// hash one byte sequence
function sha256(value) {
  return createHash("sha256").update(value).digest("hex");
}

// compare text by code point
function compareText(left, right) {
  // order unequal values deterministically
  if (left < right) {
    return -1;
  }
  // order unequal values deterministically
  if (left > right) {
    return 1;
  }
  return 0;
}

// canonicalize one private comparison value
function canonicalJson(value) {
  // retain scalar json spelling
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value);
  }
  // retain semantic array order
  if (Array.isArray(value)) {
    return "[" + value.map(
      // canonicalize one array member
      (entry) => canonicalJson(entry),
    ).join(",") + "]";
  }
  const keys = Object.keys(value).sort(compareText);
  return "{" + keys.map(
    // canonicalize one object member
    (key) => JSON.stringify(key) + ":" + canonicalJson(value[key]),
  ).join(",") + "}";
}

// require one exact private key set
function hasExactKeys(value, keys) {
  return value !== null && typeof value === "object" &&
    !Array.isArray(value) &&
    JSON.stringify(Object.keys(value).sort(compareText)) === JSON.stringify(keys);
}

// parse one exact canonical private record
function parseCanonicalRecord(value, keys) {
  // reject one noncanonical serialized record
  if (typeof value !== "string") {
    throw guardError();
  }
  const parsed = JSON.parse(value);
  // reject one incomplete or noncanonical record
  if (!hasExactKeys(parsed, keys) || canonicalJson(parsed) !== value) {
    throw guardError();
  }
  return parsed;
}

