// build one exact private payload
function fixedPayload(length, prefix, suffix = "") {
  const fillLength = length - Buffer.byteLength(prefix, "utf8") -
    Buffer.byteLength(suffix, "utf8");
  // reject one invalid fixed fixture definition
  if (!Number.isSafeInteger(fillLength) || fillLength < 0) {
    throw new Error(GUARD_TOKEN);
  }
  return prefix + "x".repeat(fillLength) + suffix;
}

