    childCloseScheduled: false,
    childClosed: false,
    duplicateClose: response.kind === "duplicate-close",
    stdinClosed: false,
    stdinFinished: false,
    stderrClosed: false,
    stderrEnded: false,
    stdoutClosed: false,
    stdoutEnded: false,
