    childCloseEmits: 0,
    closeCodeClass: "absent",
    closeSignalPresent: false,
    deadlineMatured: false,
    killCalls: 0,
    killAfterDeadlineMaturity: false,
    killSignalMatches: true,
    spawnThrew: false,
    stderrEmittedBytes: 0,
    stderrKilledBeforeEmitReturn: false,
    stderrNonBufferChunks: 0,
    stdinBufferIsBuffer: false,
    stdinBytes: 0,
    stdinEndCalls: 0,
    stdinFinishedAtChildClose: false,
    stdinSha256: null,
    stdinWriteCalls: 0,
