function deepHelperNodes(depth) {
  const endByteColumn = depth + 4;
  const leafOrdinal = depth + 2;
  const nodes = [
    [
      0, "module", null, null, null, null, null, null, null, "none", null,
      [], [], [["body", 0, 1]],
    ],
    [
      1, "expression-statement", 1, 0, 1, endByteColumn, null, null, null,
      "none", null, [], [], [["value", 0, 2]],
    ],
  ];
  // append every nested unary node
  for (let index = 0; index < depth; index += 1) {
    const ordinal = index + 2;
    nodes.push([
      ordinal, "unary-operator", 1, index, 1, endByteColumn, null, null, null,
      "none", null, ["operator.unary-plus"], [], [["operand", 0, ordinal + 1]],
    ]);
  }
  nodes.push([
    leafOrdinal, "name", 1, depth, 1, endByteColumn, "item", null, null,
    "none", null, ["context.load"], [], [],
  ]);
  return nodes;
}

