test(
  "Python fact kinds and child order follow the exact AST contract",
  // verify exact fact mapping and order
  async () => {
    const orderedSource = [
      "@decorate",
      "def sample():",
      "    raise Problem()",
      "    value",
      "",
    ].join("\n");
    const deleteSource = "del value\n";
    const sources = [
      physicalSource("python", "fixture/ast-order.py", orderedSource),
      physicalSource("python", "fixture/delete.py", deleteSource),
    ];
    sources.sort(
      // retain exact frontend batch order
      (left, right) => compareText(left.language, right.language)
        || compareText(left.path, right.path)
        || compareText(left.rawSha256, right.rawSha256),
    );
    const result = await analyzeBackendNonmoduleSourcesBatch({ sources });
    const orderedFacts = result.semanticFacts.filter(
      // retain only the AST order fixture
      (fact) => fact.site.path === "fixture/ast-order.py",
    );
    const functionFact = orderedFacts.find(
      // locate the decorated function
      (fact) => fact.factKind === "function"
        && fact.attributes.identifier === "sample",
    );
    assert.notEqual(functionFact, undefined);
    assert.deepEqual(
      functionFact.childEdges.map(
        // project exact AST field order
        (edge) => edge.role,
      ),
      ["body", "body", "decorator_list"],
    );
    const raiseFact = orderedFacts.find(
      // locate the raise statement fact
      (fact) => fact.site.startUtf16 === orderedSource.indexOf("raise Problem()"),
    );
    const expressionStatementFact = orderedFacts.find(
      // locate the expression statement fact
      (fact) => fact.site.startUtf16 === orderedSource.indexOf("value"),
    );
    assert.equal(raiseFact.factKind, "control");
    assert.equal(expressionStatementFact.factKind, "control");
    assert.equal(
      result.semanticFacts.some(
        // forbid facts from unsupported delete syntax
        (fact) => fact.site.path === "fixture/delete.py",
      ),
      false,
    );
    assertUnsupportedGap(result);
  },
);

