test(
  "literal Python node-e payloads retain private derived custody and never execute",
  // verify derived source custody
  async () => {
    const directory = await mkdtemp(join(tmpdir(), "weather-source-poison-"));
    const marker = join(directory, "executed");
    const sentinel = "private-derived-sentinel-7e0bcf";
    const javascript = `await import("node:fs/promises").then((fs) => fs.writeFile(${JSON.stringify(marker)}, ${JSON.stringify(sentinel)})); Date.now();`;
    const sourceText = [
      "import subprocess",
      `bridge = ${JSON.stringify(javascript)}`,
      "subprocess.run(['node', '--input-type=module', '-e', bridge], check=True)",
      "",
    ].join("\n");

    // always remove poison markers
    try {
      assert.equal(Buffer.byteLength(FIXED_BRIDGE_SOURCE), 64);
      assert.equal(
        sha256(Buffer.from(FIXED_BRIDGE_SOURCE)),
        "95292593cca97092865b5184d4a7e72b47e17fcc38e5540d23674798a0cc897f",
      );
      const fixedSource = physicalSource(
        "python",
        "fixture/bridge.py",
        FIXED_BRIDGE_SOURCE,
      );
      const poisonSource = physicalSource(
        "python",
        "fixture/poison-bridge.py",
        sourceText,
      );
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [fixedSource, poisonSource],
      });
      assert.equal(result.derivedSources.length, 2);
      const fixedDerived = result.derivedSources.find(
        // locate the fixed bridge custody
        (derived) => derived.parentPath === fixedSource.path,
      );
      const poisonDerived = result.derivedSources.find(
        // locate the poison bridge custody
        (derived) => derived.parentPath === poisonSource.path,
      );
      assert.notEqual(fixedDerived, undefined);
      assert.notEqual(poisonDerived, undefined);
      assertExactKeys(poisonDerived, PRIVATE_SOURCE_KEYS);
      assert.equal(poisonDerived.sourceKind, "derived");
      assert.equal(poisonDerived.language, "javascript");
      assert.equal(poisonDerived.parentRawSha256, poisonSource.rawSha256);
      assert.equal(poisonDerived.resolutionBase, "fixture");
      assert.equal(poisonDerived.sourceText, javascript);
      assert.equal(poisonDerived.rawSha256, sha256(Buffer.from(javascript)));
      assert.equal(
        poisonDerived.derivedId,
        frame("weather-backend-derived-source/v1", {
          containerSpan: poisonDerived.containerSpan,
          language: poisonDerived.language,
          parentPath: poisonDerived.parentPath,
          parentRawSha256: poisonDerived.parentRawSha256,
          rawSha256: poisonDerived.rawSha256,
          resolutionBase: poisonDerived.resolutionBase,
        }),
      );
      assert.equal(poisonDerived.path, `derived:${poisonDerived.derivedId}`);
      assertExactKeys(poisonDerived.containerSpan, ["endUtf16", "startUtf16"]);

      assert.equal(
        fixedDerived.derivedId,
        "decace4882962718c08ada879d8fed13cab5dcc6061534d599411e2b5e1e5ba5",
      );
      assert.equal(fixedDerived.path, `derived:${fixedDerived.derivedId}`);
      assert.equal(fixedDerived.sourceText, "Date.now();");
      assert.equal(
        fixedDerived.rawSha256,
        "5742fe0e2deb1cf7f6440ffe8915ef59279554f5b03eaa9b309445f9beabd21a",
      );
      assert.deepEqual(fixedDerived.containerSpan, {
        endUtf16: 61,
        startUtf16: 48,
      });

      const fixedContainer = occurrencesOf(result, "container.python-node-e").find(
        // locate the fixed bridge container
        (occurrence) => occurrence.sourceLocator === fixedSource.path,
      );
      const poisonContainer = occurrencesOf(result, "container.python-node-e").find(
        // locate the parent custody mutation
        (occurrence) => occurrence.sourceLocator === poisonSource.path,
      );
      assert.deepEqual(fixedContainer, FIXED_CONTAINER_OCCURRENCE);
      assert.notEqual(poisonContainer, undefined);
      const fixedDerivedOccurrence = result.occurrences.find(
        // locate the fixed derived child clock
        (occurrence) => occurrence.sourceLocator === fixedDerived.path,
      );
      const poisonDerivedOccurrence = result.occurrences.find(
        // locate the derived parent mutation
        (occurrence) => occurrence.sourceLocator === poisonDerived.path
          && occurrence.surface === "ecmascript.date-now",
      );
      assert.deepEqual(fixedDerivedOccurrence, FIXED_DERIVED_OCCURRENCE);
      assert.notEqual(poisonDerivedOccurrence, undefined);
      assert.equal(
        poisonDerivedOccurrence.normalizedExpressionSha256,
        fixedDerivedOccurrence.normalizedExpressionSha256,
      );
      assert.notEqual(
        poisonDerivedOccurrence.parentOccurrenceId,
        fixedDerivedOccurrence.parentOccurrenceId,
      );
      assert.notEqual(poisonDerivedOccurrence.id, fixedDerivedOccurrence.id);
      assert.equal(publicFrontendBytes(result).includes(sentinel), false);
      assert.equal(publicFrontendBytes(result).includes(marker), false);
      await assertMissing(marker);
      assertDeepFrozen(result);
    } finally {
      await rm(directory, { force: true, recursive: true });
    }
  },
);

