test(
  "routine header defaults retain private facts without PL body ownership",
  // verify header and decoded-span custody
  async () => {
    const sourceText = [
      "CREATE FUNCTION header_default_clock(",
      "  argument timestamptz DEFAULT clock_timestamp()",
      ") RETURNS timestamptz",
      "LANGUAGE plpgsql",
      "AS $body$",
      "BEGIN",
      "  RETURN argument;",
      "END;",
      "$body$;",
      "",
    ].join("\n");
    const headerStart = sourceText.indexOf("clock_timestamp()");
    const headerEnd = headerStart + "clock_timestamp()".length;
    const result = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("sql", "fixture/header-default.sql", sourceText)],
    });
    const facts = result.semanticFacts.filter(
      // retain the header fixture facts
      (fact) => fact.site.path === "fixture/header-default.sql",
    );
    assert.equal(
      facts.some(
        // retain the routine declaration
        (fact) => fact.factKind === "function"
          && fact.attributes.identifier === "header_default_clock"),
      true,
    );
    assert.equal(
      facts.some(
        // retain the positioned parameter
        (fact) => fact.factKind === "parameter"
          && fact.attributes.identifier === "argument"),
      true,
    );
    assert.equal(
      facts.some(
        // retain the header clock fact
        (fact) => fact.factKind === "clock-expression"
          && fact.site.startUtf16 === headerStart
          && fact.site.endUtf16 === headerEnd),
      true,
    );
    assert.equal(
      result.occurrences.some(
        // forbid PL ownership of a header default
        (occurrence) => occurrence.language === "plpgsql"),
      false,
    );
    const headerOccurrences = result.occurrences.filter(
      // retain physical header ownership
      (occurrence) => occurrence.language === "sql"
        && occurrence.surface === "postgres.clock-timestamp"
        && occurrence.span.startOffsetUtf16 === headerStart,
    );
    assert.equal(headerOccurrences.length, 1);
    assert.equal(headerOccurrences[0].identityVersion, "physical-v1");
    assert.equal(
      result.occurrences.every(
        // reject invalid decoded coordinates
        (occurrence) => occurrence.span.startOffsetUtf16 >= 0
          && occurrence.span.endOffsetUtf16 >= occurrence.span.startOffsetUtf16
          && occurrence.span.endOffsetUtf16 <= sourceText.length,
      ),
      true,
    );
    assert.equal(result.diagnostics.length, 0);
  },
);

test(
  "actual migration inventory retains every SQL PLpgSQL and DO routine fact",
  // verify current procedural corpus coverage
  async () => {
    const migrationRoot = new URL(
      "../packages/database/migrations/",
      import.meta.url,
    );
    const migrationNames = (await readdir(migrationRoot)).filter(
      // retain only migration sql files
      (name) => /^\d{4}_[a-z0-9_]+\.sql$/u.test(name),
    ).sort(compareText);
    assert.equal(migrationNames.length, 23);
    const sources = await Promise.all(migrationNames.map(
      // read one reviewed migration source
      async (name) => physicalSource(
        "sql",
        `packages/database/migrations/${name}`,
        await readFile(new URL(name, migrationRoot), "utf8"),
      ),
    ));
    sources.sort(
      // retain exact frontend batch order
      (left, right) => compareText(left.language, right.language)
        || compareText(left.path, right.path)
        || compareText(left.rawSha256, right.rawSha256),
    );
    const result = await analyzeBackendNonmoduleSourcesBatch({ sources });
    const sqlRoutines = result.semanticFacts.filter(
      // retain sql-language routine facts
      (fact) => fact.language === "sql" && fact.factKind === "function",
    );
    const proceduralRoutines = result.semanticFacts.filter(
      // retain procedural routine facts
      (fact) => fact.language === "plpgsql" && fact.factKind === "function",
    );
    const doRoutines = proceduralRoutines.filter(
      // retain anonymous do blocks
      (fact) => fact.attributes.identifier === "<anonymous>",
    );
    const namedProceduralRoutines = proceduralRoutines.filter(
      // retain named procedural routines
      (fact) => fact.attributes.identifier !== "<anonymous>",
    );
    assert.equal(sqlRoutines.length, 13);
    assert.equal(namedProceduralRoutines.length, 58);
    assert.equal(doRoutines.length, 3);
    const sourceLengths = new Map(sources.map(
      // index one migration byte-independent length
      (source) => [source.path, source.sourceText.length],
    ));
    assert.equal(
      [...sqlRoutines, ...proceduralRoutines].every(
        // require one positioned contained routine fact
        (fact) => fact.site.startUtf16 >= 0
          && fact.site.endUtf16 > fact.site.startUtf16
          && fact.site.endUtf16 <= sourceLengths.get(fact.site.path),
      ),
      true,
    );
    assert.notEqual(
      doRoutines.find(
        // retain the dynamic sql do block itself
        (fact) => fact.site.path.endsWith("0010_forecast_training_export.sql"),
      ),
      undefined,
    );
    assertUnsupportedGap(result);
  },
);

test(
  "shell constants resolve sources and clock commands without executing poison commands",
  // verify bounded shell analysis
  async () => {
    const directory = await mkdtemp(join(tmpdir(), "weather-shell-poison-"));
    const marker = join(directory, "executed");
    const sleepSource = "sleep -0.25\n";
    const timeoutSource = "timeout --signal=TERM -- 2.5 sleep 1\n";
    const sourceText = `#!/usr/bin/env bash
base="deploy/scripts"
library="\${base}/common.sh"
source "$library"
case "$1" in
  daily) verb="maintenance-daily" ;;
  monthly) verb="maintenance-monthly" ;;
esac
now=$(date -u +%s)
sleep 1
timeout 2 printf '%s' "$verb"
touch ${JSON.stringify(marker)}
`;
    assert.equal(Buffer.byteLength(sleepSource), 12);
    assert.equal(
      sha256(Buffer.from(sleepSource)),
      "43a48861ff5f3562e8c0e12a0069b63ac82de4b3a86e7295354f2123e83ad1d6",
    );
    assert.equal(Buffer.byteLength(timeoutSource), 37);
    assert.equal(
      sha256(Buffer.from(timeoutSource)),
      "c29beec0a2ec7ed6785f2277f201dc2bfb5e5206928ea17a61496413afd2c094",
    );
    // always remove shell markers
    try {
      const sources = [
        physicalSource("shell", "fixture/date.sh", "date -u +%s\n"),
        physicalSource("shell", "fixture/date-equivalent.sh", "date   '-u'   \"+%Y\"\n"),
        physicalSource("shell", "fixture/dispatch.sh", sourceText),
        physicalSource("shell", "fixture/invalid-sleep.sh", "sleep --verbose 1\n"),
        physicalSource(
          "shell",
          "fixture/invalid-timeout.sh",
          "timeout --signal= -- 2 sleep 1\n",
        ),
        physicalSource("shell", "fixture/sleep.sh", sleepSource),
        physicalSource(
          "shell",
          "fixture/timeout.sh",
          timeoutSource,
        ),
      ];
      sources.sort(
        // retain exact frontend batch order
        (left, right) => compareText(left.language, right.language)
          || compareText(left.path, right.path)
          || compareText(left.rawSha256, right.rawSha256),
      );
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources,
      });
      const dateOccurrences = occurrencesOf(result, "shell.date");
      const sleepOccurrences = occurrencesOf(result, "shell.sleep");
      const timeoutOccurrences = occurrencesOf(result, "shell.timeout");
      assert.equal(dateOccurrences.length, 3);
      assert.equal(sleepOccurrences.length, 2);
      assert.equal(timeoutOccurrences.length, 1);
      const fixedDate = dateOccurrences.find(
        // locate the fixed date vector
        (occurrence) => occurrence.sourceLocator === "fixture/date.sh",
      );
      const equivalentDate = dateOccurrences.find(
        // locate the equivalent quoted date vector
        (occurrence) => occurrence.sourceLocator === "fixture/date-equivalent.sh",
      );
      assert.equal(
        fixedDate.normalizedExpressionSha256,
        "4a46ee886f515dba08921c07c3bf9e96bd0ef425f9f3c8d803e05bc7639e5e54",
      );
      assert.equal(
        equivalentDate.normalizedExpressionSha256,
        fixedDate.normalizedExpressionSha256,
      );
      assert.notEqual(
        fixedDate.normalizedExpressionSha256,
        "634ea267fae4d4c35a63fb9d9d5c665b3fc7de0628e8adb8556ed1fe71b6b469",
      );
      const fixedSleep = sleepOccurrences.find(
        // locate the negative duration vector
        (occurrence) => occurrence.sourceLocator === "fixture/sleep.sh",
      );
      assert.equal(
        fixedSleep.normalizedExpressionSha256,
        "1fa16d5e02c0dff5141c029f233cc9941f759d9554bc032b0e1d727fc172a333",
      );
      const fixedTimeout = timeoutOccurrences.find(
        // locate the attached option vector
        (occurrence) => occurrence.sourceLocator === "fixture/timeout.sh",
      );
      assert.equal(
        fixedTimeout.normalizedExpressionSha256,
        "19aa7871835f2d757f69c5729c849d81f9d89ddda70a8480337d35777fa3d2d2",
      );
      assert.equal(
        result.occurrences.some(
          // forbid invalid option occurrences
          (occurrence) => occurrence.sourceLocator === "fixture/invalid-sleep.sh"
            || occurrence.sourceLocator === "fixture/invalid-timeout.sh",
        ),
        false,
      );
      assert.equal(
        result.semanticFacts.some(
          // retain the literal source edge fact
          (fact) => fact.factKind === "import"
            && fact.attributes.literalRole === "import-specifier"
            && fact.attributes.literalValue === "deploy/scripts/common.sh",
        ),
        true,
      );
      assert.equal(
        result.diagnostics.some(
          // retain unresolved poison command truthfully
          (diagnostic) => diagnostic.code === "frontend.unsupported",
        ),
        true,
      );
      await assertMissing(marker);
    } finally {
      await rm(directory, { force: true, recursive: true });
    }
  },
);

test(
  "shell bindings owners and exhaustive branches fail closed without false commands",
  // verify bounded shell binding semantics
  async () => {
    const bindingSource = [
      "library=\"fixture/common.sh\"",
      "library=$dynamic",
      "source \"$library\"",
      "clock_now() {",
      "  date -u +%s",
      "}",
      "ready && date -u +%s",
      "case \"$mode\" in",
      "  quick) delay=1 ;;",
      "  slow) delay=1 ;;",
      "  *) delay=1 ;;",
      "esac",
      "sleep \"$delay\"",
      "timeout 2 \"$verb\"",
      "",
    ].join("\n");
    const missingDefaultSource = [
      "case \"$mode\" in",
      "  quick) delay=1 ;;",
      "  slow) delay=1 ;;",
      "esac",
      "sleep \"$delay\"",
      "",
    ].join("\n");
    const missingAssignmentSource = [
      "case \"$mode\" in",
      "  quick) delay=1 ;;",
      "  *) other=1 ;;",
      "esac",
      "sleep \"$delay\"",
      "",
    ].join("\n");
    const singleQuotedSource = [
      "delay=1",
      "sleep '$delay'",
      "",
    ].join("\n");
    const sources = [
      physicalSource("shell", "fixture/bindings.sh", bindingSource),
      physicalSource("shell", "fixture/missing-assignment.sh", missingAssignmentSource),
      physicalSource("shell", "fixture/missing-default.sh", missingDefaultSource),
      physicalSource("shell", "fixture/single-quoted.sh", singleQuotedSource),
    ];
    sources.sort(
      // retain exact frontend batch order
      (left, right) => compareText(left.language, right.language)
        || compareText(left.path, right.path)
        || compareText(left.rawSha256, right.rawSha256),
    );
    const result = await analyzeBackendNonmoduleSourcesBatch({ sources });
    assert.equal(
      result.semanticFacts.some(
        // forbid one invalidated source binding
        (fact) => fact.factKind === "import"
          && fact.attributes.literalValue === "fixture/common.sh",
      ),
      false,
    );
    const dateOccurrences = occurrencesOf(result, "shell.date").filter(
      // retain only the binding fixture clocks
      (occurrence) => occurrence.sourceLocator === "fixture/bindings.sh",
    );
    assert.equal(dateOccurrences.length, 2);
    assert.deepEqual(
      dateOccurrences.map(
        // project exact lexical owners
        (occurrence) => occurrence.ownerSymbol,
      ).sort(compareText),
      ["<module>", "clock_now"],
    );
    assert.equal(
      occurrencesOf(result, "shell.sleep").filter(
        // retain the finite identical branch command
        (occurrence) => occurrence.sourceLocator === "fixture/bindings.sh",
      ).length,
      1,
    );
    assert.equal(
      occurrencesOf(result, "shell.timeout").some(
        // forbid the unresolved timeout child
        (occurrence) => occurrence.sourceLocator === "fixture/bindings.sh",
      ),
      false,
    );
    const incompletePaths = new Set([
      "fixture/missing-assignment.sh",
      "fixture/missing-default.sh",
      "fixture/single-quoted.sh",
    ]);
    assert.equal(
      occurrencesOf(result, "shell.sleep").some(
        // forbid incomplete or literal variable claims
        (occurrence) => incompletePaths.has(occurrence.sourceLocator),
      ),
      false,
    );
    assertUnsupportedGap(result);
  },
);

test(
  "shell logical alternatives and pipelines join environments without false edges",
  // verify branch and pipeline environments
  async () => {
    const divergentDurationSource = [
      "unit=s",
      "maybe && unit=m",
      "sleep \"1${unit}\"",
      "",
    ].join("\n");
    const divergentClockSource = [
      "unit=s",
      "maybe && unit=invalid",
      "sleep \"1${unit}\"",
      "",
    ].join("\n");
    const andSource = [
      "lib=fixture/a.sh",
      "maybe && lib=fixture/b.sh",
      "source \"$lib\"",
      "",
    ].join("\n");
    const orSource = [
      "lib=fixture/a.sh",
      "maybe || lib=fixture/b.sh",
      "source \"$lib\"",
      "",
    ].join("\n");
    const pipelineSource = [
      "lib=fixture/a.sh",
      "printf x | lib=fixture/b.sh",
      "source \"$lib\"",
      "",
    ].join("\n");
    const sources = [
      physicalSource("shell", "fixture/and-source.sh", andSource),
      physicalSource("shell", "fixture/divergent-clock.sh", divergentClockSource),
      physicalSource(
        "shell",
        "fixture/divergent-duration.sh",
        divergentDurationSource,
      ),
      physicalSource("shell", "fixture/or-source.sh", orSource),
      physicalSource("shell", "fixture/pipeline-source.sh", pipelineSource),
    ];
    sources.sort(
      // retain exact frontend batch order
      (left, right) => compareText(left.language, right.language)
        || compareText(left.path, right.path)
        || compareText(left.rawSha256, right.rawSha256),
    );
    const result = await analyzeBackendNonmoduleSourcesBatch({ sources });
    assert.equal(
      occurrencesOf(result, "shell.sleep").some(
        // forbid divergent duration alternatives
        (occurrence) => occurrence.sourceLocator === "fixture/divergent-clock.sh"
          || occurrence.sourceLocator === "fixture/divergent-duration.sh",
      ),
      false,
    );
    const importFacts = result.semanticFacts.filter(
      // retain static source edges
      (fact) => fact.factKind === "import",
    );
    assert.equal(
      importFacts.some(
        // forbid conditional source edges
        (fact) => fact.site.path === "fixture/and-source.sh"
          || fact.site.path === "fixture/or-source.sh"),
      false,
    );
    const pipelineImports = importFacts.filter(
      // retain the pipeline continuation source
      (fact) => fact.site.path === "fixture/pipeline-source.sh",
    );
    assert.equal(pipelineImports.length, 1);
    assert.equal(pipelineImports[0].attributes.literalValue, "fixture/a.sh");
    assertUnsupportedGap(result);
  },
);

test(
  "shell functions resolve free source bindings at call-time",
  // verify function environment timing
  async () => {
    const sourceText = [
      "lib=fixture/a.sh",
      "load_library() {",
      "  source \"$lib\"",
      "}",
      "lib=fixture/b.sh",
      "load_library",
      "",
    ].join("\n");
    const result = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", "fixture/call-time-source.sh", sourceText)],
    });
    const facts = result.semanticFacts.filter(
      // retain the call-time source fixture
      (fact) => fact.site.path === "fixture/call-time-source.sh",
    );
    assert.equal(
      facts.some(
        // retain the function declaration
        (fact) => fact.factKind === "function"
          && fact.attributes.identifier === "load_library"),
      true,
    );
    assert.equal(
      facts.some(
        // retain the function call
        (fact) => fact.factKind === "call"
          && fact.attributes.identifier === "load_library"),
      true,
    );
    const imports = facts.filter(
      // retain exact source edges
      (fact) => fact.factKind === "import",
    );
    assert.equal(imports.length <= 1, true);
    assert.equal(
      imports.some(
        // forbid the stale definition-time source
        (fact) => fact.attributes.literalValue === "fixture/a.sh"),
      false,
    );
    // accept one exact call-time edge or an honest gap
    if (imports.length === 1) {
      assert.equal(imports[0].attributes.literalValue, "fixture/b.sh");
    } else {
      assertUnsupportedGap(result);
    }
  },
);

