test(
  "shell scalar amplification and diagnostic growth stop at frozen budgets",
  // verify bounded shell work
  async () => {
    const doublingLines = ["spec=x"];
    // cross the existing literal cap safely
    for (let index = 0; index < 13; index += 1) {
      doublingLines.push('spec="$spec$spec"');
    }
    doublingLines.push('source "$spec"', "");
    const amplificationSource = doublingLines.join("\n");
    assert.equal(Buffer.byteLength(amplificationSource, "utf8") < 4096, true);
    await assert.rejects(
      // reject the resolved scalar above the literal cap
      () => analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource(
          "shell",
          "fixture/scalar-amplification.sh",
          amplificationSource,
        )],
      }),
      // require the closed bound failure
      (error) => {
        assert.equal(error.code, "frontend.bound-exceeded");
        assert.equal(error.stage, "frontend-bootstrap");
        return true;
      },
    );

    const diagnosticSource = Array.from(
      { length: 10001 },
      // build one unsupported command per diagnostic
      (_, index) => `unknown_command_${index}`,
    ).join("\n");
    assert.equal(Buffer.byteLength(diagnosticSource, "utf8") < 262144, true);
    await assert.rejects(
      // reject rather than truncate excess diagnostics
      () => analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource(
          "shell",
          "fixture/diagnostic-bound.sh",
          diagnosticSource,
        )],
      }),
      // require the closed bound failure
      (error) => {
        assert.equal(error.code, "frontend.bound-exceeded");
        return true;
      },
    );
  },
);

test(
  "reviewed shell corpus emits canonical source function control array and call facts",
  // verify current repository shell semantics
  async () => {
    const [commonSource, remoteSource] = await Promise.all([
      readFile(new URL("../deploy/scripts/common.sh", import.meta.url), "utf8"),
      readFile(new URL("../deploy/scripts/remote-ops.sh", import.meta.url), "utf8"),
    ]);
    const sources = [
      physicalSource("shell", "deploy/scripts/common.sh", commonSource),
      physicalSource("shell", "deploy/scripts/remote-ops.sh", remoteSource),
    ];
    sources.sort(
      // retain exact frontend batch order
      (left, right) => compareText(left.language, right.language)
        || compareText(left.path, right.path)
        || compareText(left.rawSha256, right.rawSha256),
    );
    const result = await analyzeBackendNonmoduleSourcesBatch({ sources });
    const commonFacts = result.semanticFacts.filter(
      // retain common library facts
      (fact) => fact.site.path === "deploy/scripts/common.sh",
    );
    const remoteFacts = result.semanticFacts.filter(
      // retain remote operation facts
      (fact) => fact.site.path === "deploy/scripts/remote-ops.sh",
    );
    const sourceFact = remoteFacts.find(
      // locate the installed common source edge
      (fact) => fact.factKind === "import"
        && fact.attributes.literalRole === "import-specifier",
    );
    assert.notEqual(sourceFact, undefined);
    assert.equal(sourceFact.attributes.literalValue, "deploy/scripts/common.sh");
    assert.equal(
      commonFacts.some(
        // retain a declared shell function
        (fact) => fact.factKind === "function"
          && fact.attributes.identifier === "normal_release_capacity_receipt",
      ),
      true,
    );
    assert.equal(
      commonFacts.some(
        // retain an array binding with its physical span
        (fact) => fact.factKind === "binding"
          && fact.site.startUtf16 === commonSource.indexOf("local -a arguments="),
      ),
      true,
    );
    assert.equal(
      remoteFacts.some(
        // retain actual branch control
        (fact) => fact.factKind === "control"),
      true,
    );
    assert.equal(
      [...commonFacts, ...remoteFacts].some(
        // retain one genuine shell call
        (fact) => fact.factKind === "call"),
      true,
    );
    assert.equal(
      result.semanticFacts.every(
        // require real source-contained spans
        (fact) => fact.site.startUtf16 >= 0
          && fact.site.endUtf16 > fact.site.startUtf16,
      ),
      true,
    );
  },
);

