test(
  "Python helper ignores PATH cwd and local module poisoning",
  // verify fixed helper bootstrap custody
  async () => {
    const directory = await mkdtemp(join(tmpdir(), "weather-python-bootstrap-"));
    const marker = join(directory, "ast-imported");
    const previousCwd = process.cwd();
    const previousPath = process.env.PATH;
    const previousLang = process.env.LANG;
    await writeFile(
      join(directory, "ast.py"),
      `from pathlib import Path\nPath(${JSON.stringify(marker)}).write_text("executed")\nraise RuntimeError("poison ast imported")\n`,
    );
    process.chdir(directory);
    process.env.PATH = directory;
    process.env.LANG = "poison-locale";
    // always restore process state
    try {
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource(
          "python",
          "fixture/bootstrap.py",
          "import datetime as dt\nvalue = dt.datetime.now()\n",
        )],
      });
      assert.equal(result.analysisProfile.pythonHelperCalls, 1);
      assert.equal(result.analysisProfile.pythonRuntime.implementation, "CPython");
      await assertMissing(marker);
    } finally {
      process.chdir(previousCwd);
      // restore an originally absent path
      if (previousPath === undefined) {
        delete process.env.PATH;
      } else {
        process.env.PATH = previousPath;
      }
      // restore an originally absent locale
      if (previousLang === undefined) {
        delete process.env.LANG;
      } else {
        process.env.LANG = previousLang;
      }
      await rm(directory, { force: true, recursive: true });
    }
  },
);

