test(
  "spawn stdout admits the exact cap and kills synchronously on the first excess",
  // verify independent stdout custody
  async () => {
    const source = physicalSource(
      "python",
      "fixture/stdout-boundary.py",
      "pass\n",
    );
    const responses = [
      { kind: "stdout-exact-cap" },
      { kind: "stdout-overflow-one" },
      { kind: "stdout-overflow-split" },
    ];
    const isolated = runIsolatedFrontendScenario({
      attempts: responses.map(
        // bind one source to each stdout boundary
        () => ({ sources: [source] }),
      ),
      mode: "synthetic",
      responses,
    });
    assert.equal(isolated.calls, responses.length);
    assert.equal(isolated.originalCalls, 0);
    assert.equal(isolated.forbiddenTransportCalls, 0);
    assert.equal(isolated.outcomes.length, responses.length);
    assertSanitizedTransportFailure(isolated.outcomes[0]);
    assertSanitizedTransportFailure(
      isolated.outcomes[1],
      "frontend.bound-exceeded",
    );
    assertSanitizedTransportFailure(
      isolated.outcomes[2],
      "frontend.bound-exceeded",
    );
    const [exact, oneChunk, split] = isolated.syntheticCalls;
    assert.equal(exact.stdoutEmittedBytes, PYTHON_HELPER_STDOUT_CAP);
    assert.equal(exact.killCalls, 0);
    assert.equal(oneChunk.stdoutEmittedBytes, PYTHON_HELPER_STDOUT_CAP + 1);
    assert.equal(oneChunk.stdoutKilledBeforeEmitReturn, true);
    assert.equal(oneChunk.killCalls, 1);
    assert.equal(oneChunk.killSignalMatches, true);
    assert.equal(split.stdoutEmittedBytes, PYTHON_HELPER_STDOUT_CAP + 1);
    assert.equal(split.stdoutKilledBeforeEmitReturn, true);
    assert.equal(split.killCalls, 1);
    assert.equal(split.killSignalMatches, true);
    assertSyntheticCloseGate(isolated);
  },
);

