test(
  "helper child cardinality alignment and preorder reject structurally plausible trees",
  // verify exact helper ownership grammar
  async () => {
    const callSource = physicalSource(
      "python",
      "fixture/codec-call-shape.py",
      "target(value)\n",
    );
    const compareSource = physicalSource(
      "python",
      "fixture/codec-compare-shape.py",
      "left < middle < right\n",
    );
    const dictSource = physicalSource(
      "python",
      "fixture/codec-dict-shape.py",
      "{**values, 'key': item}\n",
    );
    const defaultSource = physicalSource(
      "python",
      "fixture/codec-default-shape.py",
      "def sample(first, second=1):\n    pass\n",
    );
    const optionalSource = physicalSource(
      "python",
      "fixture/codec-optional-shape.py",
      "def sample():\n    return\n",
    );
    const preorderSource = physicalSource(
      "python",
      "fixture/codec-preorder-shape.py",
      "item\npass\n",
    );
    const cases = [
      {
        ok: true,
        response: helperResponse(dictSource, nullableDictHelperNodes()),
        source: dictSource,
      },
      {
        ok: true,
        response: helperResponse(optionalSource, optionalReturnHelperNodes()),
        source: optionalSource,
      },
      {
        ok: false,
        response: mutatedHelperResponse(
          callSource,
          callHelperNodes(),
          // remove the required call target
          (nodes) => {
            nodes[2][13] = [["args", 0, 3], ["args", 1, 4]];
          },
        ),
        source: callSource,
      },
      {
        ok: false,
        response: mutatedHelperResponse(
          callSource,
          callHelperNodes(),
          // duplicate the scalar call target
          (nodes) => {
            nodes[2][13] = [["func", 0, 3], ["func", 1, 4]];
          },
        ),
        source: callSource,
      },
      {
        ok: false,
        response: mutatedHelperResponse(
          callSource,
          callHelperNodes(),
          // create one noncontiguous argument index
          (nodes) => {
            nodes[2][13][1][1] = 1;
          },
        ),
        source: callSource,
      },
      {
        ok: false,
        response: mutatedHelperResponse(
          compareSource,
          compareHelperNodes(),
          // remove the required comparison left operand
          (nodes) => {
            nodes[2][11].push("operator.less-than");
            nodes[2][13] = [
              ["comparators", 0, 3],
              ["comparators", 1, 4],
              ["comparators", 2, 5],
            ];
          },
        ),
        source: compareSource,
      },
      {
        ok: false,
        response: mutatedHelperResponse(
          compareSource,
          compareHelperNodes(),
          // mismatch comparison operators and operands
          (nodes) => {
            nodes[2][11].pop();
          },
        ),
        source: compareSource,
      },
      {
        ok: false,
        response: mutatedHelperResponse(
          compareSource,
          compareHelperNodes(),
          // create one noncontiguous comparator index
          (nodes) => {
            nodes[2][13][1][1] = 1;
            nodes[2][13][2][1] = 2;
          },
        ),
        source: compareSource,
      },
      {
        ok: false,
        response: mutatedHelperResponse(
          dictSource,
          nullableDictHelperNodes(),
          // mismatch dict keys and aligned values
          (nodes) => {
            nodes[2][13] = [
              ["keys", 0, 4],
              ["keys", 1, 3],
              ["values", 1, 5],
            ];
          },
        ),
        source: dictSource,
      },
      {
        ok: false,
        response: mutatedHelperResponse(
          defaultSource,
          alignedDefaultHelperNodes(),
          // remove the required function body
          (nodes) => {
            nodes[1][13] = [["decorator_list", 0, 5]];
          },
        ),
        source: defaultSource,
      },
      {
        ok: false,
        response: mutatedHelperResponse(
          defaultSource,
          alignedDefaultHelperNodes(),
          // move one positional default off the right edge
          (nodes) => {
            nodes[1][12][0][5] = 4;
            nodes[1][12][1][5] = null;
          },
        ),
        source: defaultSource,
      },
      {
        ok: false,
        response: helperResponse(preorderSource, nonpreorderHelperNodes()),
        source: preorderSource,
      },
    ];
    const isolated = runIsolatedFrontendScenario({
      attempts: cases.map(
        // bind one exact helper source
        (entry) => ({ sources: [entry.source] }),
      ),
      mode: "synthetic",
      responses: cases.map(
        // bind one exact helper response
        (entry) => ({ stderr: "", stdout: entry.response }),
      ),
    });
    assert.equal(isolated.calls, cases.length);
    assert.equal(isolated.originalCalls, 0);
    assert.equal(isolated.forbiddenTransportCalls, 0);
    assert.equal(isolated.outcomes.length, cases.length);
    // verify each exact structural outcome
    for (let index = 0; index < cases.length; index += 1) {
      const outcome = isolated.outcomes[index];
      assert.equal(outcome.ok, cases[index].ok);
      // retain closed failure taxonomy
      if (!cases[index].ok) {
        assert.equal(outcome.error.code, "frontend.invalid-output");
        assert.equal(outcome.error.stage, "frontend-bootstrap");
        assert.equal(outcome.error.guardTokenSeen, false);
      }
    }
  },
);

test(
  "helper DTO validation rejects scalar association tree and resource corruption",
  // verify total helper validation
  async () => {
    const aliasSource = physicalSource(
      "python",
      "fixture/codec-alias.py",
      "import datetime as dt\n",
    );
    const formattedSource = physicalSource(
      "python",
      "fixture/codec-formatted.py",
      "value = f\"{item!r}\"\n",
    );
    const literalSource = physicalSource(
      "python",
      "fixture/codec-literal.py",
      "value = 1\n",
    );
    const functionSource = physicalSource(
      "python",
      "fixture/codec-function.py",
      "def sample(value=1):\n    pass\n",
    );
    const backwardSource = physicalSource(
      "python",
      "fixture/codec-backward.py",
      "1\n",
    );
    const depth = 257;
    const deepSource = physicalSource(
      "python",
      "fixture/codec-deep.py",
      `${"+".repeat(depth)}item\n`,
    );
    const nodeCapSource = physicalSource(
      "python",
      "fixture/codec-node-cap.py",
      "pass\n",
    );
    const faults = [
      syntheticHelperFault(
        aliasSource,
        aliasHelperNodes(),
        // reject a module identifier
        (nodes) => {
          nodes[0][6] = "module";
        },
      ),
      syntheticHelperFault(
        aliasSource,
        aliasHelperNodes(),
        // reject an import identifier
        (nodes) => {
          nodes[1][6] = "datetime";
        },
      ),
      syntheticHelperFault(
        functionSource,
        functionHelperNodes(),
        // reject a missing function identifier
        (nodes) => {
          nodes[1][6] = null;
        },
      ),
      syntheticHelperFault(
        aliasSource,
        aliasHelperNodes(),
        // reject context on an alias
        (nodes) => {
          nodes[2][11] = ["context.load"];
        },
      ),
      syntheticHelperFault(
        formattedSource,
        formattedHelperNodes(),
        // reject a missing name context
        (nodes) => {
          nodes[5][11] = [];
        },
      ),
      syntheticHelperFault(
        formattedSource,
        formattedHelperNodes(),
        // reject multiple name contexts
        (nodes) => {
          nodes[5][11] = ["context.load", "context.store"];
        },
      ),
      syntheticHelperFault(
        literalSource,
        literalHelperNodes(),
        // reject a noncanonical boolean literal
        (nodes) => {
          nodes[3][8] = "boolean";
          nodes[3][10] = "truth";
        },
      ),
      syntheticHelperFault(
        literalSource,
        literalHelperNodes(),
        // reject a unicode prefix on an integer
        (nodes) => {
          nodes[3][6] = "literal-prefix.unicode";
        },
      ),
      syntheticHelperFault(
        formattedSource,
        formattedHelperNodes(),
        // reject literal custody on formatted value
        (nodes) => {
          nodes[4][8] = "string";
          nodes[4][9] = "semantic-constant";
          nodes[4][10] = "private-formatted-literal";
        },
      ),
      syntheticHelperFault(
        functionSource,
        functionHelperNodes(),
        // reject function associations on a module
        (nodes) => {
          nodes[0][12] = [["parameter", 0, null, "positional", 2, 3, null]];
        },
      ),
      syntheticHelperFault(
        functionSource,
        functionHelperNodes(),
        // reject a null positional parameter
        (nodes) => {
          nodes[1][12][0][4] = null;
        },
      ),
      syntheticHelperFault(
        functionSource,
        functionHelperNodes(),
        // reject reordered parameter associations
        (nodes) => {
          [nodes[1][12][0], nodes[1][12][1]] = [
            nodes[1][12][1],
            nodes[1][12][0],
          ];
        },
      ),
      syntheticHelperFault(
        functionSource,
        functionHelperNodes(),
        // reject a default mapped to the body
        (nodes) => {
          nodes[1][12][0][5] = 4;
        },
      ),
      syntheticHelperFault(
        aliasSource,
        aliasHelperNodes(),
        // reject a self cycle
        (nodes) => {
          nodes[0][13] = [["body", 0, 0]];
        },
      ),
      syntheticHelperFault(
        aliasSource,
        aliasHelperNodes(),
        // reject one shared child
        (nodes) => {
          nodes[0][13] = [["body", 0, 1], ["body", 1, 1]];
        },
      ),
      syntheticHelperFault(
        aliasSource,
        aliasHelperNodes(),
        // reject unreachable nodes
        (nodes) => {
          nodes[0][13] = [];
        },
      ),
      syntheticHelperFault(
        backwardSource,
        backwardHelperNodes(),
        // preserve one backward preorder tree
        () => {},
      ),
      syntheticHelperFault(
        aliasSource,
        aliasHelperNodes(),
        // reject a nonmodule root
        (nodes) => {
          nodes.splice(0, nodes.length, [
            0, "pass", 1, 0, 1, 4, null, null, null, "none", null, [], [], [],
          ]);
        },
      ),
      syntheticHelperFault(
        aliasSource,
        aliasHelperNodes(),
        // reject a second module
        (nodes) => {
          nodes.push([
            3, "module", null, null, null, null, null, null, null, "none",
            null, [], [], [],
          ]);
        },
      ),
      syntheticHelperFault(
        deepSource,
        deepHelperNodes(depth),
        // preserve the over-depth tree
        () => {},
        "frontend.bound-exceeded",
      ),
      syntheticHelperFault(
        nodeCapSource,
        nodeCapHelperNodes(250001),
        // preserve the over-node-cap response
        () => {},
        "frontend.bound-exceeded",
      ),
    ];
    const synthetic = runIsolatedFrontendScenario({
      attempts: faults.map(
        // bind one source to each hostile response
        (fault) => ({ sources: [fault.source] }),
      ),
      mode: "synthetic",
      responses: faults.map(
        // retain one closed hostile response
        (fault) => fault.response,
      ),
    });
    assert.equal(synthetic.calls, faults.length);
    assert.equal(synthetic.originalCalls, 0);
    assert.equal(synthetic.forbiddenTransportCalls, 0);
    assert.equal(synthetic.responseCursor, faults.length);
    assert.equal(synthetic.outcomes.length, faults.length);
    // verify every hostile response fails closed
    for (let index = 0; index < faults.length; index += 1) {
      const outcome = synthetic.outcomes[index];
      assert.equal(outcome.ok, false);
      assert.equal(outcome.error.code, faults[index].code);
      assert.equal(outcome.error.guardTokenSeen, false);
      assert.equal(outcome.error.messageMatchesCode, true);
      assert.equal(outcome.error.nameIsError, true);
      assert.equal(outcome.error.stage, "frontend-bootstrap");
      assert.equal(JSON.stringify(outcome).includes("private-formatted-literal"), false);
    }
  },
);

test(
  "unsupported syntax and bound violations fail with sanitized diagnostics",
  // verify hostile frontend failures
  async () => {
    const sentinel = "private-error-sentinel-c3d4";
    const malformed = physicalSource(
      "python",
      "fixture/malformed.py",
      `match value:\n    case {${JSON.stringify(sentinel)}: captured}:\n        pass\n`,
    );
    const result = await analyzeBackendNonmoduleSourcesBatch({ sources: [malformed] });
    assert.equal(
      result.diagnostics.some(
        // require the closed unsupported diagnostic
        (diagnostic) => diagnostic.code === "frontend.unsupported"
          && diagnostic.messageId === diagnostic.code
          && diagnostic.dimension === "frontend"
          && diagnostic.severity === "gap",
      ),
      true,
    );
    assert.equal(publicFrontendBytes(result).includes(sentinel), false);

    const aliasSource = physicalSource(
      "python",
      "fixture/alias-invalid.py",
      "import datetime as dt\n",
    );
    const formattedSource = physicalSource(
      "python",
      "fixture/formatted-invalid.py",
      "value = f\"{item!r}\"\n",
    );
    const responses = [
      {
        stderr: "",
        stdout: mutatedHelperResponse(
          aliasSource,
          aliasHelperNodes(),
          // remove one required tuple member
          (nodes) => nodes[2].pop(),
        ),
      },
      {
        stderr: "",
        stdout: mutatedHelperResponse(
          aliasSource,
          aliasHelperNodes(),
          // replace one integer with text
          (nodes) => {
            nodes[2][0] = "2";
          },
        ),
      },
      {
        stderr: "",
        stdout: mutatedHelperResponse(
          aliasSource,
          aliasHelperNodes(),
          // exceed the safe integer range
          (nodes) => {
            nodes[2][0] = Number.MAX_SAFE_INTEGER + 1;
          },
        ),
      },
      {
        stderr: "",
        stdout: mutatedHelperResponse(
          aliasSource,
          aliasHelperNodes(),
          // append one forbidden tuple member
          (nodes) => nodes[2].push(null),
        ),
      },
      {
        stderr: "",
        stdout: mutatedHelperResponse(
          aliasSource,
          aliasHelperNodes(),
          // retain semantic alias values with noncanonical bytes
          (nodes) => {
            nodes[2][6] = "[\"datetime\", \"dt\"]";
          },
        ),
      },
      {
        stderr: "",
        stdout: mutatedHelperResponse(
          formattedSource,
          formattedHelperNodes(),
          // inject one unknown conversion identifier
          (nodes) => {
            nodes[4][6] = "conversion.invalid";
          },
        ),
      },
      {
        stderr: "",
        stdout: mutatedHelperResponse(
          formattedSource,
          formattedHelperNodes(),
          // inject one unknown context token
          (nodes) => {
            nodes[5][11] = ["context.invalid"];
          },
        ),
      },
      {
        stderr: "",
        stdout: mutatedHelperResponse(
          formattedSource,
          formattedHelperNodes(),
          // inject one unknown operator token
          (nodes) => {
            nodes[5][11] = ["operator.invalid"];
          },
        ),
      },
      {
        stderr: "",
        stdout: mutatedHelperResponse(
          aliasSource,
          aliasHelperNodes(),
          // inject one unpaired unicode surrogate
          (nodes) => {
            nodes[2][6] = JSON.stringify(["\ud800", "dt"]);
          },
        ),
      },
      {
        stderr: "private-helper-stderr-sentinel",
        stdout: helperResponse(aliasSource, aliasHelperNodes()),
      },
      {
        stderr: "",
        stdout: "{",
      },
      {
        kind: "stdout-overflow-one",
      },
    ];
    const attempts = responses.map(
      // bind one valid source to each validator fault
      (_response, index) => ({
        sources: [index >= 5 && index <= 7 ? formattedSource : aliasSource],
      }),
    );
    const synthetic = runIsolatedFrontendScenario({
      attempts,
      mode: "synthetic",
      responses,
    });
    assert.equal(synthetic.calls, responses.length);
    assert.equal(synthetic.originalCalls, 0);
    assert.equal(synthetic.forbiddenTransportCalls, 0);
    assert.equal(synthetic.responseCursor, responses.length);
    assert.equal(synthetic.outcomes.length, responses.length);
    const expectedCodes = [
      "frontend.invalid-output",
      "frontend.invalid-output",
      "frontend.invalid-output",
      "frontend.invalid-output",
      "frontend.invalid-output",
      "frontend.invalid-output",
      "frontend.invalid-output",
      "frontend.invalid-output",
      "frontend.invalid-output",
      "frontend.invalid-output",
      "frontend.invalid-output",
      "frontend.bound-exceeded",
    ];
    // verify every fault stays sanitized and fail closed
    for (let index = 0; index < synthetic.outcomes.length; index += 1) {
      const outcome = synthetic.outcomes[index];
      assert.equal(outcome.ok, false);
      assert.equal(outcome.error.code, expectedCodes[index]);
      assert.equal(outcome.error.guardTokenSeen, false);
      assert.equal(outcome.error.messageMatchesCode, true);
      assert.equal(outcome.error.nameIsError, true);
      assert.equal(outcome.error.stage, "frontend-bootstrap");
      assert.equal(JSON.stringify(outcome).includes("private-helper-stderr-sentinel"), false);
    }

    const oversizedLiteral = "x".repeat(262145);
    await assert.rejects(
      // reject a decoded payload above its cap
      () => analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource(
          "python",
          "fixture/oversized.py",
          `import subprocess\nsubprocess.run(["node", "-e", ${JSON.stringify(oversizedLiteral)}])\n`,
        )],
      }),
      (error) => {
        assert.equal(String(error).includes(oversizedLiteral.slice(0, 64)), false);
        return true;
      },
    );
  },
);

const WORK_COUNTER_FRONTEND_SCRIPT = String.raw`
import process from "node:process";

// summarize one closed counter failure
function failureSummary(error) {
  const errorCode = ["frontend.bound-exceeded", "frontend.invalid-output"].includes(
    error?.code,
  )
    ? error.code
    : "test-harness.unexpected-error";
  return {
    errorCode,
    errorStage: error?.stage === "frontend-bootstrap"
      ? error.stage
      : "test-harness",
  };
}

// run one closed work-counter batch
async function main() {
  const payload = JSON.parse(await new Promise(
    // collect one bounded parent payload
    (resolve, reject) => {
      const chunks = [];
      process.stdin.on(
        "data",
        // retain one bounded input chunk
        (chunk) => chunks.push(chunk),
      );
      process.stdin.on(
        "end",
        // decode one complete input
        () => resolve(Buffer.concat(chunks).toString("utf8")),
      );
      process.stdin.on(
        "error",
        // reject one input stream failure
        (error) => reject(error),
      );
    },
  ));
  const frontend = await import(payload.frontendModuleUrl);
  const OriginalArrayPush = Array.prototype.push;
  const OriginalMap = globalThis.Map;
  const OriginalSet = globalThis.Set;
  let counters = {
    constructorCalls: 0,
    constructorEntries: 0,
    getCalls: 0,
    hasCalls: 0,
    pairIterations: 0,
    setConstructorCalls: 0,
    setConstructorEntries: 0,
    setIterations: 0,
    tokenPropertyReads: 0,
    tokenRecords: 0,
  };

  // instrument map work after module import
  class CountingMap extends OriginalMap {
    // count one map construction
    constructor(iterable) {
      super();
      counters.constructorCalls += 1;
      // copy one provided iterable
      if (iterable !== undefined && iterable !== null) {
        // count one copied entry
        for (const entry of iterable) {
          counters.constructorEntries += 1;
          OriginalMap.prototype.set.call(this, entry[0], entry[1]);
        }
      }
    }

    // count default pair iteration
    *[Symbol.iterator]() {
      // yield one retained pair
      for (const entry of OriginalMap.prototype.entries.call(this)) {
        counters.pairIterations += 1;
        yield entry;
      }
    }

    // count explicit pair iteration
    *entries() {
      // yield one retained pair
      for (const entry of OriginalMap.prototype.entries.call(this)) {
        counters.pairIterations += 1;
        yield entry;
      }
    }

    // count explicit key iteration
    *keys() {
      // yield one retained key
      for (const entry of OriginalMap.prototype.entries.call(this)) {
        counters.pairIterations += 1;
        yield entry[0];
      }
    }

    // count explicit value iteration
    *values() {
      // yield one retained value
      for (const entry of OriginalMap.prototype.entries.call(this)) {
        counters.pairIterations += 1;
        yield entry[1];
      }
    }

    // count callback pair iteration
    forEach(callback, thisArg) {
      // visit one retained pair
      for (const [key, value] of OriginalMap.prototype.entries.call(this)) {
        counters.pairIterations += 1;
        callback.call(thisArg, value, key, this);
      }
    }

    // count one direct key lookup
    get(key) {
      counters.getCalls += 1;
      return OriginalMap.prototype.get.call(this, key);
    }

    // count one direct key probe
    has(key) {
      counters.hasCalls += 1;
      return OriginalMap.prototype.has.call(this, key);
    }
  }

  // instrument set copy work after module import
  class CountingSet extends OriginalSet {
    // count one set construction
    constructor(iterable) {
      super();
      counters.setConstructorCalls += 1;
      // copy one provided iterable
      if (iterable !== undefined && iterable !== null) {
        // count one copied value
        for (const value of iterable) {
          counters.setConstructorEntries += 1;
          OriginalSet.prototype.add.call(this, value);
        }
      }
    }

    // count default value iteration
    *[Symbol.iterator]() {
      // yield one retained value
      for (const value of OriginalSet.prototype.values.call(this)) {
        counters.setIterations += 1;
        yield value;
      }
    }

    // count explicit entry iteration
    *entries() {
      // yield one retained entry
      for (const entry of OriginalSet.prototype.entries.call(this)) {
        counters.setIterations += 1;
        yield entry;
      }
    }

    // count explicit key iteration
    *keys() {
      // yield one retained key
      for (const value of OriginalSet.prototype.values.call(this)) {
        counters.setIterations += 1;
        yield value;
      }
    }

    // count explicit value iteration
    *values() {
      // yield one retained value
      for (const value of OriginalSet.prototype.values.call(this)) {
        counters.setIterations += 1;
        yield value;
      }
    }

    // count callback value iteration
    forEach(callback, thisArg) {
      // visit one retained value
      for (const value of OriginalSet.prototype.values.call(this)) {
        counters.setIterations += 1;
        callback.call(thisArg, value, value, this);
      }
    }
  }

  // identify one owned sql token record
  function isSqlTokenRecord(value) {
    // reject nonrecords and arrays
    if (value === null || typeof value !== "object" || Array.isArray(value)) {
      return false;
    }
    const keys = Object.keys(value).sort();
    return keys.length === 4 &&
      keys[0] === "end" && keys[1] === "start" &&
      keys[2] === "type" && keys[3] === "value";
  }

  // proxy one owned sql token record
  function countedSqlToken(value) {
    // preserve every non-token value
    if (!isSqlTokenRecord(value)) {
      return value;
    }
    counters.tokenRecords += 1;
    return new Proxy(value, {
      // count structural token reads
      get(target, property, receiver) {
        // count only grammar-discriminating properties
        if (property === "type" || property === "value") {
          counters.tokenPropertyReads += 1;
        }
        return Reflect.get(target, property, receiver);
      },
    });
  }

  globalThis.Map = CountingMap;
  globalThis.Set = CountingSet;
  // wrap test-owned token insertions
  Array.prototype.push = function (...items) {
    return Reflect.apply(
      OriginalArrayPush,
      this,
      items.map(
        // wrap only owned sql token records
        (item) => countedSqlToken(item),
      ),
    );
  };
  const summaries = [];
  let calibration = null;
  let setCalibration = null;
  let tokenCalibration = null;
  // restore the global before serialization
  try {
    const calibrationOriginal = new OriginalMap([
      ["first", 1],
      ["second", 2],
    ]);
    const calibrationMap = new CountingMap(calibrationOriginal);
    // count one known instrumented iteration
    for (const _entry of calibrationMap) {
      // consume one calibration pair
    }
    calibration = {
      constructorCalls: counters.constructorCalls,
      constructorEntries: counters.constructorEntries,
      pairIterations: counters.pairIterations,
    };
    const calibrationOriginalSet = new OriginalSet(["first", "second"]);
    const calibrationSet = new CountingSet(calibrationOriginalSet);
    // count one known instrumented set iteration
    for (const _value of calibrationSet) {
      // consume one calibration value
    }
    setCalibration = {
      constructorCalls: counters.setConstructorCalls,
      constructorEntries: counters.setConstructorEntries,
      iterations: counters.setIterations,
    };
    const calibrationTokens = [];
    calibrationTokens.push({ end: 1, start: 0, type: "identifier", value: "x" });
    const calibrationToken = calibrationTokens[0];
    void calibrationToken.type;
    void calibrationToken.value;
    tokenCalibration = {
      propertyReads: counters.tokenPropertyReads,
      records: counters.tokenRecords,
    };
    counters = {
      constructorCalls: 0,
      constructorEntries: 0,
      getCalls: 0,
      hasCalls: 0,
      pairIterations: 0,
      setConstructorCalls: 0,
      setConstructorEntries: 0,
      setIterations: 0,
      tokenPropertyReads: 0,
      tokenRecords: 0,
    };
    // analyze each independent work witness
    for (const scenario of payload.scenarios) {
      counters = {
        constructorCalls: 0,
        constructorEntries: 0,
        getCalls: 0,
        hasCalls: 0,
        pairIterations: 0,
        setConstructorCalls: 0,
        setConstructorEntries: 0,
        setIterations: 0,
        tokenPropertyReads: 0,
        tokenRecords: 0,
      };
      // capture one sanitized scenario outcome
      try {
        const result = await frontend.analyzeBackendNonmoduleSourcesBatch({
          sources: [scenario.source],
        });
        summaries.push({
          bindingFactCount: result.semanticFacts.filter(
            // count one retained binding fact
            (fact) => fact.factKind === "binding",
          ).length,
          callFactCount: result.semanticFacts.filter(
            // count one retained call fact
            (fact) => fact.factKind === "call",
          ).length,
          clockOccurrenceCount: result.occurrences.filter(
            // count one candidate clock occurrence
            (occurrence) => occurrence.countsAsClockCandidate,
          ).length,
          controlFactCount: result.semanticFacts.filter(
            // count one retained control fact
            (fact) => fact.factKind === "control",
          ).length,
          counters: { ...counters },
          derivedSourceCount: result.derivedSources.length,
          diagnosticCount: result.diagnostics.length,
          expressionFactCount: result.semanticFacts.filter(
            // count one retained expression fact
            (fact) => fact.factKind === "expression",
          ).length,
          factCount: result.semanticFacts.length,
          functionFactCount: result.semanticFacts.filter(
            // count one retained function fact
            (fact) => fact.factKind === "function",
          ).length,
          id: scenario.id,
          occurrenceCount: result.occurrences.length,
          ok: true,
          unsupportedDiagnosticCount: result.diagnostics.filter(
            // count one sanitized frontend gap
            (diagnostic) => diagnostic.code === "frontend.unsupported",
          ).length,
        });
      } catch (error) {
        // retain one closed failure
        summaries.push({
          counters: { ...counters },
          ...failureSummary(error),
          id: scenario.id,
          ok: false,
        });
      }
    }
  } finally {
    Array.prototype.push = OriginalArrayPush;
    globalThis.Map = OriginalMap;
    globalThis.Set = OriginalSet;
  }
  process.stdout.write(JSON.stringify({
    calibration,
    ok: true,
    setCalibration,
    summaries,
    tokenCalibration,
  }));
}

main().catch(
  // emit one closed harness failure
  () => process.stdout.write(JSON.stringify({
    errorCode: "test-harness.unexpected-error",
    errorStage: "test-harness",
    ok: false,
  })),
);
`;

// run bounded frontend work witnesses
function runFrontendWorkCounterScenarios(scenarios) {
  const run = spawnSync(
    "/bin/sh",
    [
      "-c",
      "ulimit -c 0 || exit 125\nexec \"$@\"",
      "weather-frontend-work-counter",
      process.execPath,
      "--max-old-space-size=128",
      "--input-type=module",
      "-e",
      WORK_COUNTER_FRONTEND_SCRIPT,
    ],
    {
      cwd: REPOSITORY_ROOT,
      encoding: "utf8",
      input: JSON.stringify({
        frontendModuleUrl: FRONTEND_MODULE_URL,
        scenarios,
      }),
      killSignal: "SIGKILL",
      maxBuffer: 1024 * 1024,
      timeout: 15_000,
    },
  );
  let summary = null;
  // parse only one successful closed summary
  if (run.error === undefined && run.status === 0) {
    // decode one closed child result
    try {
      summary = JSON.parse(run.stdout);
    } catch {
      // reject one malformed child result
      summary = null;
    }
  }
  return {
    signal: run.signal,
    spawnFailed: run.error !== undefined,
    status: run.status,
    stderrBytes: Buffer.byteLength(run.stderr ?? "", "utf8"),
    stdoutBytes: Buffer.byteLength(run.stdout ?? "", "utf8"),
    summary,
  };
}

test(
  "PLpgSQL rejects unordered duplicate and recursively malformed SQL transactionally",
  // verify closed sql grammar
  async () => {
    const malformedBodies = [
      [
        "unordered-clauses",
        "SELECT current_timestamp WHERE TRUE FROM pg_catalog.pg_class;",
      ],
      [
        "duplicate-clauses",
        "SELECT current_timestamp FROM pg_catalog.pg_class FROM pg_catalog.pg_type;",
      ],
      ["with-junk", "WITH junk SELECT current_timestamp;"],
      ["nested-select", "SELECT (SELECT current_timestamp FROM);"],
      [
        "missing-later-then",
        [
          "selected_at := CASE",
          "  WHEN TRUE THEN current_timestamp",
          "  WHEN FALSE",
          "END;",
        ].join("\n"),
      ],
      [
        "duplicate-else",
        [
          "selected_at := CASE",
          "  WHEN TRUE THEN current_timestamp",
          "  ELSE current_timestamp",
          "  ELSE current_timestamp",
          "END;",
        ].join("\n"),
      ],
    ];
    // isolate each transactional failure
    for (const [name, body] of malformedBodies) {
      const path = `fixture/sql-${name}.sql`;
      const sourceText = [
        `CREATE FUNCTION malformed_${name.replaceAll("-", "_")}()`,
        "RETURNS timestamptz LANGUAGE plpgsql",
        "AS $body$",
        "DECLARE",
        "  selected_at timestamptz;",
        "BEGIN",
        body,
        "  RETURN selected_at;",
        "END;",
        "$body$;",
        "",
      ].join("\n");
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("sql", path, sourceText)],
      });
      assert.equal(
        result.occurrences.some(
          // forbid one malformed pl provider
          (occurrence) => occurrence.language === "plpgsql"
            && occurrence.sourceLocator === path,
        ),
        false,
      );
      assert.equal(
        result.semanticFacts.some(
          // forbid one malformed pl fact
          (fact) => fact.language === "plpgsql" && fact.site.path === path,
        ),
        false,
      );
      assertUnsupportedGap(result);
    }
  },
);

test(
  "PLpgSQL accepts closed CTE nested query and CASE grammar",
  // verify valid sql grammar
  async () => {
    const path = "fixture/sql-closed-positive.sql";
    const sourceText = [
      "CREATE FUNCTION closed_query_clock()",
      "RETURNS timestamptz LANGUAGE plpgsql",
      "AS $body$",
      "DECLARE",
      "  selected_at timestamptz;",
      "BEGIN",
      "  WITH clock_value AS (",
      "    SELECT current_timestamp AS value",
      "  )",
      "  SELECT value INTO selected_at FROM clock_value;",
      "  SELECT (SELECT current_timestamp FROM pg_catalog.pg_class LIMIT 1)",
      "    INTO selected_at;",
      "  selected_at := CASE",
      "    WHEN TRUE THEN current_timestamp",
      "    WHEN FALSE THEN CURRENT_DATE",
      "    ELSE current_timestamp",
      "  END;",
      "  RETURN selected_at;",
      "END;",
      "$body$;",
      "",
    ].join("\n");
    const result = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("sql", path, sourceText)],
    });
    const providers = result.occurrences.filter(
      // retain positioned pl providers
      (occurrence) => occurrence.language === "plpgsql"
        && occurrence.sourceLocator === path,
    );
    assert.equal(
      providers.filter(
        // retain current timestamp reads
        (occurrence) => occurrence.surface === "postgres.current-timestamp",
      ).length,
      4,
    );
    assert.equal(
      providers.filter(
        // retain current date reads
        (occurrence) => occurrence.surface === "postgres.current-date",
      ).length,
      1,
    );
    assert.equal(
      result.semanticFacts.some(
        // retain the valid routine declaration
        (fact) => fact.language === "plpgsql"
          && fact.site.path === path
          && fact.factKind === "function"
          && fact.attributes.identifier === "closed_query_clock",
      ),
      true,
    );
    assert.equal(result.diagnostics.length, 0);
  },
);

test(
  "shell wrapper value options cannot transfer node eval custody",
  // verify closed wrapper parsing
  async () => {
    const sentinel = "private-wrapper-node-e-sentinel-7d4c";
    const negativeFixtures = [
      ["fixture/sudo-value-option.sh", `sudo -u node -e ${JSON.stringify(sentinel)}\n`],
      [
        "fixture/sudo-user-alias.sh",
        `sudo --user=node node -e ${JSON.stringify(sentinel)}\n`,
      ],
      [
        "fixture/sudo-non-interactive-alias.sh",
        `sudo --non-interactive node -e ${JSON.stringify(sentinel)}\n`,
      ],
      [
        "fixture/setpriv-value-option.sh",
        `setpriv --reuid node -e ${JSON.stringify(sentinel)}\n`,
      ],
      [
        "fixture/setpriv-reordered-options.sh",
        `setpriv --regid=10002 --reuid=10002 --clear-groups node -e ${JSON.stringify(sentinel)}\n`,
      ],
      [
        "fixture/setpriv-conflicting-option.sh",
        `setpriv --reuid=10002 --reuid=10003 --regid=10002 --clear-groups node -e ${JSON.stringify(sentinel)}\n`,
      ],
      [
        "fixture/setpriv-conflicting-groups.sh",
        `setpriv --reuid=10002 --regid=10002 --clear-groups --keep-groups node -e ${JSON.stringify(sentinel)}\n`,
      ],
      [
        "fixture/setpriv-empty-value.sh",
        `setpriv --reuid= --regid=10002 --clear-groups node -e ${JSON.stringify(sentinel)}\n`,
      ],
      [
        "fixture/setpriv-missing-child.sh",
        "exec setpriv --reuid=10002 --regid=10002 --clear-groups\n",
      ],
      ["fixture/sudo-missing-child.sh", "exec sudo -n\n"],
      [
        "fixture/sudo-second-end-options.sh",
        `exec sudo -n -- -- node -e ${JSON.stringify(sentinel)}\n`,
      ],
      [
        "fixture/sudo-option-after-end-options.sh",
        `exec sudo -n -- -u node -e ${JSON.stringify(sentinel)}\n`,
      ],
      [
        "fixture/nested-privileged-wrapper.sh",
        `exec sudo -n setpriv --reuid=10002 --regid=10002 --clear-groups node -e ${JSON.stringify(sentinel)}\n`,
      ],
    ];
    // isolate each unresolved wrapper child
    for (const [path, sourceText] of negativeFixtures) {
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      assert.equal(result.derivedSources.length, 0);
      assert.equal(
        result.occurrences.some(
          // forbid invented node custody
          (occurrence) => occurrence.surface === "container.shell-node-e"
            || occurrence.sourceLocator.startsWith("derived:"),
        ),
        false,
      );
      assert.equal(
        result.semanticFacts.some(
          // forbid private embedded source custody
          (fact) => fact.site.path === path
            && fact.factKind === "embedded-source",
        ),
        false,
      );
      assert.equal(
        result.semanticFacts.some(
          // forbid one downstream node call
          (fact) => fact.site.path === path
            && fact.factKind === "call"
            && fact.attributes.identifier === "node",
        ),
        false,
      );
      assert.equal(
        result.semanticFacts.some(
          // forbid one downstream source edge
          (fact) => fact.site.path === path && fact.factKind === "import",
        ),
        false,
      );
      assertUnsupportedGap(result);
      assert.equal(publicFrontendBytes(result).includes(sentinel), false);
    }

    const positivePath = "fixture/setpriv-attached-options.sh";
    const positive = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource(
        "shell",
        positivePath,
        "exec setpriv --reuid=10002 --regid=10002 --clear-groups node -e \"Date.now();\"\n",
      )],
    });
    assert.equal(positive.derivedSources.length, 1);
    assert.equal(positive.derivedSources[0].sourceText, "Date.now();");
    const wrappedContainer = positive.occurrences.find(
      // retain one admitted node container
      (occurrence) => occurrence.surface === "container.shell-node-e"
        && occurrence.sourceLocator === positivePath,
    );
    assert.notEqual(wrappedContainer, undefined);
    assert.equal(positive.diagnostics.length, 0);

    const changedIdentity = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource(
        "shell",
        "fixture/setpriv-attached-options-changed-identity.sh",
        "exec setpriv --reuid=10003 --regid=10002 --clear-groups node -e \"Date.now();\"\n",
      )],
    });
    const changedIdentityContainer = changedIdentity.occurrences.find(
      // retain one changed-identity container
      (occurrence) => occurrence.surface === "container.shell-node-e",
    );
    assert.notEqual(changedIdentityContainer, undefined);
    assert.equal(
      changedIdentityContainer.normalizedExpressionSha256,
      wrappedContainer.normalizedExpressionSha256,
    );
    assert.equal(changedIdentity.diagnostics.length, 0);

    const bare = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource(
        "shell",
        "fixture/bare-node-e.sh",
        "node -e \"Date.now();\"\n",
      )],
    });
    const bareContainer = bare.occurrences.find(
      // retain one bare node container
      (occurrence) => occurrence.surface === "container.shell-node-e",
    );
    assert.notEqual(bareContainer, undefined);
    assert.notEqual(
      wrappedContainer.normalizedExpressionSha256,
      bareContainer.normalizedExpressionSha256,
    );
    assert.equal(bare.diagnostics.length, 0);
  },
);

test(
  "SQL nested query validation performs linear delimiter ownership work",
  // verify bounded query work
  () => {
    const sizes = [0, 64, 128];
    const scenarios = sizes.map(
      // build one bounded query-work witness
      (size) => {
        const declarations = Array.from(
          { length: size },
          // build one positioned local initializer
          (_value, index) => `  local_${index} integer := ${index};`,
        );
        const queries = Array.from(
          { length: size },
          // build one independent static query
          (_value, index) => `(SELECT ${index + 1})`,
        );
        const expression = queries.length === 0
          ? "ARRAY[1]"
          : `ARRAY[${queries.join(", ")}]`;
        const sourceText = [
          `CREATE FUNCTION query_work_${size}()`,
          "RETURNS integer LANGUAGE plpgsql",
          "AS $body$",
          "DECLARE",
          ...declarations,
          "  selected_values integer[];",
          "BEGIN",
          `  selected_values := ${expression};`,
          "  RETURN 1;",
          "END;",
          "$body$;",
          "",
        ].join("\n");
        return {
          id: `sql-${size}`,
          source: physicalSource(
            "sql",
            `fixture/sql-query-work-${size}.sql`,
            sourceText,
          ),
        };
      },
    );
    const isolated = runFrontendWorkCounterScenarios(scenarios);
    assert.deepEqual(
      {
        signal: isolated.signal,
        spawnFailed: isolated.spawnFailed,
        status: isolated.status,
        stderrBytes: isolated.stderrBytes,
      },
      { signal: null, spawnFailed: false, status: 0, stderrBytes: 0 },
    );
    assert.equal(isolated.stdoutBytes <= 1024 * 1024, true);
    assert.equal(isolated.summary?.ok, true);
    assert.deepEqual(isolated.summary.calibration, {
      constructorCalls: 1,
      constructorEntries: 2,
      pairIterations: 2,
    });
    assert.deepEqual(
      isolated.summary.summaries.map(
        // project one closed work outcome
        (summary) => [summary.id, summary.ok],
      ),
      [["sql-0", true], ["sql-64", true], ["sql-128", true]],
    );
    // verify every query witness retained real semantics
    for (let index = 0; index < sizes.length; index += 1) {
      const summary = isolated.summary.summaries[index];
      assert.equal(summary.diagnosticCount, 0);
      assert.equal(summary.unsupportedDiagnosticCount, 0);
      assert.equal(summary.derivedSourceCount, 0);
      assert.equal(summary.clockOccurrenceCount, 0);
      assert.equal(summary.functionFactCount >= 1, true);
      assert.equal(summary.bindingFactCount >= sizes[index] + 1, true);
      assert.equal(summary.expressionFactCount >= sizes[index] + 1, true);
      assert.equal(summary.controlFactCount >= 1, true);
    }
    const sqlFactCounts = isolated.summary.summaries.map(
      // project retained sql facts
      (summary) => summary.factCount,
    );
    assert.equal(sqlFactCounts[1] > sqlFactCounts[0], true);
    assert.equal(sqlFactCounts[2] > sqlFactCounts[1], true);
    const [baseline, small, large] = isolated.summary.summaries.map(
      // project query pair iterations
      (summary) => summary.counters.pairIterations,
    );
    assert.equal(small >= baseline, true);
    assert.equal(large >= small, true);
    assert.equal(large - small <= (small - baseline) * 2 + 256, true);
  },
);

