test(
  "procedural capture stays top-level PL and never leaks into LANGUAGE sql",
  // verify procedural capture context
  async () => {
    const invalidSqlBodies = [
      [
        "fixture/sql-insert-returning-into.sql",
        "INSERT INTO weather (selected_at) VALUES (current_timestamp) RETURNING selected_at INTO captured;",
      ],
      [
        "fixture/sql-update-returning-into.sql",
        "UPDATE weather SET selected_at = current_timestamp RETURNING selected_at INTO captured;",
      ],
      [
        "fixture/sql-delete-returning-into.sql",
        "DELETE FROM weather WHERE current_timestamp IS NOT NULL RETURNING selected_at INTO captured;",
      ],
      [
        "fixture/sql-select-into.sql",
        "SELECT current_timestamp INTO captured;",
      ],
    ];
    // isolate each nonprocedural capture rejection
    for (const [path, statement] of invalidSqlBodies) {
      const sourceText = [
        "CREATE FUNCTION sql_capture_invalid()",
        "RETURNS timestamptz LANGUAGE sql",
        "AS $body$",
        statement,
        "$body$;",
        "",
      ].join("\n");
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("sql", path, sourceText)],
      });
      assert.equal(
        result.occurrences.some(
          // forbid one invalid sql-body provider
          (occurrence) => occurrence.countsAsClockCandidate
            && occurrence.sourceLocator === path,
        ),
        false,
      );
      assert.equal(
        result.semanticFacts.some(
          // forbid one invalid sql-body fact
          (fact) => fact.language === "sql" && fact.site.path === path,
        ),
        false,
      );
      assertUnsupportedGap(result);
    }

    const nestedCaptures = [
      [
        "fixture/pl-nested-select-into.sql",
        "SELECT (SELECT current_timestamp INTO inner_value) INTO outer_value;",
      ],
      [
        "fixture/pl-cte-select-into.sql",
        [
          "WITH child AS (SELECT current_timestamp AS value INTO inner_value)",
          "SELECT value INTO outer_value FROM child;",
        ].join("\n"),
      ],
    ];
    // isolate each nested procedural-capture rejection
    for (const [nestedPath, statement] of nestedCaptures) {
      const nestedSource = [
        "CREATE FUNCTION pl_nested_select_into()",
        "RETURNS timestamptz LANGUAGE plpgsql",
        "AS $body$",
        "DECLARE",
        "  inner_value timestamptz;",
        "  outer_value timestamptz;",
        "BEGIN",
        `  ${statement}`,
        "  RETURN outer_value;",
        "END;",
        "$body$;",
        "",
      ].join("\n");
      const nested = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("sql", nestedPath, nestedSource)],
      });
      assert.equal(
        nested.occurrences.some(
          // forbid one malformed nested-query provider
          (occurrence) => occurrence.language === "plpgsql"
            && occurrence.sourceLocator === nestedPath,
        ),
        false,
      );
      assert.equal(
        nested.semanticFacts.some(
          // forbid one malformed nested-query fact
          (fact) => fact.language === "plpgsql" && fact.site.path === nestedPath,
        ),
        false,
      );
      assertUnsupportedGap(nested);
    }

    const plPath = "fixture/pl-top-level-capture-positive.sql";
    const plSource = [
      "CREATE FUNCTION pl_top_level_capture_positive()",
      "RETURNS timestamptz LANGUAGE plpgsql",
      "AS $body$",
      "DECLARE",
      "  selected_at timestamptz;",
      "  selected_id integer;",
      "BEGIN",
      "  SELECT (SELECT current_timestamp) INTO selected_at;",
      "  DELETE FROM weather WHERE id = 1 RETURNING id INTO selected_id;",
      "  RETURN selected_at;",
      "END;",
      "$body$;",
      "",
    ].join("\n");
    const pl = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("sql", plPath, plSource)],
    });
    assert.equal(pl.diagnostics.length, 0);
    assert.equal(
      pl.occurrences.filter(
        // retain one nested provider under top-level capture
        (occurrence) => occurrence.language === "plpgsql"
          && occurrence.sourceLocator === plPath
          && occurrence.surface === "postgres.current-timestamp",
      ).length,
      1,
    );
    const plBindings = pl.semanticFacts.filter(
      // retain positioned pl bindings
      (fact) => fact.language === "plpgsql"
        && fact.site.path === plPath
        && fact.factKind === "binding",
    );
    assert.equal(
      plBindings.filter(
        // retain selected-at declaration and capture
        (fact) => fact.attributes.identifier === "selected_at",
      ).length >= 2,
      true,
    );
    assert.equal(
      plBindings.filter(
        // retain selected-id declaration and capture
        (fact) => fact.attributes.identifier === "selected_id",
      ).length >= 2,
      true,
    );

    const validSqlBodies = [
      [
        "fixture/sql-select-positive.sql",
        "SELECT current_timestamp;",
      ],
      [
        "fixture/sql-returning-positive.sql",
        "INSERT INTO weather (selected_at) VALUES (current_timestamp) RETURNING selected_at;",
      ],
    ];
    // isolate each valid sql-language body
    for (const [path, statement] of validSqlBodies) {
      const sourceText = [
        "CREATE FUNCTION sql_body_positive()",
        "RETURNS timestamptz LANGUAGE sql",
        "AS $body$",
        statement,
        "$body$;",
        "",
      ].join("\n");
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("sql", path, sourceText)],
      });
      assert.equal(result.diagnostics.length, 0);
      assert.equal(
        result.semanticFacts.some(
          // retain one valid sql routine
          (fact) => fact.language === "sql"
            && fact.site.path === path
            && fact.factKind === "function",
        ),
        true,
      );
      assert.equal(
        result.semanticFacts.some(
          // retain one valid sql provider fact
          (fact) => fact.language === "sql"
            && fact.site.path === path
            && fact.factKind === "clock-expression",
        ),
        true,
      );
      assert.equal(
        result.semanticFacts.some(
          // forbid one procedural binding in sql
          (fact) => fact.language === "sql"
            && fact.site.path === path
            && fact.factKind === "binding",
        ),
        false,
      );
    }
  },
);

test(
  "INSERT query bodies cannot inherit PL capture and TRUNCATE rejects empty targets",
  // verify nested query context and target cardinality
  async () => {
    const malformedBodies = [
      [
        "fixture/pl-insert-select-into.sql",
        "INSERT INTO destination (selected_at) SELECT current_timestamp INTO inner_capture;",
      ],
      [
        "fixture/pl-insert-with-into.sql",
        [
          "INSERT INTO destination (selected_at)",
          "WITH source_value AS (",
          "  SELECT current_timestamp AS value INTO inner_capture",
          ")",
          "SELECT value FROM source_value;",
        ].join("\n"),
      ],
      [
        "fixture/pl-truncate-trailing-comma.sql",
        [
          "selected_at := current_timestamp;",
          "TRUNCATE public.weather,;",
        ].join("\n"),
      ],
      [
        "fixture/pl-set-query-duplicate-capture.sql",
        "SELECT current_timestamp INTO first_capture UNION SELECT current_timestamp INTO second_capture;",
      ],
    ];
    // isolate each malformed nested or target production
    for (const [path, statement] of malformedBodies) {
      const sourceText = [
        "CREATE FUNCTION malformed_nested_production()",
        "RETURNS timestamptz LANGUAGE plpgsql",
        "AS $body$",
        "DECLARE",
        "  first_capture timestamptz;",
        "  inner_capture timestamptz;",
        "  second_capture timestamptz;",
        "  selected_at timestamptz;",
        "BEGIN",
        `  ${statement}`,
        "  RETURN selected_at;",
        "END;",
        "$body$;",
        "",
      ].join("\n");
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("sql", path, sourceText)],
      });
      assert.equal(
        result.occurrences.some(
          // forbid one malformed pl provider
          (occurrence) => occurrence.language === "plpgsql"
            && occurrence.sourceLocator === path,
        ),
        false,
      );
      assert.equal(
        result.semanticFacts.some(
          // forbid one malformed pl fact
          (fact) => fact.language === "plpgsql" && fact.site.path === path,
        ),
        false,
      );
      assertUnsupportedGap(result);
    }

    const validPath = "fixture/pl-insert-query-and-truncate-positive.sql";
    const validSource = [
      "CREATE FUNCTION insert_query_and_truncate_positive()",
      "RETURNS timestamptz LANGUAGE plpgsql",
      "AS $body$",
      "DECLARE",
      "  selected_at timestamptz;",
      "BEGIN",
      "  INSERT INTO destination (selected_at)",
      "  SELECT current_timestamp;",
      "  INSERT INTO destination (selected_at)",
      "  WITH source_value AS (SELECT current_timestamp AS value)",
      "  SELECT value FROM source_value;",
      "  INSERT INTO destination (selected_at)",
      "  SELECT current_timestamp UNION SELECT current_timestamp;",
      "  TRUNCATE public.weather, public.weather_archive;",
      "  selected_at := current_timestamp;",
      "  RETURN selected_at;",
      "END;",
      "$body$;",
      "",
    ].join("\n");
    const valid = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("sql", validPath, validSource)],
    });
    assert.equal(valid.diagnostics.length, 0);
    assert.equal(
      valid.occurrences.filter(
        // retain every valid body provider
        (occurrence) => occurrence.language === "plpgsql"
          && occurrence.sourceLocator === validPath
          && occurrence.surface === "postgres.current-timestamp",
      ).length,
      5,
    );
    const controls = valid.semanticFacts.filter(
      // retain valid static statement controls
      (fact) => fact.language === "plpgsql"
        && fact.site.path === validPath
        && fact.factKind === "control",
    );
    assert.equal(
      controls.filter(
        // retain valid insert controls
        (fact) => fact.attributes.identifier === "insert",
      ).length,
      3,
    );
    assert.equal(
      controls.filter(
        // retain one valid truncate control
        (fact) => fact.attributes.identifier === "truncate",
      ).length,
      1,
    );
  },
);

test(
  "SQL function calls stay visible while cast type modifiers stay non-call syntax",
  // verify exact call and type ownership
  async () => {
    const leftExpression = "left(current_timestamp::text, 2)";
    const rightExpression = "right(current_timestamp::text, 2)";
    const callPath = "fixture/sql-left-right-call-boundary.sql";
    const callSource = [
      "CREATE PROCEDURE sql_left_right_call_boundary()",
      "LANGUAGE plpgsql",
      "AS $body$",
      "BEGIN",
      `  PERFORM ${leftExpression}, ${rightExpression};`,
      "END;",
      "$body$;",
      "",
    ].join("\n");
    const calls = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("sql", callPath, callSource)],
    });
    const callFacts = calls.semanticFacts.filter(
      // retain genuine left and right calls
      (fact) => fact.language === "plpgsql"
        && fact.site.path === callPath
        && fact.factKind === "call",
    );
    assert.deepEqual(
      callFacts.map(
        // project positioned call ownership
        (fact) => [
          fact.attributes.identifier,
          fact.site.startUtf16,
          fact.site.endUtf16,
        ],
      ),
      [
        [
          "left",
          callSource.indexOf(leftExpression),
          callSource.indexOf(leftExpression) + leftExpression.length,
        ],
        [
          "right",
          callSource.indexOf(rightExpression),
          callSource.indexOf(rightExpression) + rightExpression.length,
        ],
      ],
    );
    assert.deepEqual(
      calls.occurrences.filter(
        // retain nested clock providers
        (occurrence) => occurrence.language === "plpgsql"
          && occurrence.sourceLocator === callPath,
      ).map(
        // project exact provider surfaces
        (occurrence) => occurrence.surface,
      ),
      ["postgres.current-timestamp", "postgres.current-timestamp"],
    );
    assertUnsupportedGap(calls);

    const castPath = "fixture/sql-cast-type-modifier-boundary.sql";
    const clockCall = "clock_timestamp()";
    const castSource = [
      "CREATE PROCEDURE sql_cast_type_modifier_boundary()",
      "LANGUAGE plpgsql",
      "AS $body$",
      "BEGIN",
      `  PERFORM CAST(${clockCall} AS timestamptz), CAST(1 AS numeric(10,2)), 1::pg_catalog.numeric(10,2);`,
      "END;",
      "$body$;",
      "",
    ].join("\n");
    const casts = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("sql", castPath, castSource)],
    });
    const castCalls = casts.semanticFacts.filter(
      // retain calls from valid cast expressions
      (fact) => fact.language === "plpgsql"
        && fact.site.path === castPath
        && fact.factKind === "call",
    );
    assert.deepEqual(
      castCalls.map(
        // project exact call identities
        (fact) => fact.attributes.identifier,
      ),
      ["clock_timestamp"],
    );
    assert.equal(castCalls[0].site.startUtf16, castSource.indexOf(clockCall));
    assert.equal(
      castCalls[0].site.endUtf16,
      castSource.indexOf(clockCall) + clockCall.length,
    );
    assert.deepEqual(
      casts.occurrences.filter(
        // retain the genuine nested provider
        (occurrence) => occurrence.language === "plpgsql"
          && occurrence.sourceLocator === castPath,
      ).map(
        // project the retained provider surface
        (occurrence) => occurrence.surface,
      ),
      ["postgres.clock-timestamp"],
    );
    assert.equal(
      casts.semanticFacts.filter(
        // retain the genuine nested clock fact
        (fact) => fact.language === "plpgsql"
          && fact.site.path === castPath
          && fact.factKind === "clock-expression",
      ).length,
      1,
    );
    assert.equal(casts.diagnostics.length, 0);
  },
);

test(
  "SQL CAST FILTER quantifier and OVER constructs enforce closed grammar roles",
  // verify construct-specific expression grammar
  async () => {
    const malformedExpressions = [
      [
        "fixture/pl-malformed-cast-arity.sql",
        "CAST(current_timestamp AS timestamptz, 1)",
      ],
      [
        "fixture/pl-malformed-cast-missing-as.sql",
        "CAST(current_timestamp timestamptz)",
      ],
      [
        "fixture/pl-malformed-cast-duplicate-as.sql",
        "CAST(current_timestamp AS timestamptz AS text)",
      ],
      [
        "fixture/pl-malformed-cast-type-tail.sql",
        "CAST(1 AS pg_catalog.numeric(10,2).extra)",
      ],
      [
        "fixture/pl-malformed-filter-clause.sql",
        "clock_timestamp() FILTER (1)",
      ],
      [
        "fixture/pl-malformed-filter-cardinality.sql",
        "clock_timestamp() FILTER (WHERE true, false)",
      ],
      [
        "fixture/pl-malformed-quantifier-empty.sql",
        "current_timestamp = ANY ()",
      ],
      [
        "fixture/pl-malformed-quantifier-arity.sql",
        "current_timestamp = ANY (1, 2)",
      ],
      [
        "fixture/pl-malformed-over-clause.sql",
        "max(clock_timestamp()) OVER (1)",
      ],
      [
        "fixture/pl-malformed-over-order.sql",
        "max(clock_timestamp()) OVER (ORDER BY current_timestamp PARTITION BY current_date)",
      ],
      [
        "fixture/pl-malformed-over-duplicate.sql",
        "max(clock_timestamp()) OVER (PARTITION BY current_date PARTITION BY current_date)",
      ],
    ];
    // isolate each malformed construct
    for (const [path, expression] of malformedExpressions) {
      const sourceText = [
        "CREATE PROCEDURE malformed_sql_construct()",
        "LANGUAGE plpgsql",
        "AS $body$",
        "BEGIN",
        `  PERFORM ${expression};`,
        "END;",
        "$body$;",
        "",
      ].join("\n");
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("sql", path, sourceText)],
      });
      assert.equal(
        result.occurrences.some(
          // forbid providers from one malformed construct
          (occurrence) => occurrence.language === "plpgsql"
            && occurrence.sourceLocator === path,
        ),
        false,
      );
      assert.equal(
        result.semanticFacts.some(
          // forbid facts from one malformed construct
          (fact) => fact.language === "plpgsql" && fact.site.path === path,
        ),
        false,
      );
      assertUnsupportedGap(result);
    }

    const validExpressions = [
      {
        calls: ["clock_timestamp"],
        expression: "CAST(clock_timestamp() AS timestamptz)",
        path: "fixture/pl-valid-cast.sql",
        surfaces: ["postgres.clock-timestamp"],
        unsupported: false,
      },
      {
        calls: ["clock_timestamp", "max"],
        expression: "max(clock_timestamp()) FILTER (WHERE true)",
        path: "fixture/pl-valid-filter.sql",
        surfaces: ["postgres.clock-timestamp"],
        unsupported: true,
      },
      {
        calls: [],
        expression: "current_timestamp = ANY (ARRAY[current_timestamp])",
        path: "fixture/pl-valid-quantifier-expression.sql",
        surfaces: [
          "postgres.current-timestamp",
          "postgres.current-timestamp",
        ],
        unsupported: false,
      },
      {
        calls: [],
        expression: "current_timestamp = ANY (SELECT current_timestamp)",
        path: "fixture/pl-valid-quantifier-subquery.sql",
        surfaces: [
          "postgres.current-timestamp",
          "postgres.current-timestamp",
        ],
        unsupported: false,
      },
      {
        calls: ["clock_timestamp", "max"],
        expression: "max(clock_timestamp()) OVER (PARTITION BY current_date ORDER BY current_timestamp)",
        path: "fixture/pl-valid-over.sql",
        surfaces: [
          "postgres.clock-timestamp",
          "postgres.current-date",
          "postgres.current-timestamp",
        ],
        unsupported: true,
      },
    ];
    // isolate each admitted construct
    for (const scenario of validExpressions) {
      const sourceText = [
        "CREATE PROCEDURE valid_sql_construct()",
        "LANGUAGE plpgsql",
        "AS $body$",
        "BEGIN",
        `  PERFORM ${scenario.expression};`,
        "END;",
        "$body$;",
        "",
      ].join("\n");
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("sql", scenario.path, sourceText)],
      });
      assert.deepEqual(
        result.semanticFacts.filter(
          // retain genuine calls from one valid construct
          (fact) => fact.language === "plpgsql"
            && fact.site.path === scenario.path
            && fact.factKind === "call",
        ).map(
          // project one call identity
          (fact) => fact.attributes.identifier,
        ).sort(compareText),
        scenario.calls,
      );
      assert.deepEqual(
        result.occurrences.filter(
          // retain providers from one valid construct
          (occurrence) => occurrence.language === "plpgsql"
            && occurrence.sourceLocator === scenario.path,
        ).map(
          // project one provider surface
          (occurrence) => occurrence.surface,
        ),
        scenario.surfaces,
      );
      assert.equal(
        result.semanticFacts.some(
          // retain facts from one admitted construct
          (fact) => fact.language === "plpgsql"
            && fact.site.path === scenario.path,
        ),
        true,
      );
      // distinguish binding gaps from grammar failures
      if (scenario.unsupported) {
        assertUnsupportedGap(result);
        assert.equal(
          result.diagnostics.every(
            // require only honest unsupported gaps
            (diagnostic) => diagnostic.code === "frontend.unsupported",
          ),
          true,
        );
      } else {
        assert.equal(result.diagnostics.length, 0);
      }
    }
  },
);

