const SQL_ROUTINE_CONTAINER_COUNTER_SCRIPT = String.raw`
import { readFileSync } from "node:fs";

const payload = JSON.parse(readFileSync(0, "utf8"));
const frontend = await import(payload.frontendModuleUrl);
const OriginalArrayFilter = Array.prototype.filter;
let activeFixturePath = null;
let physicalFilterCallbackVisits = 0;

// identify one physical occurrence entry
function isPhysicalOccurrence(value, fixturePath) {
  return value !== null && typeof value === "object" &&
    value.sourceLocator === fixturePath &&
    typeof value.id === "string" && typeof value.surface === "string" &&
    value.span !== null && typeof value.span === "object";
}

// summarize one closed failure
function failureSummary(error) {
  const code = ["frontend.bound-exceeded", "frontend.invalid-output"].includes(
    error?.code,
  )
    ? error.code
    : "test-harness.unexpected-error";
  return {
    code,
    messageMatchesCode: error?.message === code,
    ok: false,
    stage: error?.stage === "frontend-bootstrap"
      ? error.stage
      : "test-harness",
  };
}

// count physical occurrence filter work
Array.prototype.filter = function (callback, thisArg) {
  const physicalOccurrences = activeFixturePath !== null && this.length > 0 &&
    isPhysicalOccurrence(this[0], activeFixturePath);
  // count one delegated physical filter callback
  function countedFilterCallback(value, index, array) {
    // count only one marked physical occurrence visit
    if (physicalOccurrences) {
      physicalFilterCallbackVisits += 1;
    }
    return Reflect.apply(callback, thisArg, [value, index, array]);
  }
  return Reflect.apply(OriginalArrayFilter, this, [countedFilterCallback]);
};

let calibration = null;
const summaries = [];
// restore the builtin before serialization
try {
  activeFixturePath = "fixture/calibration.sql";
  const calibrationOccurrences = [0, 1].map(
    // build one physical calibration occurrence
    (index) => ({
      id: "clock-occurrence-v1:" + String(index).padStart(64, "0"),
      sourceLocator: activeFixturePath,
      span: { endOffsetUtf16: index + 1, startOffsetUtf16: index },
      surface: "postgres.dollar-quoted-body",
    }),
  );
  calibrationOccurrences.filter(
    // visit every physical calibration member
    () => true,
  );
  calibration = physicalFilterCallbackVisits;
  activeFixturePath = null;
  physicalFilterCallbackVisits = 0;
  // analyze every isolated routine family
  for (const scenario of payload.scenarios) {
    activeFixturePath = scenario.source.path;
    physicalFilterCallbackVisits = 0;
    // capture one sanitized scenario result
    try {
      const result = await frontend.analyzeBackendNonmoduleSourcesBatch({
        sources: [scenario.source],
      });
      let clockOccurrenceCount = 0;
      let containerIdCount = 0;
      let dollarContainerCount = 0;
      let routineBodyCount = 0;
      let routineFactIdCount = 0;
      let routineFactCount = 0;
      let routineIdentifierCount = 0;
      let unsupportedDiagnosticCount = 0;
      // count every semantic routine invariant
      for (const fact of result.semanticFacts) {
        // retain plpgsql routine facts only
        if (fact.factKind !== "function" || fact.language !== "plpgsql") {
          continue;
        }
        routineFactCount += 1;
        // retain one reviewed routine identifier
        if (
          typeof fact.attributes.identifier === "string" &&
          fact.attributes.identifier.startsWith(scenario.routinePrefix)
        ) {
          routineIdentifierCount += 1;
        }
        // retain one stable routine fact id
        if (/^[a-f0-9]{64}$/u.test(fact.factId)) {
          routineFactIdCount += 1;
        }
        let bodyEdges = 0;
        // count each direct body target
        for (const edge of fact.childEdges) {
          // retain one routine body edge
          if (edge.role === "body") {
            bodyEdges += 1;
          }
        }
        // retain exactly one body target
        if (bodyEdges === 1) {
          routineBodyCount += 1;
        }
      }
      // count every physical occurrence invariant
      for (const occurrence of result.occurrences) {
        // count one clock candidate
        if (occurrence.countsAsClockCandidate) {
          clockOccurrenceCount += 1;
        }
        // retain one exact dollar body container
        if (
          occurrence.identityVersion === "physical-v1" &&
          occurrence.surface === "postgres.dollar-quoted-body" &&
          occurrence.kind === "non-provider-container" &&
          occurrence.countsAsClockCandidate === false &&
          occurrence.sourceLocator === scenario.source.path
        ) {
          dollarContainerCount += 1;
          // retain one stable physical occurrence id
          if (/^clock-occurrence-v1:[a-f0-9]{64}$/u.test(occurrence.id)) {
            containerIdCount += 1;
          }
        }
      }
      // count every sanitized diagnostic
      for (const diagnostic of result.diagnostics) {
        // retain one unsupported diagnostic
        if (diagnostic.code === "frontend.unsupported") {
          unsupportedDiagnosticCount += 1;
        }
      }
      summaries.push({
        clockOccurrenceCount,
        containerIdCount,
        derivedSourceCount: result.derivedSources.length,
        diagnosticCount: result.diagnostics.length,
        dollarContainerCount,
        factCount: result.semanticFacts.length,
        id: scenario.id,
        occurrenceCount: result.occurrences.length,
        ok: true,
        physicalFilterCallbackVisits,
        routineBodyCount,
        routineFactCount,
        routineFactIdCount,
        routineIdentifierCount,
        unsupportedDiagnosticCount,
      });
    // close one failed routine scenario
    } catch (error) {
      summaries.push({
        ...failureSummary(error),
        id: scenario.id,
        physicalFilterCallbackVisits,
      });
    }
    activeFixturePath = null;
  }
} finally {
  Array.prototype.filter = OriginalArrayFilter;
}
process.stdout.write(JSON.stringify({
  calibration,
  ok: true,
  summaries,
}));
`;

// run isolated sql routine counters
function runSqlRoutineContainerCounterScenarios(scenarios) {
  const run = spawnSync(
    "/bin/sh",
    [
      "-c",
      "ulimit -c 0 || exit 125\nexec \"$@\"",
      "weather-sql-routine-container-counter",
      process.execPath,
      "--max-old-space-size=128",
      "--input-type=module",
      "-e",
      SQL_ROUTINE_CONTAINER_COUNTER_SCRIPT,
    ],
    {
      cwd: REPOSITORY_ROOT,
      encoding: "utf8",
      input: JSON.stringify({
        frontendModuleUrl: FRONTEND_MODULE_URL,
        scenarios,
      }),
      killSignal: "SIGKILL",
      maxBuffer: 1024 * 1024,
      timeout: 15_000,
    },
  );
  let summary = null;
  // parse only one closed successful summary
  if (run.error === undefined && run.status === 0) {
    // decode one bounded counter result
    try {
      summary = JSON.parse(run.stdout);
    } catch {
      summary = null;
    }
  }
  return {
    signal: run.signal,
    spawnFailed: run.error !== undefined,
    status: run.status,
    stderrBytes: Buffer.byteLength(run.stderr ?? "", "utf8"),
    stdoutBytes: Buffer.byteLength(run.stdout ?? "", "utf8"),
    summary,
  };
}

// require one bounded sql counter envelope
function assertSqlRoutineContainerCounterEnvelope(run, scenarioCount) {
  assert.equal(run.spawnFailed, false);
  assert.equal(run.status, 0);
  assert.equal(run.signal, null);
  assert.equal(run.stderrBytes, 0);
  assert.equal(run.stdoutBytes < 1024 * 1024, true);
  assert.notEqual(run.summary, null);
  assert.equal(run.summary.ok, true);
  assert.equal(run.summary.calibration, 2);
  assert.equal(run.summary.summaries.length, scenarioCount);
}

test(
  "SQL routine container linkage work stays linear",
  // verify routine container lookup stays bounded
  () => {
    const sizes = [0, 32, 64];
    const scenarios = sizes.map(
      // build one routine container family
      (size) => {
        const statements = [];
        // retain one zero-size sql invariant
        if (size === 0) {
          statements.push("SELECT 1;", "");
        }
        // append one valid routine and dollar body
        for (let index = 0; index < size; index += 1) {
          statements.push(
            `CREATE FUNCTION routine_perf_${index}()`,
            "RETURNS integer",
            "LANGUAGE plpgsql",
            `AS $body_${index}$`,
            "BEGIN",
            "  RETURN 1;",
            "END;",
            `$body_${index}$;`,
            "",
          );
        }
        return {
          id: `sql-routine-containers-${size}`,
          routinePrefix: "routine_perf_",
          source: physicalSource(
            "sql",
            `fixture/sql-routine-containers-${size}.sql`,
            statements.join("\n"),
          ),
        };
      },
    );
    const run = runSqlRoutineContainerCounterScenarios(scenarios);
    assertSqlRoutineContainerCounterEnvelope(run, scenarios.length);
    // verify semantics before counter growth
    for (let index = 0; index < sizes.length; index += 1) {
      const summary = run.summary.summaries[index];
      const size = sizes[index];
      assert.equal(summary.ok, true);
      assert.equal(summary.routineFactCount, size);
      assert.equal(summary.routineBodyCount, size);
      assert.equal(summary.routineIdentifierCount, size);
      assert.equal(summary.routineFactIdCount, size);
      assert.equal(summary.dollarContainerCount, size);
      assert.equal(summary.containerIdCount, size);
      assert.equal(summary.occurrenceCount, size);
      assert.equal(summary.clockOccurrenceCount, 0);
      assert.equal(summary.diagnosticCount, 0);
      assert.equal(summary.unsupportedDiagnosticCount, 0);
      assert.equal(summary.derivedSourceCount, 0);
      assert.equal(summary.factCount >= size, true);
    }
    const counterSummaries = run.summary.summaries.map(
      // adapt one sql counter to the shared counter envelope
      (summary) => ({
        counters: {
          physicalFilterCallbackVisits:
            summary.physicalFilterCallbackVisits,
        },
      }),
    );
    assertLinearCounter(counterSummaries, "physicalFilterCallbackVisits");
  },
);

test(
  "shell mutation builtins invalidate stale values at their owning boundary",
  // verify builtin mutation effects
  async () => {
    const evalPath = "fixture/eval-mutation-effects.sh";
    const evalSource = [
      "path=library.sh",
      "eval path=other.sh",
      'source "$path"',
      "",
    ].join("\n");
    const evalResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", evalPath, evalSource)],
    });
    assert.equal(
      evalResult.semanticFacts.some(
        // forbid stale or evaluated source edges
        (fact) => fact.site.path === evalPath && fact.factKind === "import",
      ),
      false,
    );
    // retain the eval and source calls
    for (const [identifier, command] of [
      ["eval", "eval path=other.sh"],
      ["source", 'source "$path"'],
    ]) {
      const startUtf16 = evalSource.indexOf(command);
      assert.equal(
        evalResult.semanticFacts.some(
          // locate one positioned eval-effect call
          (fact) => fact.site.path === evalPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + command.length,
        ),
        true,
      );
    }
    assert.equal(evalResult.occurrences.length, 0);
    assert.equal(evalResult.derivedSources.length, 0);
    assertUnsupportedGap(evalResult);

    const printfPath = "fixture/printf-v-mutation-effects.sh";
    const printfSource = [
      "path=library.sh",
      "printf -v path %s other.sh",
      'source "$path"',
      "",
    ].join("\n");
    const printfResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", printfPath, printfSource)],
    });
    const printfImports = printfResult.semanticFacts.filter(
      // retain printf-v source edges
      (fact) => fact.site.path === printfPath && fact.factKind === "import",
    );
    assert.equal(printfImports.length <= 1, true);
    assert.equal(
      printfImports.some(
        // forbid the stale pre-printf edge
        (fact) => fact.attributes.literalValue === "fixture/library.sh",
      ),
      false,
    );
    // require the exact printf value when modeled
    if (printfImports.length === 1) {
      assert.equal(printfImports[0].attributes.literalValue, "fixture/other.sh");
      assert.equal(printfResult.diagnostics.length, 0);
    } else {
      assertUnsupportedGap(printfResult);
    }
    assert.equal(printfResult.occurrences.length, 0);
    assert.equal(printfResult.derivedSources.length, 0);
    // retain the printf-v and source calls
    for (const [identifier, command] of [
      ["printf", "printf -v path %s other.sh"],
      ["source", 'source "$path"'],
    ]) {
      const startUtf16 = printfSource.indexOf(command);
      assert.equal(
        printfResult.semanticFacts.some(
          // locate one positioned printf-v call
          (fact) => fact.site.path === printfPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + command.length,
        ),
        true,
      );
    }

    const printfRiskSources = [
      [
        "fixture/printf-n-mutation-effects.sh",
        [
          "path=library.sh",
          "printf -v output '%n' path",
          'source "$path"',
          "",
        ].join("\n"),
      ],
      [
        "fixture/printf-dynamic-format-effects.sh",
        [
          "path=library.sh",
          "read format",
          'printf -v path "$format" other.sh',
          'source "$path"',
          "",
        ].join("\n"),
      ],
    ];
    // isolate each multi-target or dynamic printf effect
    for (const [path, sourceText] of printfRiskSources) {
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      assert.equal(
        result.semanticFacts.some(
          // forbid source edges across printf target risk
          (fact) => fact.site.path === path && fact.factKind === "import",
        ),
        false,
      );
      // retain the printf and source consumers
      for (const identifier of ["printf", "source"]) {
        assert.equal(
          result.semanticFacts.some(
            // locate one printf-risk call
            (fact) => fact.site.path === path
              && fact.factKind === "call"
              && fact.attributes.identifier === identifier,
          ),
          true,
        );
      }
      const sourceConsumer = 'source "$path"';
      const sourceOffset = sourceText.lastIndexOf(sourceConsumer);
      assert.equal(
        result.semanticFacts.some(
          // retain the positioned printf-risk consumer
          (fact) => fact.site.path === path
            && fact.factKind === "call"
            && fact.attributes.identifier === "source"
            && fact.site.startUtf16 === sourceOffset
            && fact.site.endUtf16 === sourceOffset + sourceConsumer.length,
        ),
        true,
      );
      assert.equal(result.occurrences.length, 0);
      assert.equal(result.derivedSources.length, 0);
      assertUnsupportedGap(result);
    }

    const mapfileSources = [
      ["fixture/mapfile-default-effects.sh", "MAPFILE", "mapfile"],
      ["fixture/mapfile-target-effects.sh", "values", "mapfile -t values"],
      [
        "fixture/mapfile-delimiter-target-effects.sh",
        "values",
        "mapfile -d '' -t values",
      ],
    ];
    // isolate each admitted mapfile target shape
    for (const [path, target, command] of mapfileSources) {
      const consumer = `node -e "$${target}"`;
      const sourceText = [
        `${target}='Date.now();'`,
        command,
        consumer,
        "",
      ].join("\n");
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      assert.equal(result.occurrences.length, 0);
      assert.equal(result.derivedSources.length, 0);
      assert.equal(
        result.semanticFacts.some(
          // forbid mapfile-stale embedded custody
          (fact) => fact.site.path === path
            && fact.factKind === "embedded-source",
        ),
        false,
      );
      // retain the mapfile and node calls
      for (const identifier of ["mapfile", "node"]) {
        assert.equal(
          result.semanticFacts.some(
            // locate one mapfile-effect call
            (fact) => fact.site.path === path
              && fact.factKind === "call"
              && fact.attributes.identifier === identifier,
          ),
          true,
        );
      }
      const consumerOffset = sourceText.lastIndexOf(consumer);
      assert.equal(
        result.semanticFacts.some(
          // retain the positioned mapfile consumer
          (fact) => fact.site.path === path
            && fact.factKind === "call"
            && fact.attributes.identifier === "node"
            && fact.site.startUtf16 === consumerOffset
            && fact.site.endUtf16 === consumerOffset + consumer.length,
        ),
        true,
      );
      assertUnsupportedGap(result);
    }

    const callbackPath = "fixture/mapfile-callback-effects.sh";
    const callbackSource = [
      "path=library.sh",
      "mapfile -C 'path=other.sh'",
      'source "$path"',
      "",
    ].join("\n");
    const callbackResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", callbackPath, callbackSource)],
    });
    assert.equal(
      callbackResult.semanticFacts.some(
        // forbid source edges across callback code effects
        (fact) => fact.site.path === callbackPath && fact.factKind === "import",
      ),
      false,
    );
    // retain the callback and source calls
    for (const identifier of ["mapfile", "source"]) {
      assert.equal(
        callbackResult.semanticFacts.some(
          // locate one callback-effect call
          (fact) => fact.site.path === callbackPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier,
        ),
        true,
      );
    }
    const callbackConsumer = 'source "$path"';
    const callbackOffset = callbackSource.lastIndexOf(callbackConsumer);
    assert.equal(
      callbackResult.semanticFacts.some(
        // retain the positioned callback consumer
        (fact) => fact.site.path === callbackPath
          && fact.factKind === "call"
          && fact.attributes.identifier === "source"
          && fact.site.startUtf16 === callbackOffset
          && fact.site.endUtf16 === callbackOffset + callbackConsumer.length,
      ),
      true,
    );
    assert.equal(callbackResult.occurrences.length, 0);
    assert.equal(callbackResult.derivedSources.length, 0);
    assertUnsupportedGap(callbackResult);
  },
);

test(
  "shell loop headers retain providers and invalidate assigned targets",
  // verify loop header effects
  async () => {
    const providerLoops = [
      ["while", "fixture/while-date-header.sh"],
      ["until", "fixture/until-date-header.sh"],
    ];
    // isolate each provider loop header
    for (const [kind, path] of providerLoops) {
      const sourceText = [
        `${kind} date; do`,
        "  :",
        "done",
        "",
      ].join("\n");
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      const providers = occurrencesOf(result, "shell.date");
      assert.equal(providers.length <= 1, true);
      assert.equal(result.derivedSources.length, 0);
      const dateStart = sourceText.indexOf("date");
      assert.equal(
        result.semanticFacts.some(
          // retain the positioned header call
          (fact) => fact.site.path === path
            && fact.factKind === "call"
            && fact.attributes.identifier === "date"
            && fact.site.startUtf16 === dateStart
            && fact.site.endUtf16 === dateStart + "date".length,
        ),
        true,
      );
      assert.equal(
        result.semanticFacts.some(
          // retain the typed loop control
          (fact) => fact.site.path === path
            && fact.factKind === "control"
            && fact.attributes.identifier === kind,
        ),
        true,
      );
      const bodyStart = sourceText.indexOf("  :") + 2;
      assert.equal(
        result.semanticFacts.some(
          // retain the positioned loop body call
          (fact) => fact.site.path === path
            && fact.factKind === "call"
            && fact.attributes.identifier === ":"
            && fact.site.startUtf16 === bodyStart
            && fact.site.endUtf16 === bodyStart + 1,
        ),
        true,
      );
      // require one provider or an honest header gap
      if (providers.length === 0) {
        assertUnsupportedGap(result);
      } else {
        assert.equal(result.diagnostics.length, 0);
      }
    }

    const readLoops = [
      ["while", "fixture/while-read-header.sh"],
      ["until", "fixture/until-read-header.sh"],
    ];
    // isolate each mutating loop header
    for (const [kind, path] of readLoops) {
      const sourceText = [
        "delay=1",
        `${kind} read delay; do`,
        "  :",
        "done",
        'sleep "$delay"',
        "",
      ].join("\n");
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      assert.equal(occurrencesOf(result, "shell.sleep").length, 0);
      assert.equal(result.derivedSources.length, 0);
      // retain the read and sleep calls
      for (const identifier of ["read", "sleep"]) {
        assert.equal(
          result.semanticFacts.some(
            // locate one loop-effect call
            (fact) => fact.site.path === path
              && fact.factKind === "call"
              && fact.attributes.identifier === identifier,
          ),
          true,
        );
      }
      const sleepConsumer = 'sleep "$delay"';
      const sleepOffset = sourceText.lastIndexOf(sleepConsumer);
      assert.equal(
        result.semanticFacts.some(
          // retain the positioned loop demand
          (fact) => fact.site.path === path
            && fact.factKind === "call"
            && fact.attributes.identifier === "sleep"
            && fact.site.startUtf16 === sleepOffset
            && fact.site.endUtf16 === sleepOffset + sleepConsumer.length,
        ),
        true,
      );
      const bodyStart = sourceText.indexOf("  :") + 2;
      assert.equal(
        result.semanticFacts.some(
          // retain the positioned mutating loop body
          (fact) => fact.site.path === path
            && fact.factKind === "call"
            && fact.attributes.identifier === ":"
            && fact.site.startUtf16 === bodyStart
            && fact.site.endUtf16 === bodyStart + 1,
        ),
        true,
      );
      assert.equal(
        result.semanticFacts.some(
          // retain the mutating loop control
          (fact) => fact.site.path === path
            && fact.factKind === "control"
            && fact.attributes.identifier === kind,
        ),
        true,
      );
      assertUnsupportedGap(result);
    }

    const selectDelayPath = "fixture/select-delay-target.sh";
    const selectDelaySource = [
      "delay=1",
      "select delay in 2 3; do",
      "  :",
      "done",
      'sleep "$delay"',
      "",
    ].join("\n");
    const selectDelayResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", selectDelayPath, selectDelaySource)],
    });
    assert.equal(occurrencesOf(selectDelayResult, "shell.sleep").length, 0);
    assert.equal(selectDelayResult.derivedSources.length, 0);
    assert.equal(
      selectDelayResult.semanticFacts.some(
        // retain the select control
        (fact) => fact.site.path === selectDelayPath
          && fact.factKind === "control"
          && fact.attributes.identifier === "select",
      ),
      true,
    );
    const selectSleep = 'sleep "$delay"';
    const selectSleepOffset = selectDelaySource.lastIndexOf(selectSleep);
    assert.equal(
      selectDelayResult.semanticFacts.some(
        // retain the positioned select demand
        (fact) => fact.site.path === selectDelayPath
          && fact.factKind === "call"
          && fact.attributes.identifier === "sleep"
          && fact.site.startUtf16 === selectSleepOffset
          && fact.site.endUtf16 === selectSleepOffset + selectSleep.length,
      ),
      true,
    );
    const selectDelayBody = selectDelaySource.indexOf("  :") + 2;
    assert.equal(
      selectDelayResult.semanticFacts.some(
        // retain the positioned select body
        (fact) => fact.site.path === selectDelayPath
          && fact.factKind === "call"
          && fact.attributes.identifier === ":"
          && fact.site.startUtf16 === selectDelayBody
          && fact.site.endUtf16 === selectDelayBody + 1,
      ),
      true,
    );
    assert.equal(
      selectDelayResult.semanticFacts.some(
        // retain the select demand call
        (fact) => fact.site.path === selectDelayPath
          && fact.factKind === "call"
          && fact.attributes.identifier === "sleep",
      ),
      true,
    );
    assertUnsupportedGap(selectDelayResult);

    const selectReplyPath = "fixture/select-reply-target.sh";
    const selectReplySource = [
      "REPLY='Date.now();'",
      "select choice in fixed; do",
      "  :",
      "done",
      'node -e "$REPLY"',
      "",
    ].join("\n");
    const selectReplyResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", selectReplyPath, selectReplySource)],
    });
    assert.equal(selectReplyResult.occurrences.length, 0);
    assert.equal(selectReplyResult.derivedSources.length, 0);
    assert.equal(
      selectReplyResult.semanticFacts.some(
        // forbid stale select reply custody
        (fact) => fact.site.path === selectReplyPath
          && fact.factKind === "embedded-source",
      ),
      false,
    );
    assert.equal(
      selectReplyResult.semanticFacts.some(
        // retain the select reply consumer
        (fact) => fact.site.path === selectReplyPath
          && fact.factKind === "call"
          && fact.attributes.identifier === "node",
      ),
      true,
    );
    const selectNode = 'node -e "$REPLY"';
    const selectNodeOffset = selectReplySource.lastIndexOf(selectNode);
    assert.equal(
      selectReplyResult.semanticFacts.some(
        // retain the positioned reply consumer
        (fact) => fact.site.path === selectReplyPath
          && fact.factKind === "call"
          && fact.attributes.identifier === "node"
          && fact.site.startUtf16 === selectNodeOffset
          && fact.site.endUtf16 === selectNodeOffset + selectNode.length,
      ),
      true,
    );
    const selectReplyBody = selectReplySource.indexOf("  :") + 2;
    assert.equal(
      selectReplyResult.semanticFacts.some(
        // retain the positioned reply loop body
        (fact) => fact.site.path === selectReplyPath
          && fact.factKind === "call"
          && fact.attributes.identifier === ":"
          && fact.site.startUtf16 === selectReplyBody
          && fact.site.endUtf16 === selectReplyBody + 1,
      ),
      true,
    );
    assertUnsupportedGap(selectReplyResult);
  },
);

test(
  "shell function effects stay scoped to sourced provenance",
  // verify source-scoped function effects
  async () => {
    const callerPath = "fixture/provenance-caller.sh";
    const callerText = [
      "source funcs.sh",
      "f() {",
      "  bridge",
      "}",
      "path=old.sh",
      "f",
      'source "$path"',
      "",
    ].join("\n");
    const callerSource = physicalSource("shell", callerPath, callerText);
    const missingResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [callerSource],
    });
    const missingImports = missingResult.semanticFacts.filter(
      // retain missing-profile source edges
      (fact) => fact.site.path === callerPath && fact.factKind === "import",
    );
    assert.equal(
      missingImports.some(
        // retain the literal sourced profile edge
        (fact) => fact.attributes.literalValue === "fixture/funcs.sh",
      ),
      true,
    );
    assert.equal(
      missingImports.some(
        // forbid the stale caller value
        (fact) => fact.attributes.literalValue === "fixture/old.sh",
      ),
      false,
    );
    const callerFStart = callerText.lastIndexOf("\nf\n") + 1;
    const callerSourceStart = callerText.lastIndexOf('source "$path"');
    // retain the final caller and source calls
    for (const [identifier, startUtf16, length] of [
      ["f", callerFStart, "f".length],
      ["source", callerSourceStart, 'source "$path"'.length],
    ]) {
      assert.equal(
        missingResult.semanticFacts.some(
          // locate one positioned missing-profile call
          (fact) => fact.site.path === callerPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }
    assertUnsupportedGap(missingResult);
    const missingDiagnosticCount = missingResult.diagnostics.length;

    const unrelatedProfiles = [
      [
        "pure",
        "fixture/unrelated-pure.sh",
        "bridge() {\n  :\n}\n",
      ],
      [
        "mutating",
        "fixture/unrelated-mutating.sh",
        "bridge() {\n  path=other.sh\n}\n",
      ],
    ];
    // isolate each unrelated definition profile
    for (const [name, path, sourceText] of unrelatedProfiles) {
      const unrelatedSource = physicalSource("shell", path, sourceText);
      const standalone = await analyzeBackendNonmoduleSourcesBatch({
        sources: [unrelatedSource],
      });
      assert.equal(standalone.diagnostics.length, 0);
      assert.equal(standalone.occurrences.length, 0);
      assert.equal(standalone.derivedSources.length, 0);
      assert.equal(
        standalone.semanticFacts.some(
          // retain the unrelated function body
          (fact) => fact.site.path === path
            && fact.factKind === "function"
            && fact.attributes.identifier === "bridge",
        ),
        true,
      );

      const sources = [callerSource, unrelatedSource];
      sources.sort(
        // retain exact frontend batch order
        (left, right) => compareText(left.language, right.language)
          || compareText(left.path, right.path)
          || compareText(left.rawSha256, right.rawSha256),
      );
      const result = await analyzeBackendNonmoduleSourcesBatch({ sources });
      const imports = result.semanticFacts.filter(
        // retain caller edges from one unrelated profile
        (fact) => fact.site.path === callerPath && fact.factKind === "import",
      );
      assert.equal(
        imports.some(
          // forbid unrelated closure from restoring stale custody
          (fact) => fact.attributes.literalValue === "fixture/old.sh",
        ),
        false,
      );
      assert.equal(result.diagnostics.length >= missingDiagnosticCount, true);
      assertUnsupportedGap(result);
      // retain the positioned caller and source calls
      for (const [identifier, startUtf16, length] of [
        ["f", callerFStart, "f".length],
        ["source", callerSourceStart, 'source "$path"'.length],
      ]) {
        assert.equal(
          result.semanticFacts.some(
            // locate one unrelated-profile caller fact
            (fact) => fact.site.path === callerPath
              && fact.factKind === "call"
              && fact.attributes.identifier === identifier
              && fact.site.startUtf16 === startUtf16
              && fact.site.endUtf16 === startUtf16 + length,
          ),
          true,
          name,
        );
      }
    }

    const funcsSource = physicalSource(
      "shell",
      "fixture/funcs.sh",
      "bridge() {\n  :\n}\n",
    );
    const completeSources = [callerSource, funcsSource];
    completeSources.sort(
      // retain exact complete-profile order
      (left, right) => compareText(left.language, right.language)
        || compareText(left.path, right.path)
        || compareText(left.rawSha256, right.rawSha256),
    );
    const completeResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: completeSources,
    });
    const completeImports = completeResult.semanticFacts.filter(
      // retain complete caller imports
      (fact) => fact.site.path === callerPath && fact.factKind === "import",
    );
    assert.equal(
      completeImports.some(
        // retain the sourced function profile
        (fact) => fact.attributes.literalValue === "fixture/funcs.sh",
      ),
      true,
    );
    assert.equal(
      completeImports.some(
        // retain the pure-call caller value
        (fact) => fact.attributes.literalValue === "fixture/old.sh",
      ),
      true,
    );
    assert.equal(completeResult.diagnostics.length, 0);
    assert.equal(completeResult.occurrences.length, 0);
    assert.equal(completeResult.derivedSources.length, 0);

    const libraryPath = "fixture/lib.sh";
    const librarySource = physicalSource(
      "shell",
      libraryPath,
      "g() {\n  :\n}\nf() {\n  g\n}\n",
    );
    const overridePath = "fixture/override-caller.sh";
    const overrideText = [
      "source lib.sh",
      "g() {",
      "  path=other.sh",
      "}",
      "path=old.sh",
      "f",
      'source "$path"',
      "",
    ].join("\n");
    const overrideSources = [
      librarySource,
      physicalSource("shell", overridePath, overrideText),
    ];
    overrideSources.sort(
      // retain exact override-profile order
      (left, right) => compareText(left.language, right.language)
        || compareText(left.path, right.path)
        || compareText(left.rawSha256, right.rawSha256),
    );
    const overrideResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: overrideSources,
    });
    const overrideImports = overrideResult.semanticFacts.filter(
      // retain override caller imports
      (fact) => fact.site.path === overridePath && fact.factKind === "import",
    );
    assert.equal(
      overrideImports.some(
        // forbid the stale pre-override value
        (fact) => fact.attributes.literalValue === "fixture/old.sh",
      ),
      false,
    );
    const finalOverrideImports = overrideImports.filter(
      // omit the literal library source edge
      (fact) => fact.attributes.literalValue !== "fixture/lib.sh",
    );
    assert.equal(finalOverrideImports.length <= 1, true);
    // require the caller override when modeled
    if (finalOverrideImports.length === 1) {
      assert.equal(
        finalOverrideImports[0].attributes.literalValue,
        "fixture/other.sh",
      );
    } else {
      assertUnsupportedGap(overrideResult);
    }
    const overrideFStart = overrideText.lastIndexOf("\nf\n") + 1;
    const overrideSourceStart = overrideText.lastIndexOf('source "$path"');
    // retain the override caller and source calls
    for (const [identifier, startUtf16, length] of [
      ["f", overrideFStart, "f".length],
      ["source", overrideSourceStart, 'source "$path"'.length],
    ]) {
      assert.equal(
        overrideResult.semanticFacts.some(
          // locate one positioned override-profile call
          (fact) => fact.site.path === overridePath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }

    const sharedSource = physicalSource(
      "shell",
      "fixture/shared.sh",
      "read() {\n  :\n}\n",
    );
    const callerAText = "source shared.sh\nread ignored\n";
    const callerBPath = "fixture/caller-b.sh";
    const callerBText = [
      "f() {",
      "  read delay",
      "}",
      "delay=1",
      "f",
      'sleep "$delay"',
      "",
    ].join("\n");
    const sharedSources = [
      sharedSource,
      physicalSource("shell", "fixture/caller-a.sh", callerAText),
      physicalSource("shell", callerBPath, callerBText),
    ];
    sharedSources.sort(
      // retain exact shared-profile order
      (left, right) => compareText(left.language, right.language)
        || compareText(left.path, right.path)
        || compareText(left.rawSha256, right.rawSha256),
    );
    const sharedResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: sharedSources,
    });
    assert.equal(
      occurrencesOf(sharedResult, "shell.sleep").some(
        // forbid caller-b stale sleep custody
        (occurrence) => occurrence.sourceLocator === callerBPath,
      ),
      false,
    );
    const callerBFStart = callerBText.lastIndexOf("\nf\n") + 1;
    const callerBSleepStart = callerBText.lastIndexOf('sleep "$delay"');
    // retain the caller-b function and demand calls
    for (const [identifier, startUtf16, length] of [
      ["f", callerBFStart, "f".length],
      ["sleep", callerBSleepStart, 'sleep "$delay"'.length],
    ]) {
      assert.equal(
        sharedResult.semanticFacts.some(
          // locate one positioned shared-profile call
          (fact) => fact.site.path === callerBPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }
    assertUnsupportedGap(sharedResult);

    const pendingNodePath = "fixture/pending-node-caller.sh";
    const pendingNodeText = [
      "source library.sh",
      'node -e "Date.now();"',
      "",
    ].join("\n");
    const pendingNodeResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", pendingNodePath, pendingNodeText)],
    });
    assert.equal(pendingNodeResult.derivedSources.length, 0);
    assert.equal(
      occurrencesOf(pendingNodeResult, "container.shell-node-e").length,
      0,
    );
    assert.equal(
      pendingNodeResult.semanticFacts.some(
        // retain the exact pending source edge
        (fact) => fact.site.path === pendingNodePath
          && fact.factKind === "import"
          && fact.attributes.literalValue === "fixture/library.sh",
      ),
      true,
    );
    // retain the pending source and node calls
    for (const [identifier, command] of [
      ["source", "source library.sh"],
      ["node", 'node -e "Date.now();"'],
    ]) {
      const startUtf16 = pendingNodeText.indexOf(command);
      assert.equal(
        pendingNodeResult.semanticFacts.some(
          // locate one positioned pending-custody call
          (fact) => fact.site.path === pendingNodePath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + command.length,
        ),
        true,
      );
    }
    assert.equal(
      pendingNodeResult.diagnostics.every(
        // retain only sanitized pending-custody diagnostics
        (diagnostic) => diagnostic.code === "frontend.unsupported"
          && diagnostic.messageId === diagnostic.code,
      ),
      true,
    );

    const pendingEffectPath = "fixture/pending-effect-caller.sh";
    const pendingEffectText = [
      "source library.sh",
      "f() {",
      "  printf ignored",
      "}",
      "delay=1",
      "f",
      'sleep "$delay"',
      "",
    ].join("\n");
    const pendingEffectCaller = physicalSource(
      "shell",
      pendingEffectPath,
      pendingEffectText,
    );
    const pendingEffectResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [pendingEffectCaller],
    });
    assert.equal(
      occurrencesOf(pendingEffectResult, "shell.sleep").length,
      0,
    );
    assert.equal(pendingEffectResult.derivedSources.length, 0);
    assert.equal(
      pendingEffectResult.semanticFacts.some(
        // retain the exact pending effect edge
        (fact) => fact.site.path === pendingEffectPath
          && fact.factKind === "import"
          && fact.attributes.literalValue === "fixture/library.sh",
      ),
      true,
    );
    const pendingFStart = pendingEffectText.lastIndexOf("\nf\n") + 1;
    const pendingSleepStart = pendingEffectText.lastIndexOf('sleep "$delay"');
    // retain the pending caller and clock demand
    for (const [identifier, startUtf16, length] of [
      ["f", pendingFStart, "f".length],
      ["sleep", pendingSleepStart, 'sleep "$delay"'.length],
    ]) {
      assert.equal(
        pendingEffectResult.semanticFacts.some(
          // locate one positioned pending-effect call
          (fact) => fact.site.path === pendingEffectPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }
    assert.equal(
      pendingEffectResult.diagnostics.every(
        // retain only sanitized pending-effect diagnostics
        (diagnostic) => diagnostic.code === "frontend.unsupported"
          && diagnostic.messageId === diagnostic.code,
      ),
      true,
    );

    const pendingLibrary = physicalSource(
      "shell",
      "fixture/library.sh",
      "printf() {\n  :\n}\n",
    );
    const resolvedEffectSources = [pendingEffectCaller, pendingLibrary];
    resolvedEffectSources.sort(
      // retain exact resolved profile order
      (left, right) => compareText(left.language, right.language)
        || compareText(left.path, right.path)
        || compareText(left.rawSha256, right.rawSha256),
    );
    const resolvedEffectResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: resolvedEffectSources,
    });
    const resolvedSleepOccurrences = occurrencesOf(
      resolvedEffectResult,
      "shell.sleep",
    );
    assert.equal(resolvedSleepOccurrences.length, 1);
    assert.equal(
      resolvedSleepOccurrences[0].sourceLocator,
      pendingEffectPath,
    );
    assert.equal(resolvedSleepOccurrences[0].countsAsClockCandidate, true);
    assert.equal(
      resolvedSleepOccurrences[0].span.startOffsetUtf16,
      pendingSleepStart,
    );
    assert.equal(
      resolvedSleepOccurrences[0].span.endOffsetUtf16,
      pendingSleepStart + 'sleep "$delay"'.length,
    );
    assert.equal(resolvedEffectResult.diagnostics.length, 0);
    assert.equal(resolvedEffectResult.derivedSources.length, 0);
    assert.equal(
      resolvedEffectResult.semanticFacts.some(
        // retain the resolved source edge
        (fact) => fact.site.path === pendingEffectPath
          && fact.factKind === "import"
          && fact.attributes.literalValue === "fixture/library.sh",
      ),
      true,
    );
    // retain the resolved caller and clock demand
    for (const [identifier, startUtf16, length] of [
      ["f", pendingFStart, "f".length],
      ["sleep", pendingSleepStart, 'sleep "$delay"'.length],
    ]) {
      assert.equal(
        resolvedEffectResult.semanticFacts.some(
          // locate one positioned resolved-effect call
          (fact) => fact.site.path === pendingEffectPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }
  },
);

test(
  "shell stateful builtins invalidate caller values without executing shell code",
  // verify stateful builtin effects
  async () => {
    const exportPath = "fixture/export-effect.sh";
    const exportSource = [
      "f() {",
      "  export path=other.sh",
      "}",
      "path=library.sh",
      "f",
      'source "$path"',
      "",
    ].join("\n");
    const exportResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", exportPath, exportSource)],
    });
    const exportImports = exportResult.semanticFacts.filter(
      // retain export-effect source edges
      (fact) => fact.site.path === exportPath && fact.factKind === "import",
    );
    assert.equal(exportImports.length <= 1, true);
    assert.equal(
      exportImports.some(
        // forbid the stale pre-export value
        (fact) => fact.attributes.literalValue === "fixture/library.sh",
      ),
      false,
    );
    // require the exported value when modeled
    if (exportImports.length === 1) {
      assert.equal(exportImports[0].attributes.literalValue, "fixture/other.sh");
    } else {
      assertUnsupportedGap(exportResult);
    }
    const exportFStart = exportSource.lastIndexOf("\nf\n") + 1;
    const exportSourceStart = exportSource.lastIndexOf('source "$path"');
    // retain the local caller and final consumer
    for (const [identifier, startUtf16, length] of [
      ["f", exportFStart, "f".length],
      ["source", exportSourceStart, 'source "$path"'.length],
    ]) {
      assert.equal(
        exportResult.semanticFacts.some(
          // locate one positioned export-effect call
          (fact) => fact.site.path === exportPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }
    assert.equal(exportResult.occurrences.length, 0);
    assert.equal(exportResult.derivedSources.length, 0);

    const trapPath = "fixture/debug-trap-effect.sh";
    const trapSource = [
      "path=library.sh",
      "trap 'path=other.sh' DEBUG",
      ":",
      'source "$path"',
      "",
    ].join("\n");
    const trapResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", trapPath, trapSource)],
    });
    assert.equal(
      trapResult.semanticFacts.some(
        // forbid executing trap code for custody
        (fact) => fact.site.path === trapPath && fact.factKind === "import",
      ),
      false,
    );
    // retain the trap trigger and consumer calls
    for (const [identifier, command] of [
      ["trap", "trap 'path=other.sh' DEBUG"],
      [":", ":"],
      ["source", 'source "$path"'],
    ]) {
      // locate the standalone trigger
      const startUtf16 = identifier === ":"
        ? trapSource.indexOf("\n:\n") + 1
        : trapSource.indexOf(command);
      assert.equal(
        trapResult.semanticFacts.some(
          // locate one positioned trap-effect call
          (fact) => fact.site.path === trapPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + command.length,
        ),
        true,
      );
    }
    assert.equal(trapResult.occurrences.length, 0);
    assert.equal(trapResult.derivedSources.length, 0);
    assertUnsupportedGap(trapResult);

    const directoryPath = "fixture/directory-effect.sh";
    const directorySource = [
      "PWD=library.sh",
      "cd /tmp",
      'source "$PWD"',
      "",
    ].join("\n");
    const directoryResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", directoryPath, directorySource)],
    });
    assert.equal(
      directoryResult.semanticFacts.some(
        // forbid stale directory custody
        (fact) => fact.site.path === directoryPath && fact.factKind === "import",
      ),
      false,
    );
    // retain the directory mutation and consumer calls
    for (const [identifier, command] of [
      ["cd", "cd /tmp"],
      ["source", 'source "$PWD"'],
    ]) {
      const startUtf16 = directorySource.indexOf(command);
      assert.equal(
        directoryResult.semanticFacts.some(
          // locate one positioned directory-effect call
          (fact) => fact.site.path === directoryPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + command.length,
        ),
        true,
      );
    }
    assert.equal(directoryResult.occurrences.length, 0);
    assert.equal(directoryResult.derivedSources.length, 0);
    assertUnsupportedGap(directoryResult);

    const exportedNamePath = "fixture/exported-name-unset.sh";
    const exportedNameSource = [
      "export date",
      "date() {",
      "  :",
      "}",
      "unset date",
      "date",
      "",
    ].join("\n");
    const exportedNameResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource(
        "shell",
        exportedNamePath,
        exportedNameSource,
      )],
    });
    assert.equal(occurrencesOf(exportedNameResult, "shell.date").length, 0);
    assert.equal(exportedNameResult.derivedSources.length, 0);
    assert.equal(
      exportedNameResult.semanticFacts.some(
        // retain the independent date function
        (fact) => fact.site.path === exportedNamePath
          && fact.factKind === "function"
          && fact.attributes.identifier === "date",
      ),
      true,
    );
    assert.equal(
      exportedNameResult.semanticFacts.some(
        // retain the positioned exported binding
        (fact) => fact.site.path === exportedNamePath
          && fact.factKind === "binding"
          && fact.attributes.identifier === "date"
          && fact.site.startUtf16 === 0
          && fact.site.endUtf16 === "export date".length,
      ),
      true,
    );
    const finalDateStart = exportedNameSource.lastIndexOf("\ndate\n") + 1;
    // retain the variable mutations and local call
    for (const [identifier, command, startUtf16] of [
      ["unset", "unset date", exportedNameSource.indexOf("unset date")],
      ["date", "date", finalDateStart],
    ]) {
      assert.equal(
        exportedNameResult.semanticFacts.some(
          // locate one positioned exported-name call
          (fact) => fact.site.path === exportedNamePath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + command.length,
        ),
        true,
      );
    }
    // require a closed gap when the namespace effect is conservative
    if (exportedNameResult.diagnostics.length > 0) {
      assert.equal(
        exportedNameResult.diagnostics.every(
          // retain only sanitized namespace gaps
          (diagnostic) => diagnostic.code === "frontend.unsupported"
            && diagnostic.messageId === diagnostic.code,
        ),
        true,
      );
      assertUnsupportedGap(exportedNameResult);
    }
  },
);

test(
  "shell local declarations dominate only their unconditional function scope",
  // verify local declaration dominance
  async () => {
    const conditionalScenarios = [
      [
        "logical",
        "fixture/conditional-local-logical.sh",
        [
          "f() {",
          "  : || local path",
          "  path=other.sh",
          "}",
          "path=library.sh",
          "f",
          'source "$path"',
          "",
        ].join("\n"),
      ],
      [
        "pipeline",
        "fixture/conditional-local-pipeline.sh",
        [
          "f() {",
          "  printf fixed | local path",
          "  path=other.sh",
          "}",
          "path=library.sh",
          "f",
          'source "$path"',
          "",
        ].join("\n"),
      ],
    ];
    // isolate each conditional local declaration
    for (const [name, path, sourceText] of conditionalScenarios) {
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      const imports = result.semanticFacts.filter(
        // retain conditional-local source edges
        (fact) => fact.site.path === path && fact.factKind === "import",
      );
      assert.equal(imports.length <= 1, true);
      assert.equal(
        imports.some(
          // forbid stale caller custody
          (fact) => fact.attributes.literalValue === "fixture/library.sh",
        ),
        false,
      );
      // require the global assignment when modeled
      if (imports.length === 1) {
        assert.equal(imports[0].attributes.literalValue, "fixture/other.sh", name);
      } else {
        assertUnsupportedGap(result);
      }
      const callStart = sourceText.lastIndexOf("\nf\n") + 1;
      const sourceStart = sourceText.lastIndexOf('source "$path"');
      // retain the local caller and final consumer
      for (const [identifier, startUtf16, length] of [
        ["f", callStart, "f".length],
        ["source", sourceStart, 'source "$path"'.length],
      ]) {
        assert.equal(
          result.semanticFacts.some(
            // locate one positioned local-dominance call
            (fact) => fact.site.path === path
              && fact.factKind === "call"
              && fact.attributes.identifier === identifier
              && fact.site.startUtf16 === startUtf16
              && fact.site.endUtf16 === startUtf16 + length,
          ),
          true,
          name,
        );
      }
      assert.equal(
        result.semanticFacts.some(
          // retain the local function definition
          (fact) => fact.site.path === path
            && fact.factKind === "function"
            && fact.attributes.identifier === "f",
        ),
        true,
      );
      assert.equal(result.occurrences.length, 0);
      assert.equal(result.derivedSources.length, 0);
    }

    const unconditionalPath = "fixture/unconditional-local.sh";
    const unconditionalSource = [
      "f() {",
      "  local path",
      "  path=other.sh",
      "}",
      "path=library.sh",
      "f",
      'source "$path"',
      "",
    ].join("\n");
    const unconditionalResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource(
        "shell",
        unconditionalPath,
        unconditionalSource,
      )],
    });
    const unconditionalImports = unconditionalResult.semanticFacts.filter(
      // retain unconditional-local source edges
      (fact) => fact.site.path === unconditionalPath && fact.factKind === "import",
    );
    assert.equal(unconditionalImports.length, 1);
    assert.equal(
      unconditionalImports[0].attributes.literalValue,
      "fixture/library.sh",
    );
    assert.equal(unconditionalResult.diagnostics.length, 0);
    assert.equal(unconditionalResult.occurrences.length, 0);
    assert.equal(unconditionalResult.derivedSources.length, 0);
    const unconditionalCallStart = unconditionalSource.lastIndexOf("\nf\n") + 1;
    const unconditionalSourceStart = unconditionalSource.lastIndexOf(
      'source "$path"',
    );
    // retain the pure caller and final consumer
    for (const [identifier, startUtf16, length] of [
      ["f", unconditionalCallStart, "f".length],
      ["source", unconditionalSourceStart, 'source "$path"'.length],
    ]) {
      assert.equal(
        unconditionalResult.semanticFacts.some(
          // locate one positioned unconditional-local call
          (fact) => fact.site.path === unconditionalPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }

    const nestedUnsetPath = "fixture/nested-unset-local-authority.sh";
    const nestedUnsetSource = [
      "erase() {",
      "  unset path",
      "}",
      "f() {",
      "  local path=local.sh",
      "  erase",
      "  readonly path",
      "}",
      "path=library.sh",
      "f",
      "path=other.sh",
      'source "$path"',
      "",
    ].join("\n");
    const nestedUnsetResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource(
        "shell",
        nestedUnsetPath,
        nestedUnsetSource,
      )],
    });
    const nestedUnsetImports = nestedUnsetResult.semanticFacts.filter(
      // retain nested-unset source edges
      (fact) => fact.site.path === nestedUnsetPath && fact.factKind === "import",
    );
    assert.equal(nestedUnsetImports.length <= 1, true);
    assert.equal(
      nestedUnsetImports.some(
        // forbid the possibly rejected replacement
        (fact) => fact.attributes.literalValue === "fixture/other.sh",
      ),
      false,
    );
    // retain the original value when precision survives
    if (nestedUnsetImports.length === 1) {
      assert.equal(
        nestedUnsetImports[0].attributes.literalValue,
        "fixture/library.sh",
      );
    }
    assert.equal(nestedUnsetResult.occurrences.length, 0);
    assert.equal(nestedUnsetResult.derivedSources.length, 0);
    // retain both dynamic-scope functions
    for (const identifier of ["erase", "f"]) {
      assert.equal(
        nestedUnsetResult.semanticFacts.some(
          // locate one nested-unset function
          (fact) => fact.site.path === nestedUnsetPath
            && fact.factKind === "function"
            && fact.attributes.identifier === identifier,
        ),
        true,
      );
    }
    const eraseStart = nestedUnsetSource.indexOf("\n  erase\n") + 3;
    const nestedFStart = nestedUnsetSource.lastIndexOf("\nf\n") + 1;
    const nestedSourceStart = nestedUnsetSource.lastIndexOf('source "$path"');
    // retain the nested caller and final consumer
    for (const [identifier, startUtf16, length] of [
      ["erase", eraseStart, "erase".length],
      ["f", nestedFStart, "f".length],
      ["source", nestedSourceStart, 'source "$path"'.length],
    ]) {
      assert.equal(
        nestedUnsetResult.semanticFacts.some(
          // locate one positioned nested-unset call
          (fact) => fact.site.path === nestedUnsetPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }
    assert.equal(
      nestedUnsetResult.diagnostics.every(
        // retain only sanitized dynamic-scope gaps
        (diagnostic) => diagnostic.code === "frontend.unsupported"
          && diagnostic.messageId === diagnostic.code,
      ),
      true,
    );
    assertUnsupportedGap(nestedUnsetResult);
  },
);

test(
  "shell function-wide effects survive logical alternative joins",
  // verify logical call effect joins
  async () => {
    const alternatives = [
      ["negated", "! : || change"],
      ["direct", "change || :"],
    ];
    // isolate each logical call placement
    for (const [name, expression] of alternatives) {
      const path = `fixture/logical-${name}-function-effect.sh`;
      const sourceText = [
        "change() {",
        "  path=other.sh",
        "}",
        "path=library.sh",
        expression,
        'source "$path"',
        "",
      ].join("\n");
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      const imports = result.semanticFacts.filter(
        // retain logical-effect source edges
        (fact) => fact.site.path === path && fact.factKind === "import",
      );
      assert.equal(imports.length <= 1, true);
      assert.equal(
        imports.some(
          // forbid the stale pre-call value
          (fact) => fact.attributes.literalValue === "fixture/library.sh",
        ),
        false,
      );
      // require the call effect when modeled
      if (imports.length === 1) {
        assert.equal(imports[0].attributes.literalValue, "fixture/other.sh", name);
      } else {
        assertUnsupportedGap(result);
      }
      const changeStart = sourceText.lastIndexOf(expression)
        + expression.indexOf("change");
      const sourceStart = sourceText.lastIndexOf('source "$path"');
      // retain the logical caller and final consumer
      for (const [identifier, startUtf16, length] of [
        ["change", changeStart, "change".length],
        ["source", sourceStart, 'source "$path"'.length],
      ]) {
        assert.equal(
          result.semanticFacts.some(
            // locate one positioned logical-effect call
            (fact) => fact.site.path === path
              && fact.factKind === "call"
              && fact.attributes.identifier === identifier
              && fact.site.startUtf16 === startUtf16
              && fact.site.endUtf16 === startUtf16 + length,
          ),
          true,
        );
      }
      assert.equal(result.occurrences.length, 0);
      assert.equal(result.derivedSources.length, 0);
    }

    const riskPath = "fixture/logical-readonly-function-effect.sh";
    const riskSource = [
      "mark() {",
      "  readonly path",
      "}",
      "path=library.sh",
      "! : || mark",
      "path=other.sh",
      'source "$path"',
      "",
    ].join("\n");
    const riskResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", riskPath, riskSource)],
    });
    const riskImports = riskResult.semanticFacts.filter(
      // retain logical readonly source edges
      (fact) => fact.site.path === riskPath && fact.factKind === "import",
    );
    assert.equal(riskImports.length <= 1, true);
    assert.equal(
      riskImports.some(
        // forbid the rejected replacement value
        (fact) => fact.attributes.literalValue === "fixture/other.sh",
      ),
      false,
    );
    // require the original value when precisely retained
    if (riskImports.length === 1) {
      assert.equal(riskImports[0].attributes.literalValue, "fixture/library.sh");
    }
    const markExpression = "! : || mark";
    const markStart = riskSource.indexOf(markExpression)
      + markExpression.indexOf("mark");
    const riskSourceStart = riskSource.lastIndexOf('source "$path"');
    // retain the readonly caller and final consumer
    for (const [identifier, startUtf16, length] of [
      ["mark", markStart, "mark".length],
      ["source", riskSourceStart, 'source "$path"'.length],
    ]) {
      assert.equal(
        riskResult.semanticFacts.some(
          // locate one positioned logical readonly call
          (fact) => fact.site.path === riskPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }
    assert.equal(riskResult.occurrences.length, 0);
    assert.equal(riskResult.derivedSources.length, 0);
    assertUnsupportedGap(riskResult);
  },
);

test(
  "shell reserved body markers remain ordinary header arguments until grammar position",
  // verify reserved marker ownership
  async () => {
    const scenarios = [
      {
        binding: "then",
        control: "if",
        path: "fixture/if-then-target.sh",
        requiredCalls: [
          ["read", "read then", "read then", 0],
          [":", ":", "\n  :\n", 3],
          ["sleep", 'sleep "$then"', 'sleep "$then"', 0],
        ],
        sourceText: [
          "then=1",
          "if read then; then",
          "  :",
          "fi",
          'sleep "$then"',
          "",
        ].join("\n"),
      },
      {
        binding: "then",
        control: "if",
        path: "fixture/if-then-exit-target.sh",
        requiredCalls: [
          ["read", "read then", "read then", 0],
          ["exit", "exit", "\n  exit\n", 3],
          ["sleep", 'sleep "$then"', 'sleep "$then"', 0],
        ],
        sourceText: [
          "then=1",
          "if read then; then",
          "  exit",
          "fi",
          'sleep "$then"',
          "",
        ].join("\n"),
      },
      {
        binding: "delay",
        control: "while",
        path: "fixture/while-unquoted-do-argument.sh",
        requiredCalls: [
          [":", ": do", ": do", 0],
          ["read", "read delay", "read delay", 0],
          [":", ":", "\n  :\n", 3],
          ["sleep", 'sleep "$delay"', 'sleep "$delay"', 0],
        ],
        sourceText: [
          "delay=1",
          "while : do; read delay; do",
          "  :",
          "done",
          'sleep "$delay"',
          "",
        ].join("\n"),
      },
      {
        binding: "delay",
        control: "while",
        path: "fixture/while-quoted-do-argument.sh",
        requiredCalls: [
          ["printf", "printf '%s' 'do'", "printf '%s' 'do'", 0],
          ["read", "read delay", "read delay", 0],
          [":", ":", "\n  :\n", 3],
          ["sleep", 'sleep "$delay"', 'sleep "$delay"', 0],
        ],
        sourceText: [
          "delay=1",
          "while printf '%s' 'do'; read delay; do",
          "  :",
          "done",
          'sleep "$delay"',
          "",
        ].join("\n"),
      },
    ];
    // isolate each reserved marker context
    for (const scenario of scenarios) {
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource(
          "shell",
          scenario.path,
          scenario.sourceText,
        )],
      });
      assert.equal(occurrencesOf(result, "shell.sleep").length, 0);
      assert.equal(result.derivedSources.length, 0);
      assert.equal(
        result.semanticFacts.some(
          // retain the seeded header binding
          (fact) => fact.site.path === scenario.path
            && fact.factKind === "binding"
            && fact.attributes.identifier === scenario.binding,
        ),
        true,
      );
      assert.equal(
        result.semanticFacts.some(
          // retain the enclosing control form
          (fact) => fact.site.path === scenario.path
            && fact.factKind === "control"
            && fact.attributes.identifier === scenario.control,
        ),
        true,
      );
      // retain every positioned header or demand call
      for (const [identifier, command, locator, offset] of scenario.requiredCalls) {
        const locatorStart = scenario.sourceText.indexOf(locator);
        assert.equal(locatorStart >= 0, true);
        const startUtf16 = locatorStart + offset;
        assert.equal(
          result.semanticFacts.some(
            // locate one positioned marker-context call
            (fact) => fact.site.path === scenario.path
              && fact.factKind === "call"
              && fact.attributes.identifier === identifier
              && fact.site.startUtf16 === startUtf16
              && fact.site.endUtf16 === startUtf16 + command.length,
          ),
          true,
        );
      }
      assert.equal(
        result.diagnostics.every(
          // retain only sanitized marker gaps
          (diagnostic) => diagnostic.code === "frontend.unsupported"
            && diagnostic.messageId === diagnostic.code,
        ),
        true,
      );
      assertUnsupportedGap(result);
    }
  },
);

test(
  "shell unreviewed stateful builtins invalidate targets unless local authority is proven",
  // verify builtin authority ownership
  async () => {
    const builtinScenarios = [
      ["readarray", "fixture/readarray-target-effect.sh", "readarray path"],
      ["getopts", "fixture/getopts-target-effect.sh", "getopts x path"],
    ];
    // isolate each external builtin target
    for (const [identifier, path, command] of builtinScenarios) {
      const sourceText = [
        "path=old.sh",
        command,
        'source "$path"',
        "",
      ].join("\n");
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      assert.equal(
        result.semanticFacts.some(
          // forbid stale builtin-target custody
          (fact) => fact.site.path === path && fact.factKind === "import",
        ),
        false,
      );
      const sourceCommand = 'source "$path"';
      // retain the mutator and final consumer calls
      for (const [callIdentifier, callText] of [
        [identifier, command],
        ["source", sourceCommand],
      ]) {
        const startUtf16 = sourceText.indexOf(callText);
        assert.equal(
          result.semanticFacts.some(
            // locate one positioned builtin-target call
            (fact) => fact.site.path === path
              && fact.factKind === "call"
              && fact.attributes.identifier === callIdentifier
              && fact.site.startUtf16 === startUtf16
              && fact.site.endUtf16 === startUtf16 + callText.length,
          ),
          true,
        );
      }
      assert.equal(result.occurrences.length, 0);
      assert.equal(result.derivedSources.length, 0);
      assert.equal(
        result.diagnostics.every(
          // retain only sanitized builtin-target gaps
          (diagnostic) => diagnostic.code === "frontend.unsupported"
            && diagnostic.messageId === diagnostic.code,
        ),
        true,
      );
      assertUnsupportedGap(result);
    }

    const localPath = "fixture/local-readarray-authority.sh";
    const localSource = [
      "readarray() {",
      "  :",
      "}",
      "path=old.sh",
      "readarray path",
      'source "$path"',
      "",
    ].join("\n");
    const localResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", localPath, localSource)],
    });
    const localImports = localResult.semanticFacts.filter(
      // retain local-authority source edges
      (fact) => fact.site.path === localPath && fact.factKind === "import",
    );
    assert.equal(localImports.length, 1);
    assert.equal(localImports[0].attributes.literalValue, "fixture/old.sh");
    assert.equal(localResult.diagnostics.length, 0);
    assert.equal(localResult.occurrences.length, 0);
    assert.equal(localResult.derivedSources.length, 0);
    assert.equal(
      localResult.semanticFacts.some(
        // retain the local readarray definition
        (fact) => fact.site.path === localPath
          && fact.factKind === "function"
          && fact.attributes.identifier === "readarray",
      ),
      true,
    );
    const localReadarrayStart = localSource.lastIndexOf("readarray path");
    const localSourceStart = localSource.lastIndexOf('source "$path"');
    // retain the local caller and final consumer
    for (const [identifier, startUtf16, length] of [
      ["readarray", localReadarrayStart, "readarray path".length],
      ["source", localSourceStart, 'source "$path"'.length],
    ]) {
      assert.equal(
        localResult.semanticFacts.some(
          // locate one positioned local-authority call
          (fact) => fact.site.path === localPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }
  },
);

test(
  "shell exact imports retain authority after closed setup and continuing guards",
  // verify exact import authority
  async () => {
    const callerPath = "fixture/closed-setup-caller.sh";
    const callerText = [
      "set -euo pipefail",
      "if [[ ! -d /tmp/weather-owned ]]; then",
      "  printf missing",
      "  exit 1",
      "fi",
      "source library.sh",
      'node -e "Date.now();"',
      "",
    ].join("\n");
    const callerSource = physicalSource("shell", callerPath, callerText);
    const pureLibrary = physicalSource(
      "shell",
      "fixture/library.sh",
      "pure() {\n  :\n}\n",
    );
    const completeSources = [callerSource, pureLibrary];
    completeSources.sort(
      // retain exact complete profile order
      (left, right) => compareText(left.language, right.language)
        || compareText(left.path, right.path)
        || compareText(left.rawSha256, right.rawSha256),
    );
    const completeResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: completeSources,
    });
    assert.equal(completeResult.derivedSources.length, 1);
    const completeContainers = occurrencesOf(
      completeResult,
      "container.shell-node-e",
    );
    assert.equal(completeContainers.length, 1);
    assert.equal(completeContainers[0].sourceLocator, callerPath);
    assert.equal(
      completeResult.semanticFacts.some(
        // retain the exact complete source edge
        (fact) => fact.site.path === callerPath
          && fact.factKind === "import"
          && fact.attributes.literalValue === "fixture/library.sh",
      ),
      true,
    );
    const sourceCommand = "source library.sh";
    const nodeCommand = 'node -e "Date.now();"';
    // retain the exact source and node calls
    for (const [identifier, command] of [
      ["source", sourceCommand],
      ["node", nodeCommand],
    ]) {
      const startUtf16 = callerText.indexOf(command);
      assert.equal(
        completeResult.semanticFacts.some(
          // locate one positioned complete-profile call
          (fact) => fact.site.path === callerPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + command.length,
        ),
        true,
      );
    }
    assert.equal(
      completeResult.semanticFacts.some(
        // retain the owned setup guard
        (fact) => fact.site.path === callerPath
          && fact.factKind === "control"
          && fact.attributes.identifier === "if",
      ),
      true,
    );

    const evalLibrary = physicalSource(
      "shell",
      "fixture/library.sh",
      [
        "install() {",
        '  eval "$setup"',
        "}",
        "install",
        "",
      ].join("\n"),
    );
    const evalSources = [callerSource, evalLibrary];
    evalSources.sort(
      // retain exact eval profile order
      (left, right) => compareText(left.language, right.language)
        || compareText(left.path, right.path)
        || compareText(left.rawSha256, right.rawSha256),
    );
    const evalResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: evalSources,
    });
    assert.equal(evalResult.derivedSources.length, 0);
    assert.equal(
      occurrencesOf(evalResult, "container.shell-node-e").length,
      0,
    );
    assert.equal(
      evalResult.semanticFacts.some(
        // retain the exact eval-owned source edge
        (fact) => fact.site.path === callerPath
          && fact.factKind === "import"
          && fact.attributes.literalValue === "fixture/library.sh",
      ),
      true,
    );
    assert.equal(
      evalResult.semanticFacts.some(
        // retain the unknown node consumer
        (fact) => fact.site.path === callerPath
          && fact.factKind === "call"
          && fact.attributes.identifier === "node"
          && fact.site.startUtf16 === callerText.indexOf(nodeCommand)
          && fact.site.endUtf16 === callerText.indexOf(nodeCommand)
            + nodeCommand.length,
      ),
      true,
    );
    assert.equal(
      evalResult.diagnostics.every(
        // retain only sanitized eval-world gaps
        (diagnostic) => diagnostic.code === "frontend.unsupported"
          && diagnostic.messageId === diagnostic.code,
      ),
      true,
    );
    assertUnsupportedGap(evalResult);

    const returnCallerPath = "fixture/returning-source-caller.sh";
    const returnCallerText = [
      "source library.sh",
      'node -e "Date.now();"',
      "",
    ].join("\n");
    const returningLibrary = physicalSource(
      "shell",
      "fixture/library.sh",
      [
        "if [[ -d /tmp/weather-optional ]]; then",
        "  return 0",
        "fi",
        "node() {",
        "  :",
        "}",
        "",
      ].join("\n"),
    );
    const returnSources = [
      physicalSource("shell", returnCallerPath, returnCallerText),
      returningLibrary,
    ];
    returnSources.sort(
      // retain exact returning profile order
      (left, right) => compareText(left.language, right.language)
        || compareText(left.path, right.path)
        || compareText(left.rawSha256, right.rawSha256),
    );
    const returnResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: returnSources,
    });
    assert.equal(returnResult.derivedSources.length, 0);
    assert.equal(
      occurrencesOf(returnResult, "container.shell-node-e").length,
      0,
    );
    assert.equal(
      returnResult.semanticFacts.some(
        // retain the exact returning source edge
        (fact) => fact.site.path === returnCallerPath
          && fact.factKind === "import"
          && fact.attributes.literalValue === "fixture/library.sh",
      ),
      true,
    );
    const returnNodeStart = returnCallerText.indexOf(nodeCommand);
    assert.equal(
      returnResult.semanticFacts.some(
        // retain the caller after target return
        (fact) => fact.site.path === returnCallerPath
          && fact.factKind === "call"
          && fact.attributes.identifier === "node"
          && fact.site.startUtf16 === returnNodeStart
          && fact.site.endUtf16 === returnNodeStart + nodeCommand.length,
      ),
      true,
    );
    assert.equal(
      returnResult.diagnostics.every(
        // retain only sanitized return-world gaps
        (diagnostic) => diagnostic.code === "frontend.unsupported"
          && diagnostic.messageId === diagnostic.code,
      ),
      true,
    );
    assertUnsupportedGap(returnResult);
  },
);

test(
  "shell non-erasing callees preserve dominating local ownership",
  // verify transitive local ownership
  async () => {
    const readonlyPath = "fixture/non-erasing-readonly-caller.sh";
    const readonlyText = [
      "pure() {",
      "  :",
      "}",
      "relay() {",
      "  pure",
      "}",
      "outer() {",
      "  local path=inner.sh",
      "  relay",
      "  path=inner2.sh",
      "  readonly path",
      "}",
      "path=old.sh",
      "outer",
      "path=after.sh",
      'source "$path"',
      "",
    ].join("\n");
    const readonlyResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", readonlyPath, readonlyText)],
    });
    const readonlyImports = readonlyResult.semanticFacts.filter(
      // retain the post-call source edge
      (fact) => fact.site.path === readonlyPath && fact.factKind === "import",
    );
    assert.equal(readonlyImports.length, 1);
    assert.equal(
      readonlyImports[0].attributes.literalValue,
      "fixture/after.sh",
    );
    assert.equal(readonlyResult.diagnostics.length, 0);
    assert.equal(readonlyResult.occurrences.length, 0);
    assert.equal(readonlyResult.derivedSources.length, 0);
    // retain each non-erasing function
    for (const identifier of ["pure", "relay", "outer"]) {
      assert.equal(
        readonlyResult.semanticFacts.some(
          // locate one non-erasing function definition
          (fact) => fact.site.path === readonlyPath
            && fact.factKind === "function"
            && fact.attributes.identifier === identifier,
        ),
        true,
      );
    }
    const readonlyPureStart = readonlyText.indexOf("\n  pure\n") + 3;
    const readonlyRelayStart = readonlyText.indexOf("\n  relay\n") + 3;
    const readonlyOuterStart = readonlyText.lastIndexOf("\nouter\n") + 1;
    const readonlySourceStart = readonlyText.lastIndexOf('source "$path"');
    // retain the transitive callers and source consumer
    for (const [identifier, startUtf16, length] of [
      ["pure", readonlyPureStart, "pure".length],
      ["relay", readonlyRelayStart, "relay".length],
      ["outer", readonlyOuterStart, "outer".length],
      ["source", readonlySourceStart, 'source "$path"'.length],
    ]) {
      assert.equal(
        readonlyResult.semanticFacts.some(
          // locate one positioned non-erasing call
          (fact) => fact.site.path === readonlyPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }

    const purePath = "fixture/non-erasing-pure-caller.sh";
    const pureText = [
      "pure() {",
      "  :",
      "}",
      "relay() {",
      "  pure",
      "}",
      "outer() {",
      "  local path=inner.sh",
      "  relay",
      "  path=inner2.sh",
      "}",
      "path=old.sh",
      "outer",
      'source "$path"',
      "",
    ].join("\n");
    const pureResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", purePath, pureText)],
    });
    const pureImports = pureResult.semanticFacts.filter(
      // retain the pure-callee source edge
      (fact) => fact.site.path === purePath && fact.factKind === "import",
    );
    assert.equal(pureImports.length, 1);
    assert.equal(pureImports[0].attributes.literalValue, "fixture/old.sh");
    assert.equal(pureResult.diagnostics.length, 0);
    assert.equal(pureResult.occurrences.length, 0);
    assert.equal(pureResult.derivedSources.length, 0);
    const pureOuterStart = pureText.lastIndexOf("\nouter\n") + 1;
    const pureSourceStart = pureText.lastIndexOf('source "$path"');
    // retain the pure outer call and source consumer
    for (const [identifier, startUtf16, length] of [
      ["outer", pureOuterStart, "outer".length],
      ["source", pureSourceStart, 'source "$path"'.length],
    ]) {
      assert.equal(
        pureResult.semanticFacts.some(
          // locate one positioned pure-callee call
          (fact) => fact.site.path === purePath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }

    const erasingPath = "fixture/transitive-erasing-caller.sh";
    const erasingText = [
      "erase() {",
      "  unset path",
      "}",
      "relay() {",
      "  erase",
      "}",
      "outer() {",
      "  local path=inner.sh",
      "  relay",
      "  readonly path",
      "}",
      "path=old.sh",
      "outer",
      "path=after.sh",
      'source "$path"',
      "",
    ].join("\n");
    const erasingResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", erasingPath, erasingText)],
    });
    const erasingImports = erasingResult.semanticFacts.filter(
      // retain transitive erasing source edges
      (fact) => fact.site.path === erasingPath && fact.factKind === "import",
    );
    assert.equal(erasingImports.length <= 1, true);
    assert.equal(
      erasingImports.some(
        // forbid the possibly rejected replacement
        (fact) => fact.attributes.literalValue === "fixture/after.sh",
      ),
      false,
    );
    // retain the prior global value when precision survives
    if (erasingImports.length === 1) {
      assert.equal(erasingImports[0].attributes.literalValue, "fixture/old.sh");
    }
    assert.equal(erasingResult.occurrences.length, 0);
    assert.equal(erasingResult.derivedSources.length, 0);
    const erasingEraseStart = erasingText.indexOf("\n  erase\n") + 3;
    const erasingRelayStart = erasingText.indexOf("\n  relay\n") + 3;
    const erasingOuterStart = erasingText.lastIndexOf("\nouter\n") + 1;
    const erasingSourceStart = erasingText.lastIndexOf('source "$path"');
    // retain the erasing call chain and source consumer
    for (const [identifier, startUtf16, length] of [
      ["erase", erasingEraseStart, "erase".length],
      ["relay", erasingRelayStart, "relay".length],
      ["outer", erasingOuterStart, "outer".length],
      ["source", erasingSourceStart, 'source "$path"'.length],
    ]) {
      assert.equal(
        erasingResult.semanticFacts.some(
          // locate one positioned erasing-chain call
          (fact) => fact.site.path === erasingPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + length,
        ),
        true,
      );
    }
    assert.equal(
      erasingResult.diagnostics.every(
        // retain only sanitized transitive erasure gaps
        (diagnostic) => diagnostic.code === "frontend.unsupported"
          && diagnostic.messageId === diagnostic.code,
      ),
      true,
    );
    assertUnsupportedGap(erasingResult);
  },
);

test(
  "shell external effects and structural controls have one owning dispatch",
  // verify effect and grammar dispatch ownership
  async () => {
    const externalPath = "fixture/external-effect-boundary.sh";
    const externalCommands = [
      ["dirname", "dirname /tmp/value"],
      ["ln", "ln /tmp/source /tmp/link"],
      ["mkdir", "mkdir /tmp/directory"],
      ["mv", "mv /tmp/from /tmp/to"],
      ["rmdir", "rmdir /tmp/empty"],
      ["true", "true"],
    ];
    const externalText = [
      "path=library.sh",
      ...externalCommands.map(
        // project one external command
        ([, command]) => command,
      ),
      'source "$path"',
      "",
    ].join("\n");
    const externalResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", externalPath, externalText)],
    });
    const externalImports = externalResult.semanticFacts.filter(
      // retain the external-boundary source edge
      (fact) => fact.site.path === externalPath && fact.factKind === "import",
    );
    assert.equal(externalImports.length, 1);
    assert.equal(
      externalImports[0].attributes.literalValue,
      "fixture/library.sh",
    );
    assert.equal(externalResult.occurrences.length, 0);
    assert.equal(externalResult.derivedSources.length, 0);
    // retain every external command call
    for (const [identifier, command] of externalCommands) {
      const startUtf16 = externalText.indexOf(command);
      assert.equal(
        externalResult.semanticFacts.some(
          // locate one positioned external call
          (fact) => fact.site.path === externalPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + command.length,
        ),
        true,
      );
    }
    const externalSourceStart = externalText.lastIndexOf('source "$path"');
    assert.equal(
      externalResult.semanticFacts.some(
        // retain the positioned external-boundary consumer
        (fact) => fact.site.path === externalPath
          && fact.factKind === "call"
          && fact.attributes.identifier === "source"
          && fact.site.startUtf16 === externalSourceStart
          && fact.site.endUtf16 === externalSourceStart
            + 'source "$path"'.length,
      ),
      true,
    );
    assert.equal(
      externalResult.diagnostics.every(
        // retain only sanitized external-effect gaps
        (diagnostic) => diagnostic.code === "frontend.unsupported"
          && diagnostic.messageId === diagnostic.code,
      ),
      true,
    );

    const localPath = "fixture/local-mkdir-effect.sh";
    const localText = [
      "mkdir() {",
      "  path=other.sh",
      "}",
      "path=library.sh",
      "mkdir /tmp/directory",
      'source "$path"',
      "",
    ].join("\n");
    const localResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", localPath, localText)],
    });
    const localImports = localResult.semanticFacts.filter(
      // retain local mkdir source edges
      (fact) => fact.site.path === localPath && fact.factKind === "import",
    );
    assert.equal(localImports.length <= 1, true);
    assert.equal(
      localImports.some(
        // forbid bypassing the local write
        (fact) => fact.attributes.literalValue === "fixture/library.sh",
      ),
      false,
    );
    // require the local write when modeled
    if (localImports.length === 1) {
      assert.equal(localImports[0].attributes.literalValue, "fixture/other.sh");
    } else {
      assertUnsupportedGap(localResult);
    }
    assert.equal(localResult.occurrences.length, 0);
    assert.equal(localResult.derivedSources.length, 0);
    assert.equal(
      localResult.semanticFacts.some(
        // retain the local mkdir definition
        (fact) => fact.site.path === localPath
          && fact.factKind === "function"
          && fact.attributes.identifier === "mkdir",
      ),
      true,
    );
    // retain the local mkdir and source calls
    for (const [identifier, command] of [
      ["mkdir", "mkdir /tmp/directory"],
      ["source", 'source "$path"'],
    ]) {
      const startUtf16 = localText.indexOf(command);
      assert.equal(
        localResult.semanticFacts.some(
          // locate one positioned local mkdir call
          (fact) => fact.site.path === localPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + command.length,
        ),
        true,
      );
    }

    const structuralPath = "fixture/structural-subshell-loop.sh";
    const structuralText = [
      "control_plane_digest() {",
      "  local file",
      "  local -a files=(alpha beta)",
      "  (",
      "    cd /tmp",
      "    umask 077",
      '    for file in "${files[@]}"; do',
      "      printf '%s\\n' \"$file\"",
      '      sha256sum "$file"',
      "    done",
      "  )",
      "}",
      "path=library.sh",
      "control_plane_digest",
      'source "$path"',
      "",
    ].join("\n");
    const structuralResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", structuralPath, structuralText)],
    });
    const structuralImports = structuralResult.semanticFacts.filter(
      // retain structural caller source edges
      (fact) => fact.site.path === structuralPath && fact.factKind === "import",
    );
    assert.equal(structuralImports.length, 1);
    assert.equal(
      structuralImports[0].attributes.literalValue,
      "fixture/library.sh",
    );
    assert.equal(structuralResult.occurrences.length, 0);
    assert.equal(structuralResult.derivedSources.length, 0);
    assert.equal(
      structuralResult.semanticFacts.some(
        // forbid structural markers as calls
        (fact) => fact.site.path === structuralPath
          && fact.factKind === "call"
          && ["for", "do", "done"].includes(fact.attributes.identifier),
      ),
      false,
    );
    assert.equal(
      structuralResult.semanticFacts.some(
        // retain the typed loop control
        (fact) => fact.site.path === structuralPath
          && fact.factKind === "control"
          && fact.attributes.identifier === "for",
      ),
      true,
    );
    const structuralCalls = [
      ["cd", "cd /tmp"],
      ["umask", "umask 077"],
      ["printf", "printf '%s\\n' \"$file\""],
      ["sha256sum", 'sha256sum "$file"'],
      ["control_plane_digest", "control_plane_digest"],
      ["source", 'source "$path"'],
    ];
    // retain every structural body or caller command
    for (const [identifier, command] of structuralCalls) {
      // locate the outer function call
      const startUtf16 = identifier === "control_plane_digest"
        ? structuralText.lastIndexOf("\ncontrol_plane_digest\n") + 1
        : structuralText.indexOf(command);
      assert.equal(
        structuralResult.semanticFacts.some(
          // locate one positioned structural call
          (fact) => fact.site.path === structuralPath
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === startUtf16
            && fact.site.endUtf16 === startUtf16 + command.length,
        ),
        true,
      );
    }
    assert.equal(
      structuralResult.diagnostics.every(
        // retain only sanitized child-scope gaps
        (diagnostic) => diagnostic.code === "frontend.unsupported"
          && diagnostic.messageId === diagnostic.code,
      ),
      true,
    );

    const singleDispatchScenarios = [
      ["readarray", "fixture/readarray-single-dispatch.sh", "readarray path"],
      ["getopts", "fixture/getopts-single-dispatch.sh", "getopts x path"],
    ];
    // isolate each unreviewed stateful builtin
    for (const [identifier, path, command] of singleDispatchScenarios) {
      const sourceText = `${command}\n`;
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      assert.equal(result.diagnostics.length, 1);
      assert.equal(result.diagnostics[0].code, "frontend.unsupported");
      assert.equal(
        result.diagnostics[0].messageId,
        result.diagnostics[0].code,
      );
      assert.equal(result.diagnostics[0].dimension, "frontend");
      assert.equal(result.diagnostics[0].severity, "gap");
      assert.equal(result.occurrences.length, 0);
      assert.equal(result.derivedSources.length, 0);
      assert.equal(
        result.semanticFacts.some(
          // retain the sole dispatched builtin call
          (fact) => fact.site.path === path
            && fact.factKind === "call"
            && fact.attributes.identifier === identifier
            && fact.site.startUtf16 === 0
            && fact.site.endUtf16 === command.length,
        ),
        true,
      );
    }
  },
);

test(
  "shell shadowed declaration builtins cannot establish local ownership",
  // verify declaration authority before effects
  async () => {
    const declarationNames = ["local", "declare", "typeset"];
    // isolate each shadowed declaration builtin
    for (const declarationName of declarationNames) {
      const path = `fixture/shadowed-${declarationName}-builtin.sh`;
      const sourceText = [
        `${declarationName}(){`,
        "  :",
        "}",
        "f(){",
        `  ${declarationName} path`,
        "  readonly path",
        "}",
        "path=library.sh",
        "f",
        "path=other.sh",
        'source "$path"',
        "",
      ].join("\n");
      const source = physicalSource("shell", path, sourceText);
      // pin the reviewed local fixture bytes
      if (declarationName === "local") {
        assert.equal(
          source.rawSha256,
          "be46af12007c69fad5dc3de1e3f3268bd3e54eb9cb231191ebbe13bc246390ea",
        );
      }
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [source],
      });
      const imports = result.semanticFacts.filter(
        // retain shadowed-declaration source edges
        (fact) => fact.site.path === path && fact.factKind === "import",
      );
      assert.equal(imports.length <= 1, true);
      assert.equal(
        imports.some(
          // forbid the possibly rejected replacement
          (fact) => fact.attributes.literalValue === "fixture/other.sh",
        ),
        false,
      );
      // retain the prior global value when precision survives
      if (imports.length === 1) {
        assert.equal(imports[0].attributes.literalValue, "fixture/library.sh");
      }
      assert.equal(
        result.semanticFacts.some(
          // retain the shadowing function definition
          (fact) => fact.site.path === path
            && fact.factKind === "function"
            && fact.attributes.identifier === declarationName,
        ),
        true,
      );
      const declarationCommand = `${declarationName} path`;
      const declarationStart = sourceText.indexOf(declarationCommand);
      assert.equal(
        result.semanticFacts.some(
          // retain the shadowed declaration as a call
          (fact) => fact.site.path === path
            && fact.factKind === "call"
            && fact.attributes.identifier === declarationName
            && fact.site.startUtf16 === declarationStart
            && fact.site.endUtf16 === declarationStart
              + declarationCommand.length,
        ),
        true,
      );
      assert.equal(
        result.semanticFacts.some(
          // forbid a binding from the shadowed call
          (fact) => fact.site.path === path
            && fact.factKind === "binding"
            && fact.site.startUtf16 >= declarationStart
            && fact.site.endUtf16 <= declarationStart
              + declarationCommand.length,
        ),
        false,
      );
      const moduleFStart = sourceText.lastIndexOf("\nf\n") + 1;
      const sourceStart = sourceText.lastIndexOf('source "$path"');
      // retain the module caller and final consumer
      for (const [identifier, startUtf16, length] of [
        ["f", moduleFStart, "f".length],
        ["source", sourceStart, 'source "$path"'.length],
      ]) {
        assert.equal(
          result.semanticFacts.some(
            // locate one positioned shadowed-builtin call
            (fact) => fact.site.path === path
              && fact.factKind === "call"
              && fact.attributes.identifier === identifier
              && fact.site.startUtf16 === startUtf16
              && fact.site.endUtf16 === startUtf16 + length,
          ),
          true,
        );
      }
      assert.equal(
        result.diagnostics.every(
          // retain only sanitized authority gaps
          (diagnostic) => diagnostic.code === "frontend.unsupported"
            && diagnostic.messageId === diagnostic.code,
        ),
        true,
      );
      assertUnsupportedGap(result);
    }
  },
);

test(
  "shell condition segments keep one explicit semantic owner",
  // verify condition fact ownership
  async () => {
    const nestedKinds = ["if", "while", "until"];
    // isolate each nested condition form
    for (const kind of nestedKinds) {
      const path = `fixture/nested-${kind}-condition-owner.sh`;
      // select the matching close marker
      const close = kind === "if" ? "fi" : "done";
      // select the matching body marker
      const marker = kind === "if" ? "then" : "do";
      const sourceText = [
        "if :; then",
        `  ${kind} FLAG=fixed printf ignored; ${marker}`,
        "    :",
        `  ${close}`,
        "fi",
        "",
      ].join("\n");
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      const bindingStart = sourceText.indexOf("FLAG=fixed");
      const binding = result.semanticFacts.find(
        // locate the exact condition prefix binding
        (fact) => fact.site.path === path
          && fact.factKind === "binding"
          && fact.attributes.identifier === "FLAG"
          && fact.site.startUtf16 === bindingStart
          && fact.site.endUtf16 === bindingStart + "FLAG=fixed".length,
      );
      assert.notEqual(binding, undefined);
      const innerStart = sourceText.indexOf(`  ${kind}`) + 2;
      const inner = result.semanticFacts.find(
        // locate the inner condition owner
        (fact) => fact.site.path === path
          && fact.factKind === "control"
          && fact.attributes.identifier === kind
          && fact.site.startUtf16 === innerStart,
      );
      assert.notEqual(inner, undefined);
      const outer = result.semanticFacts.find(
        // locate the outer condition owner
        (fact) => fact.site.path === path
          && fact.factKind === "control"
          && fact.attributes.identifier === "if"
          && fact.site.startUtf16 === 0,
      );
      assert.notEqual(outer, undefined);
      const conditionStart = sourceText.indexOf("printf ignored");
      const conditionCall = result.semanticFacts.find(
        // locate the inner condition call
        (fact) => fact.site.path === path
          && fact.factKind === "call"
          && fact.attributes.identifier === "printf"
          && fact.site.startUtf16 === conditionStart
          && fact.site.endUtf16 === conditionStart + "printf ignored".length,
      );
      assert.notEqual(conditionCall, undefined);
      const bodyStart = sourceText.indexOf("\n    :\n") + 5;
      const bodyCall = result.semanticFacts.find(
        // locate the inner body call
        (fact) => fact.site.path === path
          && fact.factKind === "call"
          && fact.attributes.identifier === ":"
          && fact.site.startUtf16 === bodyStart
          && fact.site.endUtf16 === bodyStart + 1,
      );
      assert.notEqual(bodyCall, undefined);
      const innerBodyEdges = inner.childEdges.filter(
        // retain direct inner body children
        (edge) => edge.role === "body",
      );
      assert.deepEqual(
        innerBodyEdges.map(
          // project direct child order
          (edge) => [edge.index, edge.childFactId],
        ),
        [
          [0, binding.factId],
          [1, conditionCall.factId],
          [2, bodyCall.factId],
        ],
      );
      assert.equal(
        outer.childEdges.some(
          // forbid escaped inner condition children
          (edge) => edge.childFactId === binding.factId
            || edge.childFactId === conditionCall.factId,
        ),
        false,
      );
    }

    const localPath = "fixture/function-local-condition-owner.sh";
    const localText = [
      "f() {",
      "  if local FLAG; then",
      "    :",
      "  fi",
      "}",
      "",
    ].join("\n");
    const localResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", localPath, localText)],
    });
    const localBindingStart = localText.indexOf("local FLAG");
    const localBinding = localResult.semanticFacts.find(
      // locate the declaration-only condition binding
      (fact) => fact.site.path === localPath
        && fact.factKind === "binding"
        && fact.attributes.identifier === "FLAG"
        && fact.site.startUtf16 === localBindingStart
        && fact.site.endUtf16 === localBindingStart + "local FLAG".length,
    );
    assert.notEqual(localBinding, undefined);
    const localControlStart = localText.indexOf("if local FLAG");
    const localControl = localResult.semanticFacts.find(
      // locate the declaration condition owner
      (fact) => fact.site.path === localPath
        && fact.factKind === "control"
        && fact.attributes.identifier === "if"
        && fact.site.startUtf16 === localControlStart,
    );
    assert.notEqual(localControl, undefined);
    const localBodyStart = localText.indexOf("\n    :\n") + 5;
    const localBodyCall = localResult.semanticFacts.find(
      // locate the declaration condition body
      (fact) => fact.site.path === localPath
        && fact.factKind === "call"
        && fact.attributes.identifier === ":"
        && fact.site.startUtf16 === localBodyStart
        && fact.site.endUtf16 === localBodyStart + 1,
    );
    assert.notEqual(localBodyCall, undefined);
    const localBodyEdges = localControl.childEdges.filter(
      // retain direct declaration condition children
      (edge) => edge.role === "body",
    );
    assert.deepEqual(
      localBodyEdges.map(
        // project declaration child order
        (edge) => [edge.index, edge.childFactId],
      ),
      [
        [0, localBinding.factId],
        [1, localBodyCall.factId],
      ],
    );
    const functionFact = localResult.semanticFacts.find(
      // locate the surrounding function owner
      (fact) => fact.site.path === localPath
        && fact.factKind === "function"
        && fact.attributes.identifier === "f",
    );
    assert.notEqual(functionFact, undefined);
    assert.equal(
      functionFact.childEdges.some(
        // forbid one escaped declaration binding
        (edge) => edge.childFactId === localBinding.factId,
      ),
      false,
    );
  },
);

test(
  "shell deferred substitutions retain discovery-time environment snapshots",
  // verify deferred substitution snapshots
  async () => {
    const valueScenarios = [
      [
        "assignment",
        "fixture/substitution-before-assignment.sh",
        [
          "path=before",
          'capture=$(dirname "$path")',
          "path=after",
          "",
        ].join("\n"),
      ],
      [
        "read",
        "fixture/substitution-before-read.sh",
        [
          "path=before",
          'capture=$(dirname "$path")',
          "read path",
          "",
        ].join("\n"),
      ],
    ];
    // isolate each later namespace mutation
    for (const [name, path, sourceText] of valueScenarios) {
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      const callStart = sourceText.indexOf("dirname");
      const call = result.semanticFacts.find(
        // locate the deferred dirname call
        (fact) => fact.site.path === path
          && fact.factKind === "call"
          && fact.attributes.identifier === "dirname"
          && fact.site.startUtf16 === callStart
          && fact.site.endUtf16 === callStart + 'dirname "$path"'.length,
      );
      assert.notEqual(call, undefined, name);
      const argumentEdge = call.childEdges.find(
        // locate the first deferred argument
        (edge) => edge.role === "args" && edge.index === 0,
      );
      assert.notEqual(argumentEdge, undefined, name);
      const argument = result.semanticFacts.find(
        // resolve the deferred argument fact
        (fact) => fact.factId === argumentEdge.childFactId,
      );
      assert.notEqual(argument, undefined, name);
      const argumentStart = sourceText.indexOf('"$path"');
      assert.equal(argument.factKind, "constant", name);
      assert.equal(argument.attributes.literalValue, "before", name);
      assert.equal(argument.site.startUtf16, argumentStart, name);
      assert.equal(
        argument.site.endUtf16,
        argumentStart + '"$path"'.length,
        name,
      );
    }

    const datePath = "fixture/substitution-before-date-shadow.sh";
    const dateText = [
      "capture=$(date -u +%s)",
      "date() {",
      "  :",
      "}",
      "",
    ].join("\n");
    const dateResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", datePath, dateText)],
    });
    const dateOccurrences = occurrencesOf(dateResult, "shell.date");
    assert.equal(dateOccurrences.length, 1);
    const dateStart = dateText.indexOf("date -u +%s");
    assert.equal(dateOccurrences[0].sourceLocator, datePath);
    assert.equal(dateOccurrences[0].span.startOffsetUtf16, dateStart);
    assert.equal(
      dateOccurrences[0].span.endOffsetUtf16,
      dateStart + "date -u +%s".length,
    );
    assert.equal(
      dateResult.semanticFacts.some(
        // retain the deferred direct date call
        (fact) => fact.site.path === datePath
          && fact.factKind === "call"
          && fact.attributes.identifier === "date"
          && fact.site.startUtf16 === dateStart
          && fact.site.endUtf16 === dateStart + "date -u +%s".length,
      ),
      true,
    );
    assert.equal(
      dateResult.semanticFacts.some(
        // retain the later date definition
        (fact) => fact.site.path === datePath
          && fact.factKind === "function"
          && fact.attributes.identifier === "date",
      ),
      true,
    );

    const nodePath = "fixture/substitution-before-node-shadow.sh";
    const nodeCommand = 'node -e "Date.now();"';
    const nodeText = [
      `capture=$(${nodeCommand})`,
      "node() {",
      "  :",
      "}",
      "",
    ].join("\n");
    const nodeResult = await analyzeBackendNonmoduleSourcesBatch({
      sources: [physicalSource("shell", nodePath, nodeText)],
    });
    assert.equal(nodeResult.derivedSources.length, 1);
    const nodeContainers = occurrencesOf(
      nodeResult,
      "container.shell-node-e",
    );
    assert.equal(nodeContainers.length, 1);
    const nodeStart = nodeText.indexOf(nodeCommand);
    assert.equal(nodeContainers[0].sourceLocator, nodePath);
    assert.equal(nodeContainers[0].span.startOffsetUtf16, nodeStart);
    assert.equal(
      nodeContainers[0].span.endOffsetUtf16,
      nodeStart + nodeCommand.length,
    );
    assert.equal(
      occurrencesOf(nodeResult, "ecmascript.date-now").length,
      1,
    );
    assert.equal(
      nodeResult.semanticFacts.some(
        // retain the deferred literal node call
        (fact) => fact.site.path === nodePath
          && fact.factKind === "call"
          && fact.attributes.identifier === "node"
          && fact.site.startUtf16 === nodeStart
          && fact.site.endUtf16 === nodeStart + nodeCommand.length,
      ),
      true,
    );
    assert.equal(
      nodeResult.semanticFacts.some(
        // retain the later node definition
        (fact) => fact.site.path === nodePath
          && fact.factKind === "function"
          && fact.attributes.identifier === "node",
      ),
      true,
    );
  },
);

test(
  "shell signal callbacks cannot infer purity from literal exit spelling",
  // verify signal callback authority
  async () => {
    const signalScenarios = [
      [
        "before",
        "fixture/signal-exit-function-before.sh",
        [
          "exit() {",
          "  path=other.sh",
          "}",
          "path=library.sh",
          "trap 'exit 130' HUP INT TERM",
          'source "$path"',
          "",
        ].join("\n"),
      ],
      [
        "after",
        "fixture/signal-exit-function-after.sh",
        [
          "path=library.sh",
          "trap 'exit 130' HUP INT TERM",
          "exit() {",
          "  path=other.sh",
          "}",
          'source "$path"',
          "",
        ].join("\n"),
      ],
    ];
    // isolate each exit definition order
    for (const [name, path, sourceText] of signalScenarios) {
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      const imports = result.semanticFacts.filter(
        // retain signal-callback source edges
        (fact) => fact.site.path === path && fact.factKind === "import",
      );
      assert.equal(imports.length, 0);
      assert.equal(
        result.semanticFacts.some(
          // retain the raw exit function authority
          (fact) => fact.site.path === path
            && fact.factKind === "function"
            && fact.attributes.identifier === "exit",
        ),
        true,
      );
      const trapCommand = "trap 'exit 130' HUP INT TERM";
      const sourceCommand = 'source "$path"';
      // retain the signal registration and source consumer
      for (const [identifier, command] of [
        ["trap", trapCommand],
        ["source", sourceCommand],
      ]) {
        const startUtf16 = sourceText.indexOf(command);
        assert.equal(
          result.semanticFacts.some(
            // locate one positioned signal callback call
            (fact) => fact.site.path === path
              && fact.factKind === "call"
              && fact.attributes.identifier === identifier
              && fact.site.startUtf16 === startUtf16
              && fact.site.endUtf16 === startUtf16 + command.length,
          ),
          true,
          name,
        );
      }
      assert.equal(
        result.diagnostics.every(
          // retain only sanitized signal gaps
          (diagnostic) => diagnostic.code === "frontend.unsupported"
            && diagnostic.messageId === diagnostic.code,
        ),
        true,
      );
      assertUnsupportedGap(result);
    }

    const positiveScenarios = [
      [
        "reset",
        "fixture/reset-exit-trap.sh",
        [
          "path=library.sh",
          "trap 'exit 130' EXIT",
          "trap - EXIT",
          'source "$path"',
          "",
        ].join("\n"),
        ["trap 'exit 130' EXIT", "trap - EXIT"],
      ],
      [
        "deferred",
        "fixture/deferred-exit-trap.sh",
        [
          "exit() {",
          "  path=other.sh",
          "}",
          "path=library.sh",
          "trap 'exit 130' EXIT",
          'source "$path"',
          "",
        ].join("\n"),
        ["trap 'exit 130' EXIT"],
      ],
    ];
    // isolate each reviewed exit trap control
    for (const [name, path, sourceText, trapCommands] of positiveScenarios) {
      const result = await analyzeBackendNonmoduleSourcesBatch({
        sources: [physicalSource("shell", path, sourceText)],
      });
      const imports = result.semanticFacts.filter(
        // retain reviewed exit-trap source edges
        (fact) => fact.site.path === path && fact.factKind === "import",
      );
      assert.equal(imports.length, 1, name);
      assert.equal(
        imports[0].attributes.literalValue,
        "fixture/library.sh",
        name,
      );
      // retain each reviewed trap call
      for (const command of trapCommands) {
        const startUtf16 = sourceText.indexOf(command);
        assert.equal(
          result.semanticFacts.some(
            // locate one positioned reviewed trap call
            (fact) => fact.site.path === path
              && fact.factKind === "call"
              && fact.attributes.identifier === "trap"
              && fact.site.startUtf16 === startUtf16
              && fact.site.endUtf16 === startUtf16 + command.length,
          ),
          true,
          name,
        );
      }
      const sourceCommand = 'source "$path"';
      const sourceStart = sourceText.lastIndexOf(sourceCommand);
      assert.equal(
        result.semanticFacts.some(
          // retain the reviewed trap continuation
          (fact) => fact.site.path === path
            && fact.factKind === "call"
            && fact.attributes.identifier === "source"
            && fact.site.startUtf16 === sourceStart
            && fact.site.endUtf16 === sourceStart + sourceCommand.length,
        ),
        true,
        name,
      );
    }
  },
);

const SHELL_SUBSTITUTION_COUNTER_SCRIPT = String.raw`
import { readFileSync } from "node:fs";

// summarize one closed counter failure
function failureSummary(error) {
  const code = ["frontend.bound-exceeded", "frontend.invalid-output"].includes(
    error?.code,
  )
    ? error.code
    : "test-harness.unexpected-error";
  return {
    code,
    messageMatchesCode: error?.message === code,
    stage: error?.stage === "frontend-bootstrap"
      ? error.stage
      : "test-harness",
  };
}

// run one isolated substitution counter
async function main() {
  const payload = JSON.parse(readFileSync(0, "utf8"));
  const frontend = await import(payload.frontendModuleUrl);
  const sliceDescriptor = Object.getOwnPropertyDescriptor(
    String.prototype,
    "slice",
  );
  const startsWithDescriptor = Object.getOwnPropertyDescriptor(
    String.prototype,
    "startsWith",
  );
  const OriginalStringIncludes = String.prototype.includes;
  const OriginalStringIndexOf = String.prototype.indexOf;
  const OriginalStringSlice = sliceDescriptor?.value;
  const OriginalStringStartsWith = startsWithDescriptor?.value;
  // require exact writable builtin descriptors
  if (
    sliceDescriptor === undefined ||
    startsWithDescriptor === undefined ||
    typeof OriginalStringSlice !== "function" ||
    typeof OriginalStringStartsWith !== "function"
  ) {
    throw new Error("test-harness.descriptor-missing");
  }
  let counters = {
    sentinelSliceCalls: 0,
    sentinelSliceReturnedUnits: 0,
    substitutionStartsWithProbes: 0,
  };

  // identify one sentinel-bearing string
  function hasSentinel(value) {
    const text = String(value);
    return Reflect.apply(
      OriginalStringIncludes,
      text,
      [payload.sentinel],
    ) && Reflect.apply(
      OriginalStringIndexOf,
      text,
      [payload.sentinel],
    ) >= 0;
  }

  // count one sentinel-preserving slice
  function countedSlice(start, end) {
    const receiver = String(this);
    const result = Reflect.apply(
      OriginalStringSlice,
      receiver,
      [start, end],
    );
    // count only overlapping fixture materialization
    if (hasSentinel(receiver) && hasSentinel(result)) {
      counters.sentinelSliceCalls += 1;
      counters.sentinelSliceReturnedUnits += result.length;
    }
    return result;
  }

  // count one substitution scanner probe
  function countedStartsWith(searchString, position) {
    const receiver = String(this);
    const probe = String(searchString);
    // count only exact substitution open probes
    if (
      hasSentinel(receiver) &&
      (probe === "$(" || probe === "$((")
    ) {
      counters.substitutionStartsWithProbes += 1;
    }
    return Reflect.apply(
      OriginalStringStartsWith,
      receiver,
      [searchString, position],
    );
  }

  Object.defineProperty(String.prototype, "slice", {
    ...sliceDescriptor,
    value: countedSlice,
  });
  Object.defineProperty(String.prototype, "startsWith", {
    ...startsWithDescriptor,
    value: countedStartsWith,
  });

  let analysis = null;
  let calibration = null;
  let capturedError = null;
  let counterSnapshot = null;
  // always restore exact builtin descriptors
  try {
    const calibrationText = "prefix" + payload.sentinel + "suffix";
    calibrationText.slice(6, 6 + payload.sentinel.length);
    calibrationText.startsWith("$(", 0);
    calibrationText.startsWith("$((", 0);
    calibration = { ...counters };
    counters = {
      sentinelSliceCalls: 0,
      sentinelSliceReturnedUnits: 0,
      substitutionStartsWithProbes: 0,
    };
    // capture one isolated public result
    try {
      analysis = await frontend.analyzeBackendNonmoduleSourcesBatch({
        sources: [payload.source],
      });
      counterSnapshot = { ...counters };
    // capture one closed analyzer failure
    } catch (error) {
      counterSnapshot = { ...counters };
      capturedError = error;
    }
  } finally {
    Object.defineProperty(String.prototype, "slice", sliceDescriptor);
    Object.defineProperty(
      String.prototype,
      "startsWith",
      startsWithDescriptor,
    );
  }

  // emit one sanitized failed outcome
  if (capturedError !== null || analysis === null) {
    process.stdout.write(JSON.stringify({
      calibration,
      counters: counterSnapshot,
      ...failureSummary(capturedError),
      ok: false,
    }));
    return;
  }

  const calls = analysis.semanticFacts.filter(
    // retain one fixture call fact
    (fact) => fact.site.path === payload.source.path && fact.factKind === "call",
  );
  const callIds = new Set(calls.map(
    // project one fixture call id
    (fact) => fact.factId,
  ));
  let ownedCallEdgeCount = 0;
  // count every direct call owner
  for (const fact of analysis.semanticFacts) {
    // inspect every direct child edge
    for (const edge of fact.childEdges) {
      // count one body-owned nested call
      if (edge.role === "body" && callIds.has(edge.childFactId)) {
        ownedCallEdgeCount += 1;
      }
    }
  }
  process.stdout.write(JSON.stringify({
    bindingFactCount: analysis.semanticFacts.filter(
      // count one fixture binding
      (fact) => fact.site.path === payload.source.path && fact.factKind === "binding",
    ).length,
    calibration,
    callFactCount: calls.length,
    clockOccurrenceCount: analysis.occurrences.filter(
      // count one direct date candidate
      (occurrence) => occurrence.sourceLocator === payload.source.path &&
        occurrence.surface === "shell.date" &&
        occurrence.countsAsClockCandidate === true,
    ).length,
    counters: counterSnapshot,
    dateCallCount: calls.filter(
      // count one direct date call
      (fact) => fact.attributes.identifier === "date",
    ).length,
    derivedSourceCount: analysis.derivedSources.length,
    diagnosticCount: analysis.diagnostics.length,
    occurrenceCount: analysis.occurrences.length,
    ok: true,
    ownedCallEdgeCount,
    printfCallCount: calls.filter(
      // count one reviewed printf call
      (fact) => fact.attributes.identifier === "printf",
    ).length,
  }));
}

main().catch(
  // emit one closed harness failure
  () => process.stdout.write(JSON.stringify({
    code: "test-harness.unexpected-error",
    messageMatchesCode: false,
    ok: false,
    stage: "test-harness",
  })),
);
`;

// run one bounded substitution counter
function runShellSubstitutionCounterScenario(source, sentinel) {
  const run = spawnSync(
    "/bin/sh",
    [
      "-c",
      "ulimit -c 0 || exit 125\nexec \"$@\"",
      "weather-shell-substitution-counter",
      process.execPath,
      "--max-old-space-size=128",
      "--input-type=module",
      "-e",
      SHELL_SUBSTITUTION_COUNTER_SCRIPT,
    ],
    {
      cwd: REPOSITORY_ROOT,
      encoding: "utf8",
      input: JSON.stringify({
        frontendModuleUrl: FRONTEND_MODULE_URL,
        sentinel,
        source,
      }),
      killSignal: "SIGKILL",
      maxBuffer: 1024 * 1024,
      timeout: 15_000,
    },
  );
  let summary = null;
  // parse only one closed successful summary
  if (run.error === undefined && run.status === 0) {
    // decode one bounded counter result
    try {
      summary = JSON.parse(run.stdout);
    } catch {
      summary = null;
    }
  }
  return {
    signal: run.signal,
    spawnFailed: run.error !== undefined,
    status: run.status,
    stderrBytes: Buffer.byteLength(run.stderr ?? "", "utf8"),
    stdoutBytes: Buffer.byteLength(run.stdout ?? "", "utf8"),
    summary,
  };
}

test(
  "shell nested command substitution scanning stays source-linear",
  // verify substitution work stays linear
  () => {
    const sentinel = "substitution_probe_9d17c6";
    const depths = [0, 32, 64];
    const summaries = [];
    // isolate every substitution depth
    for (const depth of depths) {
      let command = `printf %s ${sentinel}; date -u +%s`;
      // wrap one additional command substitution
      for (let index = 0; index < depth; index += 1) {
        command = `printf %s $(${command})`;
      }
      const source = physicalSource(
        "shell",
        `fixture/nested-substitution-${depth}.sh`,
        `capture=$(${command})\n`,
      );
      assert.equal(source.sourceText.length < 4096, true);
      const run = runShellSubstitutionCounterScenario(source, sentinel);
      assert.equal(run.spawnFailed, false);
      assert.equal(run.status, 0);
      assert.equal(run.signal, null);
      assert.equal(run.stderrBytes, 0);
      assert.equal(run.stdoutBytes < 1024 * 1024, true);
      assert.notEqual(run.summary, null);
      assert.equal(run.summary.ok, true);
      assert.deepEqual(run.summary.calibration, {
        sentinelSliceCalls: 1,
        sentinelSliceReturnedUnits: sentinel.length,
        substitutionStartsWithProbes: 2,
      });
      assert.equal(run.summary.bindingFactCount, 1);
      assert.equal(run.summary.callFactCount, depth + 2);
      assert.equal(run.summary.printfCallCount, depth + 1);
      assert.equal(run.summary.dateCallCount, 1);
      assert.equal(run.summary.clockOccurrenceCount, 1);
      assert.equal(run.summary.occurrenceCount, 1);
      assert.equal(run.summary.diagnosticCount, 0);
      assert.equal(run.summary.derivedSourceCount, 0);
      assert.equal(run.summary.ownedCallEdgeCount, depth + 2);
      summaries.push(run.summary);
    }
    const counterKeys = [
      "sentinelSliceCalls",
      "sentinelSliceReturnedUnits",
      "substitutionStartsWithProbes",
    ];
    // require monotone source-linear work
    for (const key of counterKeys) {
      const first = summaries[0].counters[key];
      const second = summaries[1].counters[key];
      const third = summaries[2].counters[key];
      assert.equal(Number.isSafeInteger(first) && first >= 0, true);
      assert.equal(Number.isSafeInteger(second) && second >= first, true);
      assert.equal(Number.isSafeInteger(third) && third >= second, true);
      const firstDelta = second - first;
      const secondDelta = third - second;
      assert.equal(secondDelta <= firstDelta * 2, true);
    }
  },
);

