        assert.equal(isolated.responseCursor, 0, mode);
        assert.equal(isolated.passiveChildCloseEmits, 1, mode);
        assert.equal(isolated.passiveExitClass, "literal-bound", mode);
        assert.equal(isolated.passiveStdoutBytes, 0, mode);
        assert.equal(isolated.passiveStderrBytes, 0, mode);
        assert.equal(isolated.passiveRetainedChunkCount, 0, mode);
        assert.equal(isolated.rawResponse, null, mode);
        assert.equal(isolated.rawStdoutBytes, 0, mode);
        assert.equal(isolated.rawStdoutSha256, null, mode);
        assert.equal(isolated.fixedPassive.mode, mode);
        assert.equal(isolated.fixedPassive.payloadBytes, 5_000, mode);
        assert.match(isolated.fixedPassive.payloadSha256, /^[0-9a-f]{64}$/u);
        assert.match(isolated.fixedPassive.sourceSha256, /^[0-9a-f]{64}$/u);
        assert.equal(isolated.firstCall.executableMatches, true, mode);
