// build one closed synthetic scope route expectation
function v10ScopeRouteExpectation(source, nodes, gap, ownerSymbol) {
  const facts = v10ExpectedHelperFacts(source, nodes);
  const selectedFacts = facts.filter(
    // retain the exact reviewed fact kinds
    (fact) => fact.factKind === "function" || fact.factKind === "call",
  );
  const callNode = nodes.find(
    // locate one exact call tuple
    (node) => node[1] === "call",
  );
  assert.notEqual(callNode, undefined);
  const callStart = v10HelperOffset(source.sourceText, callNode[2], callNode[3]);
  const occurrence = gap
    ? null
    : v10PythonNowOccurrence(source, callStart, ownerSymbol);
  return {
    diagnosticJson: gap ? canonicalJson(V10_UNSUPPORTED_DIAGNOSTIC) : null,
    factJsons: selectedFacts.map(
      // serialize one independent complete fact
      (fact) => canonicalJson(fact),
    ),
    kind: "python-scope-route",
    occurrenceJson: occurrence === null ? null : canonicalJson(occurrence),
    semanticFactCount: facts.length,
  };
}

// assert one closed synthetic scope route run
function v10AssertScopeRouteRun(source, nodes, expectation) {
  v10ValidateHelperNodes(source, nodes);
  const isolated = runIsolatedFrontendScenario({
    attempts: [{ expectation, sources: [source] }],
    responses: [{ stderr: "", stdout: helperResponse(source, nodes) }],
  });
  assert.deepEqual(
    [isolated.calls, isolated.originalCalls, isolated.forbiddenTransportCalls],
    [1, 0, 0],
    "transport-custody",
  );
  assert.equal(isolated.responseCursor, 1, "response-count");
  assert.equal(isolated.fixedPassive, null, "passive-fixture");
  assert.equal(isolated.passiveChildCloseEmits, 0, "passive-close-count");
  assert.equal(isolated.passiveStdoutBytes, 0, "passive-stdout-count");
  assert.equal(isolated.passiveStderrBytes, 0, "passive-stderr-count");
  assert.equal(isolated.rawResponse, null, "raw-response");
  assert.equal(isolated.rawStdoutBytes, 0, "raw-bytes");
  assert.equal(isolated.rawStdoutSha256, null, "raw-digest");
  assert.equal(isolated.passiveRetainedChunkCount, 0, "retained-chunks");
  assert.equal(isolated.outcomes.length, 1, "outcome-count");
  assert.equal(isolated.outcomes[0].closedAtSettlement, true, "closed-settlement");
  assert.equal(isolated.outcomes[0].ok, true, "outcome-ok");
  assert.equal(isolated.syntheticCalls.length, 1, "synthetic-count");
  assertSyntheticCloseGate(isolated);
  const transport = isolated.syntheticCalls[0];
  assert.equal(transport.childCloseEmits, 1, "child-close-count");
  assert.equal(transport.closeCodeClass, "clean", "child-close-class");
  assert.equal(transport.closeSignalPresent, false, "child-close-signal");
  assert.equal(transport.killCalls, 0, "child-kill-count");
  assert.equal(transport.stdinBufferIsBuffer, true, "stdin-buffer");
  assert.equal(transport.stdinEndCalls, 1, "stdin-end-count");
  assert.equal(transport.stdinWriteCalls, 0, "stdin-write-count");
  assert.equal(transport.stdinBytes > 0, true, "stdin-byte-count");
  assert.match(transport.stdinSha256, /^[0-9a-f]{64}$/u, "stdin-digest");
  assert.equal(transport.streamsClosedAtChildClose, true, "closed-streams");
  assert.equal(isolated.firstCall.executableMatches, true, "fixed-executable");
  assert.equal(isolated.firstCall.argsHeadMatches, true, "fixed-argv");
  assert.equal(isolated.firstCall.argsLength, 5, "fixed-argv-count");
  assert.equal(isolated.firstCall.cwdMatches, true, "fixed-cwd");
  assert.equal(isolated.firstCall.envMatches, true, "fixed-env");
  assert.equal(isolated.firstCall.shellMatches, true, "fixed-shell");
  assert.equal(isolated.firstCall.stdioMatches, true, "fixed-stdio");
  const summary = isolated.outcomes[0].summary;
  const expectedFacts = expectation.factJsons.map(
    // parse one exact private expectation locally
    (factJson) => JSON.parse(factJson),
  );
  const expectedDiagnostics = expectation.diagnosticJson === null
    ? []
    : [JSON.parse(expectation.diagnosticJson)];
  const expectedOccurrences = expectation.occurrenceJson === null
    ? []
    : [JSON.parse(expectation.occurrenceJson)];
  assert.deepEqual(Object.keys(summary), [
    "aliasFactId",
    "aliasFactMatches",
    "conversionFactMatches",
    "conversionOperatorsEmpty",
    "derivedSourceCount",
    "diagnosticCount",
    "occurrenceCount",
    "semanticFactCount",
    "scopeCallCount",
    "scopeDiagnosticDigest",
    "scopeDiagnosticMatches",
    "scopeFactCount",
    "scopeFactDigest",
    "scopeFactMatches",
    "scopeFunctionCount",
    "scopeOccurrenceDigest",
    "scopeOccurrenceMatches",
    "scopeSemanticCountMatches",
  ]);
  assert.equal(summary.scopeCallCount, 1, "selected-call-count");
  assert.equal(summary.scopeFunctionCount, expectedFacts.length - 1, "function-count");
  assert.equal(summary.scopeFactCount, expectedFacts.length, "selected-fact-count");
  assert.equal(summary.scopeFactMatches, true, "fact-match");
  assert.equal(summary.scopeDiagnosticMatches, true, "diagnostic-match");
  assert.equal(summary.scopeOccurrenceMatches, true, "occurrence-match");
  assert.equal(summary.scopeSemanticCountMatches, true, "semantic-count-match");
  assert.equal(
    summary.scopeFactDigest,
    sha256(Buffer.from(canonicalJson(expectedFacts), "utf8")),
    "fact-digest",
  );
  assert.equal(
    summary.scopeDiagnosticDigest,
    sha256(Buffer.from(canonicalJson(expectedDiagnostics), "utf8")),
    "diagnostic-digest",
  );
  assert.equal(
    summary.scopeOccurrenceDigest,
    sha256(Buffer.from(canonicalJson(expectedOccurrences), "utf8")),
    "occurrence-digest",
  );
}

test(
  "Python indexed bindings preserve ordered and stable lookup semantics",
  // verify exact indexed binding semantics
  async (context) => {
    const sizes = [0, 32, 64];
    // isolate each repeated import and call family
    for (const size of sizes) {
      await context.test(
        `repeated identical imports and calls size ${size}`,
        // verify one bounded repeated history
        async () => {
          const path = `fixture/python-v10-repeated-${size}.py`;
          const lines = ["import datetime as dt"];
          // append every identical binding
          for (let index = 0; index < size; index += 1) {
            lines.push("import datetime as dt");
          }
          // append every exact demand
          for (let index = 0; index <= size; index += 1) {
            lines.push("dt.datetime.now()");
          }
          lines.push("");
          const source = physicalSource("python", path, lines.join("\n"));
          const callStarts = v10NeedleOffsets(source.sourceText, "dt.datetime.now()");
          const expected = callStarts.map(
            // build one duplicate-aware clock record
            (start, index) => v10PythonNowOccurrence(source, start, "<module>", index + 1),
          );
          const result = await analyzeBackendNonmoduleSourcesBatch({ sources: [source] });
          v10AssertPythonProjection(result, source, expected, callStarts, false);
          assert.equal(factsOf(result, "import").length, size + 1);
          assert.equal(factsOf(result, "call").length, size + 1);
        },
      );
    }

    // isolate each deep conditional ancestry family
    for (const size of sizes) {
      await context.test(
        `conditional ancestry size ${size}`,
        // verify one bounded conditional route
        async () => {
          const path = `fixture/python-v10-conditional-depth-${size}.py`;
          const lines = ["import datetime as dt"];
          // open every nested conditional
          for (let index = 0; index < size; index += 1) {
            lines.push(`${"    ".repeat(index)}if flag_${index}:`);
          }
          // add one conditional binding only inside a real ancestry
          if (size > 0) {
            lines.push(`${"    ".repeat(size)}dt = fake`);
          }
          lines.push("dt.datetime.now()", "");
          const source = physicalSource("python", path, lines.join("\n"));
          const callStart = source.sourceText.indexOf("dt.datetime.now()");
          const expected = size === 0
            ? [v10PythonNowOccurrence(source, callStart)]
            : [];
          const result = await analyzeBackendNonmoduleSourcesBatch({ sources: [source] });
          v10AssertPythonProjection(
            result,
            source,
            expected,
            [callStart],
            size > 0,
          );
          assert.equal(factsOf(result, "control").length, size + 1);
        },
      );
    }

    const cases = [
      {
        expectedOwner: "<module>",
        gap: false,
        name: "earlier direct call precedes a later write",
        path: "fixture/python-v10-earlier-direct.py",
        sourceText: "import datetime as dt\ndt.datetime.now()\ndt = fake\n",
      },
      {
        gap: true,
        name: "future outer write blocks a nested free name",
        path: "fixture/python-v10-future-outer.py",
        sourceText: "import datetime as dt\ndef sample():\n    dt.datetime.now()\ndt = fake\n",
      },
      {
        expectedOwner: "right",
        gap: false,
        name: "sibling local writes do not leak",
        path: "fixture/python-v10-sibling-write.py",
        sourceText: [
          "import datetime as dt",
          "def left():",
          "    dt = fake",
          "def right():",
          "    dt.datetime.now()",
          "",
        ].join("\n"),
      },
      {
        expectedOwner: "sample",
        gap: false,
        name: "default expressions retain enclosing evaluation order",
        path: "fixture/python-v10-default-scope.py",
        sourceText: "import datetime as dt\ndef sample(value=dt.datetime.now()):\n    pass\ndt = fake\n",
        syntaxKind: "python-default-argument",
      },
      {
        gap: true,
        name: "preceding wildcard blocks direct authority",
        path: "fixture/python-v10-prior-wildcard.py",
        sourceText: "import datetime as dt\nfrom unknown import *\ndt.datetime.now()\n",
      },
      {
        expectedOwner: "<module>",
        gap: false,
        name: "later exact import recovers after wildcard",
        path: "fixture/python-v10-wildcard-reimport.py",
        sourceText: "from unknown import *\nimport datetime as dt\ndt.datetime.now()\n",
      },
      {
        gap: true,
        name: "future wildcard blocks a nested free name",
        path: "fixture/python-v10-future-wildcard.py",
        sourceText: "import datetime as dt\ndef sample():\n    dt.datetime.now()\nfrom unknown import *\n",
      },
      {
        gap: true,
        name: "conditional future binding remains unstable",
        path: "fixture/python-v10-conditional-future.py",
        sourceText: "import datetime as dt\nif flag:\n    dt = fake\ndt.datetime.now()\n",
      },
      {
        expectedOwner: "<module>",
        gap: false,
        name: "same-statement chained writes retain later import order",
        path: "fixture/python-v10-chained-reimport.py",
        sourceText: "import datetime as dt\ndt = alias = fake\nimport datetime as dt\ndt.datetime.now()\n",
      },
      {
        gap: true,
        name: "destructuring writes invalidate earlier authority",
        path: "fixture/python-v10-destructuring.py",
        sourceText: "import datetime as dt\ndt, other = pair\ndt.datetime.now()\n",
      },
    ];
    // isolate each exact source-order case
    for (const scenario of cases) {
      await context.test(
        scenario.name,
        // verify one exact ordered lookup
        async () => {
          const source = physicalSource(
            "python",
            scenario.path,
            scenario.sourceText,
          );
          const callStart = source.sourceText.indexOf("dt.datetime.now()");
          assert.equal(callStart >= 0, true);
          const expected = scenario.gap
            ? []
            : [v10PythonNowOccurrence(
              source,
              callStart,
              scenario.expectedOwner,
              1,
              scenario.syntaxKind,
            )];
          const result = await analyzeBackendNonmoduleSourcesBatch({ sources: [source] });
          v10AssertPythonProjection(
            result,
            source,
            expected,
            [callStart],
            scenario.gap,
          );
        },
      );
    }

    await context.test(
      "unrelated exact time alias stays resolved other",
      // verify one nonprovider exact path
      async () => {
        const path = "fixture/python-v10-unrelated-time.py";
        const sourceText = "import unrelated as time\ntime.time()\n";
        const source = physicalSource("python", path, sourceText);
        const callStart = sourceText.indexOf("time.time()");
        const result = await analyzeBackendNonmoduleSourcesBatch({ sources: [source] });
        v10AssertPythonProjection(result, source, [], [callStart], false);
        const alias = factsOf(result, "alias").find(
          // locate one exact unrelated alias
          (fact) => fact.site.path === path,
        );
        assert.notEqual(alias, undefined);
        assert.equal(alias.attributes.identifier, '["unrelated","time"]');
      },
    );
  },
);

test(
  "Python indexed member invalidations preserve lexical prefix boundaries",
  // verify exact indexed member boundaries
  async (context) => {
    const sizes = [0, 32, 64];
    // isolate each benign member prefix family
    for (const size of sizes) {
      await context.test(
        `benign member writes size ${size}`,
        // verify one bounded benign prefix family
        async () => {
          const path = `fixture/python-v10-benign-members-${size}.py`;
          const lines = ["import datetime as dt"];
          // append each unrelated member write and demand
          for (let index = 0; index < size; index += 1) {
            lines.push(`dt.cache_${index} = fake`);
            lines.push("dt.datetime.now()");
          }
          lines.push("dt.datetime.now()", "");
          const source = physicalSource("python", path, lines.join("\n"));
          const callStarts = v10NeedleOffsets(source.sourceText, "dt.datetime.now()");
          const expected = callStarts.map(
            // build one benign member occurrence
            (start, index) => v10PythonNowOccurrence(source, start, "<module>", index + 1),
          );
          const result = await analyzeBackendNonmoduleSourcesBatch({ sources: [source] });
          v10AssertPythonProjection(result, source, expected, callStarts, false);
          assert.equal(factsOf(result, "binding").length, size);
        },
      );
    }

    const cases = [
      {
        gap: true,
        name: "relevant endpoint prefix blocks now",
        path: "fixture/python-v10-member-relevant.py",
        sourceText: "import datetime as dt\ndt.datetime = fake\ndt.datetime.now()\n",
      },
      {
        gap: false,
        name: "deeper endpoint member does not block now",
        path: "fixture/python-v10-member-deeper.py",
        sourceText: "import datetime as dt\ndt.datetime.now.extra = fake\ndt.datetime.now()\n",
      },
      {
        gap: true,
        name: "later broader write survives an earlier deeper write",
        path: "fixture/python-v10-member-deeper-then-broader.py",
        sourceText: [
          "import datetime as dt",
          "dt.datetime.now.extra = fake",
          "dt.datetime = fake",
          "dt.datetime.now()",
          "",
        ].join("\n"),
      },
      {
        gap: true,
        name: "future outer member write blocks nested free authority",
        path: "fixture/python-v10-member-future-outer.py",
        sourceText: [
          "import datetime as dt",
          "def sample():",
          "    dt.datetime.now()",
          "dt.datetime = fake",
          "",
        ].join("\n"),
      },
      {
        gap: false,
        name: "sibling member writes do not leak",
        owner: "right",
        path: "fixture/python-v10-member-sibling.py",
        sourceText: [
          "import datetime as dt",
          "def left():",
          "    dt.datetime = fake",
          "def right():",
          "    dt.datetime.now()",
          "",
        ].join("\n"),
      },
    ];
    // isolate each member prefix boundary
    for (const scenario of cases) {
      await context.test(
        scenario.name,
        // verify one exact prefix decision
        async () => {
          const source = physicalSource(
            "python",
            scenario.path,
            scenario.sourceText,
          );
          const callStart = source.sourceText.lastIndexOf("dt.datetime.now()");
          const expected = scenario.gap
            ? []
            : [v10PythonNowOccurrence(
              source,
              callStart,
              scenario.owner ?? "<module>",
            )];
          const result = await analyzeBackendNonmoduleSourcesBatch({ sources: [source] });
          v10AssertPythonProjection(
            result,
            source,
            expected,
            [callStart],
            scenario.gap,
          );
        },
      );
    }

    await context.test(
      "one datetime prefix blocks both now and today",
      // verify one shared provider prefix
      async () => {
        const path = "fixture/python-v10-member-now-today.py";
        const sourceText = [
          "import datetime as dt",
          "dt.datetime = fake",
          "dt.datetime.now()",
          "dt.datetime.today()",
          "",
        ].join("\n");
        const source = physicalSource("python", path, sourceText);
        const starts = [
          sourceText.indexOf("dt.datetime.now()"),
          sourceText.indexOf("dt.datetime.today()"),
        ];
        const result = await analyzeBackendNonmoduleSourcesBatch({ sources: [source] });
        v10AssertPythonProjection(result, source, [], starts, true);
      },
    );

    await context.test(
      "same-position chained member writes remain stable",
      // verify one tied member admission order
      async () => {
        const path = "fixture/python-v10-member-tied.py";
        const sourceText = [
          "import datetime as dt",
          "dt.datetime = dt.date = fake",
          "dt.datetime.now()",
          "dt.date.today()",
          "",
        ].join("\n");
        const source = physicalSource("python", path, sourceText);
        const starts = [
          sourceText.indexOf("dt.datetime.now()"),
          sourceText.indexOf("dt.date.today()"),
        ];
        const result = await analyzeBackendNonmoduleSourcesBatch({ sources: [source] });
        v10AssertPythonProjection(result, source, [], starts, true);
      },
    );
  },
);

