test(
  "Python resolver uses bounded indexed work instead of demand history scans",
  // verify the indexed resolver ownership shape
  async () => {
    const moduleSource = await readFile(
      new URL("./backend-nonmodule-source-analysis.mjs", import.meta.url),
      "utf8",
    );
    const start = moduleSource.indexOf("function resolvePythonSemantics(");
    const end = moduleSource.indexOf("// create one native occurrence draft", start);
    assert.equal(start >= 0 && end > start, true, "resolver-region");
    const resolver = moduleSource.slice(start, end);
    const forbidden = [
      [/history\.sort\(/u, "per-cell-history-sort"],
      [/scope\.wildcards\.sort\(/u, "per-scope-wildcard-sort"],
      [/for \(const binding of history\)/u, "per-demand-history-scan"],
      [/scope\.wildcards\.findLast\(/u, "per-demand-wildcard-scan"],
      [/for \(const invalidation of entry\.scope\.invalidations\)/u,
        "per-demand-invalidation-scan"],
      [/while \(current !== null\)/u, "per-demand-parent-scan"],
      [/history\.some\(/u, "per-demand-history-probe"],
      [/pendingMemberWrites\.sort\(/u, "member-write-comparator-sort"],
      [/collectPythonSubtree\(/u, "default-subtree-rescan"],
      [/helperPath\(/u, "recursive-path-rebuild"],
      [/raw\.split\("\."\)/u, "per-demand-path-split"],
    ];
    // forbid every reviewed demand-multiplied shape
    for (const [pattern, label] of forbidden) {
      assert.equal(pattern.test(resolver), false, label);
    }
  },
);

// assert one exact arbitrary-prefix fixture
async function v10AssertOtherPrefixCase({
  aliases,
  bindingNeedles,
  callNeedles,
  expectedFactCount,
  expectedRawSha256 = null,
  gap,
  path,
  sourceText,
}) {
  const source = physicalSource("python", path, sourceText);
  // retain one independently frozen fixture digest
  if (expectedRawSha256 !== null) {
    assert.equal(source.rawSha256, expectedRawSha256, "source-digest");
  }
  const callStarts = callNeedles.flatMap(
    // locate every exact call spelling
    (needle) => v10NeedleOffsets(sourceText, needle),
  ).sort(
    // order one call position
    (left, right) => left - right,
  );
  assert.equal(callStarts.length, callNeedles.length, "call-cardinality");
  const result = await analyzeBackendNonmoduleSourcesBatch({ sources: [source] });
  v10AssertPythonProjection(result, source, [], callStarts, gap);
  assert.equal(result.semanticFacts.length, expectedFactCount, "fact-count");
  const pathFacts = result.semanticFacts.filter(
    // retain one arbitrary-prefix fixture
    (fact) => fact.site.path === path,
  );
  const importStarts = v10NeedleOffsets(sourceText, "import ");
  const actualImportStarts = pathFacts.filter(
    // retain every positioned import fact
    (fact) => fact.factKind === "import",
  ).map(
    // project one import start
    (fact) => fact.site.startUtf16,
  );
  assert.equal(
    sha256(Buffer.from(canonicalJson(actualImportStarts), "utf8")),
    sha256(Buffer.from(canonicalJson(importStarts), "utf8")),
    "import-spans",
  );
  const expectedBindingStarts = bindingNeedles.flatMap(
    // locate every exact binding spelling
    (needle) => v10NeedleOffsets(sourceText, needle),
  ).sort(
    // order one binding position
    (left, right) => left - right,
  );
  assert.equal(
    expectedBindingStarts.length,
    bindingNeedles.length,
    "binding-cardinality",
  );
  // retain every required binding position
  for (const bindingStart of expectedBindingStarts) {
    assert.equal(
      pathFacts.some(
        // locate one positioned binding fact
        (fact) => fact.factKind === "binding"
          && fact.site.startUtf16 === bindingStart,
      ),
      true,
      "binding-span",
    );
  }
  const actualAliases = pathFacts.filter(
    // retain every exact alias fact
    (fact) => fact.factKind === "alias",
  ).map(
    // project one alias identifier
    (fact) => fact.attributes.identifier,
  ).sort(compareText);
  const expectedAliases = [...aliases].sort(compareText);
  assert.equal(
    sha256(Buffer.from(canonicalJson(actualAliases), "utf8")),
    sha256(Buffer.from(canonicalJson(expectedAliases), "utf8")),
    "alias-facts",
  );
}

// build one arbitrary-prefix breadth fixture
function v10OtherPrefixBreadthSource(size, mutated) {
  const lines = ["import datetime as dt"];
  const aliases = ['["datetime","dt"]'];
  const callNeedles = [];
  const bindingNeedles = [];
  // append every unrelated exact member path
  for (let index = 0; index < size; index += 1) {
    lines.push(`import package_${index} as other_${index}`);
    lines.push(`other_${index}.branch = fake`);
    lines.push(`other_${index}.value()`);
    aliases.push(`["package_${index}","other_${index}"]`);
    bindingNeedles.push(`other_${index}.branch = fake`);
    callNeedles.push(`other_${index}.value()`);
  }
  lines.push("import collections as dt");
  aliases.push('["collections","dt"]');
  // append one historical-provider mutation
  if (mutated) {
    lines.push("dt.datetime = fake");
    bindingNeedles.push("dt.datetime = fake");
  }
  lines.push("dt.datetime.now()", "");
  callNeedles.push("dt.datetime.now()");
  return {
    aliases,
    bindingNeedles,
    callNeedles,
    expectedFactCount: 10 * size + (mutated ? 13 : 9),
    sourceText: lines.join("\n"),
  };
}

// build one arbitrary-prefix depth fixture
function v10OtherPrefixDepthSource(size, mutated) {
  const moduleName = [
    "package",
    ...Array.from(
      { length: size },
      // create one exact path segment
      (_, index) => `segment_${index}`,
    ),
  ].join(".");
  const lines = [
    "import datetime as dt",
    `import ${moduleName} as dt`,
  ];
  const bindingNeedles = [];
  // append one deep exact-path mutation
  if (mutated) {
    lines.push("dt.datetime = fake");
    bindingNeedles.push("dt.datetime = fake");
  }
  lines.push("dt.datetime.now()", "");
  return {
    aliases: ["[\"datetime\",\"dt\"]", `["${moduleName}","dt"]`],
    bindingNeedles,
    callNeedles: ["dt.datetime.now()"],
    expectedFactCount: mutated ? 13 : 9,
    sourceText: lines.join("\n"),
  };
}

