// build one full recursive python time-call tree
function v11PythonTimeTree(levels) {
  const children = [[
    "func",
    0,
    [
      "attribute",
      "time",
      null,
      null,
      ["context.load"],
      [[
        "value",
        0,
        ["name", "time", null, null, ["context.load"], []],
      ]],
    ],
  ]];
  // retain one nested argument subtree
  if (levels > 1) {
    children.push(["args", 0, v11PythonTimeTree(levels - 1)]);
  }
  return ["call", null, null, null, [], children];
}

// build one nested time expression
function v11NestedTimeExpression(levels) {
  let expression = "time.time()";
  // wrap every additional provider root
  for (let index = 1; index < levels; index += 1) {
    expression = `time.time(${expression})`;
  }
  return expression;
}

// build one exact nested python occurrence
function v11PythonTimeOccurrence(source, startOffsetUtf16, endOffsetUtf16, levels) {
  const normalizedExpressionSha256 = frame("weather-clock-expression/v2", {
    language: "python",
    normalization: "python-helper-tree/v1",
    value: v11PythonTimeTree(levels),
  });
  const preimage = {
    confidence: "expanded-direct",
    container: null,
    countsAsClockCandidate: true,
    duplicateOrdinal: 1,
    extractorOrigin: null,
    identityVersion: "union-v2",
    kind: "current-time-read",
    language: "python",
    normalizedExpressionSha256,
    ownerSymbol: "<module>",
    parentOccurrenceId: null,
    sourceLocator: source.path,
    span: v10OccurrenceSpan(source.sourceText, startOffsetUtf16, endOffsetUtf16),
    surface: "python.time-time",
    syntaxKind: "python-call",
  };
  return {
    ...preimage,
    id: `clock-occurrence-v2:${frame("weather-clock-occurrence/v2", preimage)}`,
  };
}

// verify one exact nested provider family
async function v11AssertNestedPythonProviders(size) {
  const levels = size + 1;
  const expression = v11NestedTimeExpression(levels);
  const prefix = "import time\nvalue = ";
  const source = physicalSource(
    "python",
    `fixture/python-v11-nested-time-${size}.py`,
    `${prefix}${expression}\n`,
  );
  const expectedOccurrences = [];
  const callStarts = [];
  // build every full recursive provider preimage
  for (let index = 0; index < levels; index += 1) {
    const startOffsetUtf16 = prefix.length + 10 * index;
    const endOffsetUtf16 = prefix.length + 11 * levels - index;
    callStarts.push(startOffsetUtf16);
    expectedOccurrences.push(v11PythonTimeOccurrence(
      source,
      startOffsetUtf16,
      endOffsetUtf16,
      levels - index,
    ));
  }
  const result = await analyzeBackendNonmoduleSourcesBatch({ sources: [source] });
  v10AssertPythonProjection(result, source, expectedOccurrences, callStarts, false);
  assert.equal(result.semanticFacts.length, 3 * levels + 4, "fact-count");
  assert.equal(result.occurrences.length, levels, "provider-count");
}

