// require one exact sanitized frontend gap list
function v11AssertOneUnsupportedGap(result) {
  assert.equal(
    sha256(Buffer.from(canonicalJson(result.diagnostics), "utf8")),
    sha256(Buffer.from(canonicalJson([V10_UNSUPPORTED_DIAGNOSTIC]), "utf8")),
    "diagnostic-dto",
  );
}

// locate one payload fact by private digest
function v11PayloadFact(result, path, payload) {
  const digest = sha256(Buffer.from(payload, "utf8"));
  return result.semanticFacts.find(
    // locate one exact private payload digest
    (fact) => fact.site.path === path
      && fact.factKind === "constant"
      && typeof fact.attributes.literalValue === "string"
      && sha256(Buffer.from(fact.attributes.literalValue, "utf8")) === digest,
  );
}

// verify every private fact identity
function v11AssertFactIdentities(result, path) {
  const facts = result.semanticFacts.filter(
    // retain one fixture fact set
    (fact) => fact.site.path === path,
  );
  // verify every exact fact id
  for (const fact of facts) {
    const { factId, ...preimage } = fact;
    assert.equal(factId, frame("weather-backend-semantic-fact/v1", preimage), "fact-id");
  }
}

// verify one invalid emitted-owner projection
function v11AssertInvalidOwnerRoots(result, source, payload) {
  assert.equal(result.analysisProfile.pythonHelperCalls, 1, "helper-count");
  v11AssertOneUnsupportedGap(result);
  assert.equal(result.occurrences.length, 0, "occurrence-count");
  assert.equal(result.derivedSources.length, 0, "derived-count");
  const payloadFact = v11PayloadFact(result, source.path, payload);
  assert.notEqual(payloadFact, undefined, "payload-fact");
  assert.equal(payloadFact.attributes.literalRole, "embedded-javascript", "payload-role");
  assert.equal(
    result.semanticFacts.some(
      // retain one exact node invocation fact
      (fact) => fact.site.path === source.path
        && fact.factKind === "call"
        && fact.site.startUtf16 === source.sourceText.indexOf("subprocess.run"),
    ),
    true,
    "node-call-fact",
  );
  v11AssertFactIdentities(result, source.path);
}

// verify one valid owner across both emitted root kinds
function v11AssertValidOwnerRoots(
  result,
  source,
  payload,
  ownerSymbol,
  expectedDiagnosticCount,
) {
  assert.equal(result.diagnostics.length, expectedDiagnosticCount, "diagnostic-count");
  // retain one exact mixed-source gap when requested
  if (expectedDiagnosticCount === 1) {
    v11AssertOneUnsupportedGap(result);
  }
  const custodyProjection = {
    ...result,
    diagnostics: [],
    occurrences: result.occurrences.filter(
      // retain only the valid custody pair
      (occurrence) => occurrence.surface === "container.python-node-e"
        || occurrence.sourceLocator.startsWith("derived:"),
    ),
  };
  assertC7ExactPythonCustody(custodyProjection, source, payload, ownerSymbol);
  const directStart = source.sourceText.lastIndexOf("dt.datetime.now()");
  const expectedDirect = v10PythonNowOccurrence(source, directStart, ownerSymbol);
  const direct = occurrencesOf(result, "python.datetime-now");
  assert.equal(direct.length, 1, "direct-count");
  assert.equal(
    sha256(Buffer.from(canonicalJson(direct[0]), "utf8")),
    sha256(Buffer.from(canonicalJson(expectedDirect), "utf8")),
    "direct-dto",
  );
  assert.equal(result.occurrences.length, 3, "occurrence-count");
  v11AssertFactIdentities(result, source.path);
}

// build one fixed invalid-owner payload
function v11InvalidOwnerPayload(byteLength) {
  const prefix = "/*v11-invalid-owner-private-";
  const suffix = "*/Date.now();";
  const fillerLength = byteLength - Buffer.byteLength(prefix) - Buffer.byteLength(suffix);
  assert.equal(fillerLength >= 0, true, "payload-length-input");
  const payload = `${prefix}${"x".repeat(fillerLength)}${suffix}`;
  assert.equal(Buffer.byteLength(payload, "utf8"), byteLength, "payload-byte-length");
  return payload;
}

