            "at",
            "delete",
            "entries",
            "every",
            "filter",
            "find",
            "fromEntries",
            "get",
            "has",
            "includes",
            "indexOf",
            "isArray",
            "isInteger",
            "join",
            "keys",
            "map",
            "max",
            "min",
            "pop",
            "push",
            "reduce",
            "set",
            "shift",
            "slice",
            "some",
            "sort",
            "splice",
            "unshift",
            "values",
            "test",
